function moodGradient(m){
  if (!m) return 'var(--tile)';
  return 'radial-gradient(circle at 32% 26%, rgba(255,255,255,.95), '+m.color+' 45%, '+(m.color2||m.color)+' 100%)';
}
function moodGradientFlat(m){
  if (!m) return 'var(--tile)';
  return 'linear-gradient(135deg, '+m.color+', '+(m.color2||m.color)+')';
}
