function shadeHexColor(hex, percent){
  var f = parseInt(hex.slice(1),16), R = f>>16, G = (f>>8)&0x00FF, B = f&0x0000FF;
  var p = -percent;
  var cl = function(v){ return Math.max(0, Math.min(255, v)); };
  return '#'+(0x1000000+cl(Math.round((0-R)*p)+R)*0x10000+cl(Math.round((0-G)*p)+G)*0x100+cl(Math.round((0-B)*p)+B)).toString(16).slice(1);
}
