async function rpImport(opts){
  opts = Object.assign({ multiple:false, extensions:['png','jpg','jpeg','webp','gif'], max:1600, prefix:'img' }, opts||{});
  var exts = opts.extensions.map(function(e){ return '.' + e; });
  var accept = exts.join(',') + (opts.extensions.some(function(e){ return /^(png|jpe?g|webp|gif)$/.test(e); }) ? ',image/*' : '') + (opts.extensions.some(function(e){ return /^(mp4|webm|mov)$/.test(e); }) ? ',video/*' : '');
  var files = await PM.media.pick(accept, opts.multiple);
  var out = [];
  for (var i = 0; i < files.length; i++){
    try{ out.push({ path: await PM.media.saveFile(files[i], { max: opts.max, prefix: opts.prefix }), name: files[i].name }); }
    catch(e){ console.error('RP file save failed', e); toast('Файл «' + files[i].name + '» не загрузился: ' + (e && e.message ? e.message : e)); }
  }
  return out;
}

