async function genImgGeminiNative(promptText, cfg, refInlines, refLabels){
  var model = cfg.model;
  var base = imgRstripSlash(String(cfg.endpoint||'').trim() || 'https://generativelanguage.googleapis.com/v1beta').replace(/\/v1beta$/i,'');
  var url = base + '/v1beta/models/' + encodeURIComponent(model) + ':generateContent?key=' + encodeURIComponent(cfg.apiKey);
  var ar = cfg.aspectRatio || '1:1';
  var safety = ['HARM_CATEGORY_HARASSMENT','HARM_CATEGORY_HATE_SPEECH','HARM_CATEGORY_SEXUALLY_EXPLICIT','HARM_CATEGORY_DANGEROUS_CONTENT','HARM_CATEGORY_CIVIC_INTEGRITY'].map(function(c){ return { category:c, threshold:'BLOCK_NONE' }; });
  var parts = [];
  (refInlines||[]).forEach(function(ri, k){
    if (!ri) return;
    var lb = refLabels && refLabels[k];
    if (lb) parts.push({ text: 'Reference image '+(k+1)+' — '+lb+'. Copy this person\'s face, hair color, hairstyle, eye color and piercings exactly; use it for no other person:' });
    parts.push({ inlineData: { mimeType: ri.mimeType, data: ri.data } });
  });
  parts.push({ text: promptText });
  var body = {
    contents: [{ role:'user', parts: parts }],
    generationConfig: { responseModalities:['TEXT','IMAGE'], imageConfig:{ aspectRatio: ar } },
    safetySettings: safety
  };
  var resp = await imgFetchT(url, { method:'POST', headers:{ 'Content-Type':'application/json' }, body: JSON.stringify(body) });
  if (!resp.ok) throw await imgApiErr(resp, url);
  var r = await resp.json();
  var img = imgPickGeminiImage(r);
  if (img) return img;
  if (r.error && (r.error.message || r.error.code != null)) throw new Error('Ошибка провайдера: '+(r.error.message||'')+' (code='+(r.error.code!=null?r.error.code:(r.error.status||'n/a'))+')');
  var pf = r.promptFeedback || r.prompt_feedback;
  if (pf && (pf.blockReason || pf.block_reason)) throw new Error('Цензура: промпт заблокирован ('+(pf.blockReason||pf.block_reason)+')');
  throw new Error('Картинка не пришла: '+JSON.stringify(r).slice(0,240));
}
function naisteraCanon(m){
  m = String(m || 'grok').toLowerCase().replace(/\s+/g, '-');
  if (m.indexOf('grok') >= 0) return 'grok';
  if (m.indexOf('lite') >= 0) return m.replace(/[^a-z0-9.\-]/g, '');
  if (m.indexOf('nano') >= 0 || m.indexOf('banana') >= 0) return 'nano-banana-2';
  if (m.indexOf('novel') >= 0) return 'novelai';
  return m;
}
