async function getCharCard(){
  try{
    var chat = await PM.who.current();
    var summary = chat && chat.characters && chat.characters[0];
    if (!summary) return { facts:'', styleSample:'' };
    var c = null;
    try{ c = await PM.who.character(summary.id); }catch(e){ c = null; }
    if (!c) c = summary;
    var factParts = [];
    if (c.description) factParts.push(String(c.description));
    if (c.personality) factParts.push(String(c.personality));
    if (c.scenario) factParts.push(String(c.scenario));
    var styleParts = [];
    var mesExample = c.mesExample || c.mes_example;
    var firstMes = c.firstMes || c.first_mes;
    if (mesExample) styleParts.push(String(mesExample));
    if (firstMes) styleParts.push(String(firstMes));
    return {
      facts: factParts.join('\n').trim().slice(0, 700),
      styleSample: styleParts.join('\n---\n').trim().slice(0, 700)
    };
  }catch(e){ return { facts:'', styleSample:'' }; }
}
async function getContext(n){
  try{
    var count = await PM.chat.count();
    if (!count) return '';
    var end = count - 1;
    var start = Math.max(0, end - n + 1);
    var msgs = await PM.chat.slice([start, end]);
    return (Array.isArray(msgs)?msgs:[]).map(function(m){
      var role = m.role==='user' ? 'User' : (m.role==='assistant'?'Character':'System');
      var content = String(m.content||'').replace(/<[^>]+>/g,' ').replace(/\s+/g,' ').trim();
      return role+': '+content;
    }).filter(function(l){ return l.length>6; }).join('\n');
  }catch(e){ console.error('RP getContext failed', e); return ''; }
}

function rpNoTags(s){ return typeof s === 'string' ? s.replace(/<(?=[A-Za-z\/!?])/g, '‹') : s; }
function rpTagText(text){ return rpNoTags(stripBrailleNoise(text)); }
function rpSafeUrl(u){ u = String(u || '').trim(); if (!u) return ''; if (/^data:image\/[a-z0-9.+-]+;base64,[A-Za-z0-9+\/=\s]+$/i.test(u)) return u; if (/^(https?:|blob:|file:|content:|\/)/i.test(u) && !/["'<>\s\\()]/.test(u)) return u; return ''; }
function stripBrailleNoise(text){
  if (!text) return text;
  return String(text).replace(/[⠀-⣿]/g, ' ').replace(/：/g, ':');
}
function splitKeyValueLines(text){
  var normalized = String(text||'').replace(/(\S)[ \t]+(?=[A-Za-zА-Яа-яЁё_]{1,24}\s*:)/g, '$1\n');
  return normalized.split('\n').map(function(l){ return l.trim(); }).filter(Boolean);
}
async function scanHdrClock(n){
  try{
    var count = await PM.chat.count();
    if (!count) return null;
    var end = count - 1;
    var start = Math.max(0, end - (n||40) + 1);
    var msgs = await PM.chat.slice([start, end]);
    if (!Array.isArray(msgs)) return null;
    for (var i=msgs.length-1;i>=0;i--){
      var content = stripBrailleNoise(String(msgs[i].content||''));
      var m = content.match(/\[HDR\]([\s\S]*?)\[\/HDR\]/i);
      if (!m) continue;
      var block = m[1];
      var dateM = block.match(/(?:date|дата)\s*:\s*([^\n]+?)(?=\s*(?:day|день)\s*:|$)/i);
      var dayM = block.match(/(?:day|день)\s*:\s*([^\n]+?)(?=\s*(?:date|дата)\s*:|$)/i);
      if (dateM || dayM){
        return { date: dateM ? dateM[1].trim() : '', day: dayM ? dayM[1].trim() : '' };
      }
    }
    return null;
  }catch(e){ console.error('RP scanHdrClock failed', e); return null; }
}
async function refreshHomeClock(){
  await renderHomeClockText();
}
async function renderHomeClockText(){
  var t = $('#rp_home_clock_text');
  if (!t) return;
  var clk = await rpGet('rp_rpclock', null);
  if (!clk || (!clk.date && !clk.day)){ t.textContent = 'Дата в РП не определена'; return; }
  var bits = [];
  if (clk.day) bits.push(clk.day);
  if (clk.date) bits.push(clk.date);
  t.textContent = bits.join(', ') + (clk.source==='hdr' ? ' · по HDR' : ' · по анализу контекста');
}
async function currentRpLabel(){
  try{
    var clk = await rpGet('rp_rpclock', null);
    if (!clk) return '';
    return [clk.day, clk.date].filter(Boolean).join(', ');
  }catch(e){ return ''; }
}

function msgKey(t){ return t==='main' ? 'rp_messages' : 'rp_messages_'+t; }
function statusKey(t){ return t==='main' ? 'rp_msg_status' : 'rp_msg_status_'+t; }
function summaryCountKey(t){ return t==='main' ? 'rp_msg_summary_count' : 'rp_msg_summary_count_'+t; }
function summaryEntryId(t, n){ return t==='main' ? ('rp-messenger-summary-'+n) : ('rp-contact-'+t+'-summary-'+n); }

var msgQueues = {};
function mutateMessages(threadId, fn){
  var q = msgQueues[threadId] || Promise.resolve();
  var run = q.then(async function(){
    var key = msgKey(threadId);
    var list = await rpGet(key, []);
    var res = await fn(list);
    await rpSet(key, list.slice(-500));
    return res;
  });
  msgQueues[threadId] = run.catch(function(){});
  return run;
}
async function getMsgStatus(threadId){
  var s = await rpGet(statusKey(threadId), null);
  if (!s) return null;
  if (s.state === 'pending' && Date.now() - s.at > 45000 && !rpImgJobsActive()) return { state:'error', at: s.at };
  return s;
}
async function setMsgStatus(threadId, state){
  if (state === 'idle'){ await rpSet(statusKey(threadId), null); return; }
  await rpSet(statusKey(threadId), { state: state, at: Date.now() });
}
async function nextSummaryIndex(threadId){
  var key = summaryCountKey(threadId);
  var n = (await rpGet(key, 0)) + 1;
  await rpSet(key, n);
  return n;
}

function showChoiceModal(opts){
  return new Promise(function(resolve){
    var root = $('#rp_screen') || $('#rp_frame');
    if (!root){ resolve(null); return; }
    var modal = el('div','rp_confirm_overlay');
    modal.innerHTML =
      '<div class="rp_confirm_card">'+
        '<div class="rp_confirm_title">'+escapeHtml(opts.title||'')+'</div>'+
        (opts.message ? '<div class="rp_confirm_msg">'+escapeHtml(opts.message)+'</div>' : '')+
        '<div class="rp_confirm_actions">'+
          opts.buttons.map(function(b,i){ return '<div class="rp_btn'+(b.ghost?' rp_ghost':'')+' rp_sm" data-choice="'+i+'"><span>'+escapeHtml(b.label)+'</span></div>'; }).join('')+
        '</div>'+
      '</div>';
    root.appendChild(modal);
    modal.querySelectorAll('[data-choice]').forEach(function(btn, i){
      btn.addEventListener('click', function(){
        modal.remove();
        resolve(opts.buttons[i].value);
      });
    });
  });
}

var LB_NAME_PREFIX = 'Телефон отношений';
async function rpGetStrict(key){
  return await withTimeout(Promise.resolve().then(function(){ return PM.store.get(key, 'chat'); }).then(function(v){ return { ok:true, v: v === undefined ? null : v }; }, function(){ return { ok:false }; }), 8000, { ok:false });
}
async function ensureLorebook(opts){
  opts = opts || {};
  var rid = await rpGetStrict('rp_lb_id');
  if (!rid.ok) return null;
  var lbId = rid.v;
  if (lbId){
    for (var tr = 0; tr < 2; tr++){
      var got = await withTimeout(Promise.resolve().then(function(){ return PM.lore.get(lbId); }).then(function(v){ return { v: v }; }, function(){ return { err:true }; }), 8000, { err:true });
      if (got.v) return got.v;
      if (got.err && opts.noCreate) return null;
      await new Promise(function(r){ setTimeout(r, 1200); });
    }
    if (opts.noCreate) return null;
  } else if (opts.noCreate) return null;
  var names = await getNames();
  var lbName = LB_NAME_PREFIX + ': ' + names.charName + ' \u2194 ' + names.userName;
  var found = [];
  try{ found = (await PM.lore.find(lbName)) || []; }catch(e){}
  if (found && found.length){
    var choice = await showChoiceModal({
      title: 'Найден лорбук этого персонажа',
      message: 'У «'+names.charName+'» уже есть лорбук «'+lbName+'» из другого чата. Добавлять телефонные записи в него, или вести отдельный лорбук для этого чата?',
      buttons: [
        { label: 'Добавлять в существующий', value: 'use' },
        { label: 'Создать отдельный для этого чата', value: 'new', ghost: true }
      ]
    });
    if (choice === 'use'){
      await rpSet('rp_lb_id', found[0].id);
      await attachLorebook(found[0].id);
      return found[0];
    }
    lbName = lbName + ' (' + todayISODate() + ')';
  }
  try{
    var newId = await PM.lore.create(lbName);
    await rpSet('rp_lb_id', newId);
    await attachLorebook(newId);
    return await PM.lore.get(newId);
  }catch(e){ console.error('RP lorebook create failed', e); toast('Не удалось создать лорбук: ' + (e && e.message ? e.message : e)); return null; }
}
async function attachLorebook(id){
  try{ await PM.lore.bind(id); }
  catch(e){ console.error('RP attach lorebook failed', e); toast('Лорбук создан, но не подключился к чату: ' + (e && e.message ? e.message : e)); }
}
async function getLoreLang(){ return await rpGet('rp_lore_lang', 'ru'); }
async function localizeForLore(text){
  if (!text) return text;
  var lang = await getLoreLang();
  if (lang !== 'en') return text;
  try{
    var translated = await callModel('Переведи следующий текст на английский язык, сохраняя смысл, структуру и переносы строк, ничего не добавляя от себя:\n\n'+text+'\n\nОтветь только переводом, без пояснений.');
    var t = String(translated||'').trim();
    return t || text;
  }catch(e){ console.error('RP localizeForLore failed', e); return text; }
}
async function upsertLorebookEntry(identifier, name, content, opts){
  var lb = await ensureLorebook(opts);
  if (!lb) return;
  content = await localizeForLore(content);
  var entries = lb.entries || [];
  var entry = entries.find(function(e){ return e.identifier===identifier; });
  if (entry) entry.content = content;
  else entries.push({ identifier:identifier, name:name, content:content, enabled:true, strategy:'constant' });
  lb.entries = entries;
  try{ await PM.lore.save(lb); }catch(e){ console.error('RP lorebook update failed', e); toast('Не удалось обновить лорбук: ' + (e && e.message ? e.message : e)); }
}

