var DELIVERY_PLACE_ICONS = ['🍔','🍕','🍣','🥗','🍜','☕','🍰','🧋','🍱','🛒','💊','🌸','🍩','🍗','🥟','🍛','🧁','🍺','🥐','🍦'];
var DELIVERY_PATTERNS = ['rp_dlv_pat_dots','rp_dlv_pat_stripe','rp_dlv_pat_grid','rp_dlv_pat_wave','rp_dlv_pat_cross'];
function hashStr(s){ var h=0; s=String(s||''); for (var i=0;i<s.length;i++){ h = (h*31 + s.charCodeAt(i))|0; } return Math.abs(h); }
function deliveryPlaceIcon(id){ return DELIVERY_PLACE_ICONS[hashStr(id)%DELIVERY_PLACE_ICONS.length]; }
function deliveryPlacePattern(id){ return DELIVERY_PATTERNS[hashStr('p'+id)%DELIVERY_PATTERNS.length]; }
function extractCurrencyUnit(priceStr){
  var m = /[\d.,\s]+([^\d.,\s]+.*)$/.exec(String(priceStr||'').trim());
  return m && m[1] ? m[1].trim() : rpLocCur();
}
function mulberry32(seed){
  var a = seed >>> 0;
  return function(){
    a |= 0; a = a + 0x6D2B79F5 | 0;
    var t = Math.imul(a ^ a >>> 15, 1 | a);
    t = t + Math.imul(t ^ t >>> 7, 61 | t) ^ t;
    return ((t ^ t >>> 14) >>> 0) / 4294967296;
  };
}
function deliveryMapPoints(seed){
  var rnd = mulberry32(seed||1);
  var pts = [[18+Math.round(rnd()*10), 88+Math.round(rnd()*14)]];
  for (var i=0;i<2;i++){ pts.push([Math.round(70+rnd()*170), Math.round(14+rnd()*76)]); }
  pts.push([270+Math.round(rnd()*14), 16+Math.round(rnd()*12)]);
  return pts;
}
function pointAtFraction(pts, t){
  t = Math.max(0, Math.min(1, t));
  var segs = pts.length-1;
  var segT = t*segs;
  var i = Math.min(segs-1, Math.floor(segT));
  var local = segT - i;
  var a = pts[i], b = pts[i+1];
  return [ a[0]+(b[0]-a[0])*local, a[1]+(b[1]-a[1])*local ];
}
function deliveryMapSvg(seed){
  var pts = deliveryMapPoints(seed);
  var path = pts.map(function(p,i){ return (i===0?'M':'L')+p[0]+','+p[1]; }).join(' ');
  var first = pts[0], last = pts[pts.length-1];
  var rnd2 = mulberry32((seed||1)+777);
  var streets = '';
  for (var i=0;i<4;i++){ var y = Math.round(8+rnd2()*94); streets += '<line x1="0" y1="'+y+'" x2="300" y2="'+y+'" stroke="rgba(255,255,255,.06)" stroke-width="4"/>'; }
  for (var j=0;j<5;j++){ var x = Math.round(8+rnd2()*284); streets += '<line x1="'+x+'" y1="0" x2="'+x+'" y2="110" stroke="rgba(255,255,255,.06)" stroke-width="4"/>'; }
  var gid = 'dlvGrad'+(seed||1);
  return '<svg viewBox="0 0 300 110" preserveAspectRatio="none">'+
    '<defs><linearGradient id="'+gid+'" x1="0" y1="1" x2="1" y2="0">'+
      '<stop offset="0" stop-color="#fff" stop-opacity=".85"/><stop offset="1" stop-color="#fff" stop-opacity=".3"/>'+
    '</linearGradient></defs>'+
    streets+
    '<path d="'+path+'" fill="none" stroke="url(#'+gid+')" stroke-width="2.6" stroke-linecap="round" stroke-linejoin="round" stroke-dasharray="8 7"/>'+
    '<circle cx="'+first[0]+'" cy="'+first[1]+'" r="9" fill="rgba(255,255,255,.18)"/>'+
    '<circle cx="'+first[0]+'" cy="'+first[1]+'" r="5.5" fill="#fff"/>'+
    '<text x="'+first[0]+'" y="'+(first[1]+3.5)+'" font-size="7.5" text-anchor="middle">🏬</text>'+
    '<circle cx="'+last[0]+'" cy="'+last[1]+'" r="9" fill="rgba(255,255,255,.18)"/>'+
    '<circle cx="'+last[0]+'" cy="'+last[1]+'" r="5.5" fill="#fff"/>'+
    '<text x="'+last[0]+'" y="'+(last[1]+3.5)+'" font-size="7.5" text-anchor="middle">🏠</text>'+
  '</svg>';
}

