  if (!cart.lines.length){
    main.appendChild(el('div','dlv_empty','<div class="em">🛍️</div>Корзина пуста. Выбери заведение и добавь что-нибудь вкусное.<div style="margin-top:12px;"><div class="dlv_cta" id="dlv_togo">К заведениям</div></div>'));
    $('#dlv_togo', main).addEventListener('click', function(){ DLV_TAB = 'home'; dlvRender(scope); });
    return;
  }
  $('#dlv_clear', main).addEventListener('click', async function(){ await dlvCartSave(null); dlvRender(scope); });
  var places = await rpGet('rp_delivery_places', []);
