async function generateBankFlavorNotification(){
  try{
    var card = await getCharCard();
    var today = await getStoryDate();
    var prompt = 'Придумай одно короткое банковское push-уведомление (как от настоящего банковского приложения) для персонажа из этой истории — например списание, пополнение или перевод, с правдоподобным местом/отправителем и суммой.'+
      (card.facts ? '\nФон мира/истории: '+card.facts : '')+
      '\n\nФормат СТРОГО одной строкой, без пояснений:\nТИП | место или отправитель | сумма (только число)\nТИП — строго "СПИСАНИЕ", "ПОПОЛНЕНИЕ" или "ПЕРЕВОД".';
    var raw = await callModel(prompt);
    var line = splitKeyValueLines(String(raw||''))[0] || '';
    var parts = line.split('|').map(function(p){ return p.trim(); });
    if (parts.length<3) return null;
    var amount = Math.abs(parseFloat(String(parts[2]).replace(/[^\d.,-]/g,'').replace(',','.'))||0);
    if (!amount) return null;
    var ntype = /ПОПОЛН/i.test(parts[0]) ? 'ПОПОЛНЕНИЕ' : (/ПЕРЕВОД/i.test(parts[0]) ? 'ПЕРЕВОД' : 'СПИСАНИЕ');
    return { bank:'Банк', ntype: ntype, amount: amount, place: parts[1]||'—', message:'', balanceAfter: null, time:'', dateLabel: today, source:'manual' };
  }catch(e){ console.error('RP generateBankFlavorNotification failed', e); return null; }
}
