async function renderMarketProductList(wrap, catId, scope, cartBarWrap){
  try{
    wrap.innerHTML = '<div class="rp_empty"><svg class="rp_spin" style="width:18px;height:18px;"><use href="#rpi-spinner"/></svg></div>';
    var key = 'rp_market_products_'+catId;
    var products = await rpGet(key, null);
    if (!products){
      products = await generateMarketProducts(catId);
      await rpSet(key, products);
    }
    var cart = (await rpGet('rp_market_cart', null)) || { items:{} };
    if (!products.length){ wrap.innerHTML = '<div class="rp_empty">Не удалось загрузить товары — попробуй ещё раз.</div>'; return; }
    wrap.innerHTML = '<div class="rp_mkt_product_grid">'+products.map(function(p){
      var qty = (cart.items[p.id] && cart.items[p.id].qty) || 0;
      return '<div class="rp_mkt_product_card" data-id="'+p.id+'">'+
        '<div class="rp_mkt_product_icon">'+marketCatMeta(catId).emoji+
          (qty===0 ? '<button type="button" class="rp_mkt_add_fab" data-act="plus" data-id="'+p.id+'">+</button>' : '')+
        '</div>'+
        '<div class="rp_mkt_product_body"><div class="rp_mkt_product_name">'+escapeHtml(p.name)+'</div>'+
          '<div class="rp_mkt_product_meta">★ '+escapeHtml(String(p.rating||'4.5'))+'</div>'+
          '<div class="rp_mkt_product_price">'+escapeHtml(p.price)+'</div>'+
        '</div>'+
        (qty>0 ? '<div class="rp_mkt_qty"><button data-act="minus" data-id="'+p.id+'">−</button><span>'+qty+'</span><button data-act="plus" data-id="'+p.id+'">+</button></div>' : '')+
      '</div>';
    }).join('')+'</div>';
    var refreshBtn = el('div','rp_btn rp_ghost rp_xs'); refreshBtn.style.marginBottom='10px';
    refreshBtn.innerHTML = '<svg><use href="#rpi-more"/></svg><span>Обновить подборку</span>';
    wrap.insertBefore(refreshBtn, wrap.firstChild);
    refreshBtn.addEventListener('click', async function(){
      await rpSet(key, null);
      await renderMarketProductList(wrap, catId, scope, cartBarWrap);
    });
    wrap.querySelectorAll('[data-act]').forEach(function(btn){
      btn.addEventListener('click', async function(ev){
        ev.stopPropagation();
        var id = btn.getAttribute('data-id');
        var act = btn.getAttribute('data-act');
        var p = products.find(function(x){ return x.id===id; });
        var c = (await rpGet('rp_market_cart', null)) || { items:{} };
        var cur = (c.items[id] && c.items[id].qty) || 0;
        cur = act==='plus' ? cur+1 : Math.max(0, cur-1);
        if (cur<=0) delete c.items[id]; else c.items[id] = { name: p.name, price: p.price, qty: cur };
        await rpSet('rp_market_cart', c);
        await renderMarketProductList(wrap, catId, scope, cartBarWrap);
      });
    });
    wrap.querySelectorAll('.rp_mkt_product_card').forEach(function(card){
      card.addEventListener('click', function(ev){
        if (ev.target.closest('.rp_mkt_qty') || ev.target.closest('.rp_mkt_add_fab')) return;
        marketOpenProductId = card.getAttribute('data-id');
        marketOpenProductCat = catId;
        renderMarketBody(scope);
      });
    });
    if (cartBarWrap) await renderMarketCartBar(cartBarWrap, scope);
  }catch(e){ console.error('RP market product list failed', e); wrap.innerHTML = '<div class="rp_empty">Не удалось загрузить товары.</div>'; }
}
async function generateMarketProducts(catId){
  var cat = marketCatMeta(catId);
  var card = await getCharCard();
  var prompt = 'Придумай 7-9 товаров для категории "'+cat.name+'" в универсальном маркетплейсе (как Wildberries/Ozon) в мире этой истории — разнообразные, с правдоподобными названиями и ценами.'+
    (card.facts ? '\nФон мира/истории: '+card.facts : '')+
    '\n\nФормат СТРОГО построчно, без нумерации и пояснений, каждый товар новой строкой:\nНазвание | цена (например '+rpLocPriceEx(1290,29)+') | рейтинг (например 4.6)';
  try{
    var raw = await callModel(prompt);
    var lines = splitKeyValueLines(String(raw||''));
    var products = [];
    lines.forEach(function(line){
      var parts = line.split('|').map(function(p){ return p.trim(); });
      if (parts[0]) products.push({ id: uid(), name: parts[0].slice(0,70), price: (parts[1]||'—').slice(0,30), rating: parts[2]||'4.5' });
    });
    return products.slice(0,12);
  }catch(e){ console.error('RP generateMarketProducts failed', e); return []; }
}
async function generateMarketProductDetail(product, cat){
  var card = await getCharCard();
  var prompt = 'Опиши подробно товар "'+product.name+'" (категория: '+cat.name+', цена '+product.price+') для карточки товара в маркетплейсе в мире этой истории.'+
    (card.facts ? '\nФон мира/истории: '+card.facts : '') +
    '\n\nВыведи СТРОГО в этом формате, без лишнего текста и нумерации:\n'+
    'ОПИСАНИЕ: 2-3 живых предложения о товаре\n'+
    'ХАРАКТЕРИСТИКИ:\n- Параметр: значение (5-6 строк)\n'+
    'ОТЗЫВЫ:\n- Имя | оценка от 1 до 5 | текст отзыва одним-двумя предложениями (3-4 отзыва разных покупателей)';
  try{
    var raw = String((await callModel(prompt))||'');
    var descMatch = raw.match(/ОПИСАНИЕ\s*:\s*([\s\S]*?)(?=ХАРАКТЕРИСТИКИ\s*:|$)/i);
    var specsMatch = raw.match(/ХАРАКТЕРИСТИКИ\s*:\s*([\s\S]*?)(?=ОТЗЫВЫ\s*:|$)/i);
    var reviewsMatch = raw.match(/ОТЗЫВЫ\s*:\s*([\s\S]*)$/i);
    var description = descMatch ? descMatch[1].trim() : '';
    var specs = specsMatch ? specsMatch[1].split('\n').map(function(l){ return l.replace(/^[-•]\s*/,'').trim(); }).filter(Boolean).map(function(l){
      var idx = l.indexOf(':');
      return idx>-1 ? { label: l.slice(0,idx).trim(), value: l.slice(idx+1).trim() } : { label: l, value:'' };
    }) : [];
    var reviews = reviewsMatch ? reviewsMatch[1].split('\n').map(function(l){ return l.replace(/^[-•]\s*/,'').trim(); }).filter(Boolean).map(function(l){
      var parts = l.split('|').map(function(p){ return p.trim(); });
      return { author: (parts[0]||'Покупатель').slice(0,40), rating: Math.max(1, Math.min(5, parseInt(parts[1],10)||5)), text: (parts[2]||'').slice(0,240) };
    }) : [];
    return { description: description.slice(0,500), specs: specs.slice(0,8), reviews: reviews.slice(0,6) };
  }catch(e){ console.error('RP generateMarketProductDetail failed', e); return { description:'', specs:[], reviews:[] }; }
}
async function renderMarketProductDetail(scope){
  scope.innerHTML = '<div class="rp_empty"><svg class="rp_spin" style="width:18px;height:18px;"><use href="#rpi-spinner"/></svg></div>';
  var catId = marketOpenProductCat;
  var key = 'rp_market_products_'+catId;
  var products = (await rpGet(key, [])) || [];
  var product = products.find(function(p){ return p.id === marketOpenProductId; });
  if (!product){ marketOpenProductId = null; marketOpenProductCat = null; await renderMarketBody(scope); return; }
  if (!product.detail){
    product.detail = await generateMarketProductDetail(product, marketCatMeta(catId));
    var idx = products.findIndex(function(p){ return p.id === product.id; });
    if (idx>-1){ products[idx] = product; await rpSet(key, products); }
  }
  scope.innerHTML = '';
  var backRow = el('div'); backRow.style.cssText = 'display:flex;align-items:center;gap:10px;margin-bottom:14px;';
  backRow.innerHTML = '<div class="rp_iconbtn" id="rp_mkt_detail_back"><svg><use href="#rpi-back"/></svg></div><div style="font-weight:800;font-size:14.5px;color:var(--text);flex:1;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;">'+escapeHtml(product.name)+'</div>';
  scope.appendChild(backRow);
  $('#rp_mkt_detail_back', backRow).addEventListener('click', async function(){ marketOpenProductId = null; marketOpenProductCat = null; await renderMarketBody(scope); });

  var hero = el('div','rp_mkt_detail_hero');
  hero.innerHTML = '<div class="rp_mkt_detail_hero_icon">'+marketCatMeta(catId).emoji+'</div>';
  scope.appendChild(hero);

  var reviews = product.detail.reviews || [];
  var avgRating = reviews.length ? (reviews.reduce(function(s,r){ return s+r.rating; }, 0)/reviews.length).toFixed(1) : String(product.rating||'4.5');
  var info = el('div','rp_mkt_detail_info');
  info.innerHTML =
    '<div class="rp_mkt_detail_name">'+escapeHtml(product.name)+'</div>'+
    '<div class="rp_mkt_detail_rating">★ '+escapeHtml(avgRating)+' <span class="rp_muted">· '+reviews.length+' отзыв'+(reviews.length===1?'':(reviews.length>=2&&reviews.length<=4?'а':'ов'))+'</span></div>'+
    '<div class="rp_mkt_detail_price">'+escapeHtml(product.price)+'</div>';
  scope.appendChild(info);

  if (product.detail.description){
    var descBlock = el('div','rp_mkt_detail_section');
    descBlock.innerHTML = '<div class="rp_mkt_detail_section_title">Описание</div><div class="rp_mkt_detail_desc">'+escapeHtml(product.detail.description)+'</div>';
    scope.appendChild(descBlock);
  }
  if (product.detail.specs && product.detail.specs.length){
    var specsBlock = el('div','rp_mkt_detail_section');
    specsBlock.innerHTML = '<div class="rp_mkt_detail_section_title">Характеристики</div>'+
      product.detail.specs.map(function(s){ return '<div class="rp_mkt_spec_row"><span>'+escapeHtml(s.label)+'</span><span>'+escapeHtml(s.value)+'</span></div>'; }).join('');
    scope.appendChild(specsBlock);
  }
  var reviewsBlock = el('div','rp_mkt_detail_section');
  reviewsBlock.innerHTML = '<div class="rp_mkt_detail_section_title">Отзывы</div>'+
    (reviews.length ? reviews.map(function(r){
      return '<div class="rp_mkt_review"><div class="rp_mkt_review_head"><span class="rp_mkt_review_author">'+escapeHtml(r.author)+'</span><span class="rp_mkt_review_stars">'+'★'.repeat(r.rating)+'<span style="opacity:.3;">'+'★'.repeat(5-r.rating)+'</span></span></div><div class="rp_mkt_review_text">'+escapeHtml(r.text)+'</div></div>';
    }).join('') : '<div class="rp_muted">Пока без отзывов</div>');
  scope.appendChild(reviewsBlock);

  var cart = (await rpGet('rp_market_cart', null)) || { items:{} };
  var qty = (cart.items[product.id] && cart.items[product.id].qty) || 0;
  var actionBar = el('div','rp_mkt_detail_actionbar');
  actionBar.innerHTML = '<div class="rp_mkt_qty" id="rp_mkt_detail_qty"><button data-act="minus">−</button><span>'+qty+'</span><button data-act="plus">+</button></div>'+
    '<button type="button" class="rp_mkt_checkout_btn" id="rp_mkt_detail_add" style="flex:1;justify-content:center;"><span>В корзину</span><svg><use href="#rpi-cart"/></svg></button>';
  scope.appendChild(actionBar);
  var addBtn = $('#rp_mkt_detail_add', actionBar);
  addBtn.style.setProperty('background', '#ffffff', 'important');
  addBtn.style.setProperty('color', '#241347', 'important');
  addBtn.style.setProperty('opacity', '1', 'important');
  addBtn.style.setProperty('pointer-events', 'auto', 'important');
  addBtn.style.setProperty('cursor', 'pointer', 'important');
  addBtn.style.setProperty('z-index', '50', 'important');
  addBtn.style.setProperty('position', 'relative', 'important');
  function updateQtyDisplay(q){ var s = $('#rp_mkt_detail_qty', actionBar).querySelector('span'); if (s) s.textContent = q; }
  $('#rp_mkt_detail_qty', actionBar).querySelectorAll('[data-act]').forEach(function(btn){
    btn.addEventListener('click', async function(){
      var c = (await rpGet('rp_market_cart', null)) || { items:{} };
      var cur = (c.items[product.id] && c.items[product.id].qty) || 0;
      cur = btn.getAttribute('data-act')==='plus' ? cur+1 : Math.max(0, cur-1);
      if (cur<=0) delete c.items[product.id]; else c.items[product.id] = { name: product.name, price: product.price, qty: cur };
      await rpSet('rp_market_cart', c);
      updateQtyDisplay(cur);
    });
  });
  addBtn.addEventListener('click', async function(ev){
    ev.preventDefault();
    var c = (await rpGet('rp_market_cart', null)) || { items:{} };
    var cur = (c.items[product.id] && c.items[product.id].qty) || 0;
    cur = cur<=0 ? 1 : cur;
    c.items[product.id] = { name: product.name, price: product.price, qty: cur };
    await rpSet('rp_market_cart', c);
    updateQtyDisplay(cur);
    toast('Добавлено в корзину');
  });
}
async function renderMarketCartBar(wrap, scope){
  var cart = (await rpGet('rp_market_cart', null)) || { items:{} };
  var ids = Object.keys(cart.items);
  if (!ids.length){ wrap.innerHTML=''; return; }
  var itemCount = ids.reduce(function(s,k){ return s+cart.items[k].qty; }, 0);
  var total = ids.reduce(function(s,k){
    var price = parseFloat(String(cart.items[k].price).replace(/[^\d.,]/g,'').replace(',','.')) || 0;
    return s + price*cart.items[k].qty;
  }, 0);
  var curBankBal = await getBankBalance();
  var bar = el('div','rp_mkt_cartbar');
  bar.innerHTML =
    '<div class="rp_mkt_cartbar_info">'+
      '<div class="rp_mkt_cartbar_line1">'+itemCount+' тов. · '+fmtMoney(Math.round(total))+'</div>'+
      '<div class="rp_mkt_cartbar_line2">баланс '+fmtMoney(curBankBal)+'</div>'+
    '</div>'+
    '<button type="button" class="rp_mkt_checkout_btn" id="rp_mkt_checkout"><span>Заказать</span><svg><use href="#rpi-check"/></svg></button>';
  wrap.innerHTML = '';
  wrap.appendChild(bar);
  var checkoutBtn = $('#rp_mkt_checkout', bar);
  checkoutBtn.style.setProperty('background', '#ffffff', 'important');
  checkoutBtn.style.setProperty('color', '#241347', 'important');
  checkoutBtn.style.setProperty('opacity', '1', 'important');
  checkoutBtn.style.setProperty('pointer-events', 'auto', 'important');
  checkoutBtn.style.setProperty('cursor', 'pointer', 'important');
  checkoutBtn.style.setProperty('z-index', '50', 'important');
  checkoutBtn.style.setProperty('position', 'relative', 'important');
  checkoutBtn.addEventListener('click', async function(ev){
    ev.preventDefault();
    checkoutBtn.disabled = true;
    try{
      var ok = await placeMarketOrder(cart, total);
      if (ok){ marketActiveTab = 'orders'; await renderMarketBody(scope); }
      else checkoutBtn.disabled = false;
    }catch(e){ console.error('RP market checkout failed', e); checkoutBtn.disabled = false; toast('Не удалось оформить заказ'); }
  });
}
async function placeMarketOrder(cart, total, isGift, giftFrom, giftNote){
  var payAcct = isGift ? 'bot' : 'me';
  if (isGift) await ensureBotBalance();
  var bal = await getBankBalance(payAcct);
  if (total > bal){
    if (!isGift) toast('Недостаточно средств на счёте — не хватает '+fmtMoney(total-bal));
    return false;
  }
  var items = Object.keys(cart.items).map(function(k){ return { name: cart.items[k].name, qty: cart.items[k].qty, price: cart.items[k].price }; });
  var today = await getStoryDate();
  var order = {
    id: uid(), items: items, total: Math.round(total),
    status: 'shipping', etaMinutes: isGift ? (45+Math.floor(Math.random()*31)) : (50+Math.floor(Math.random()*21)),
    startedAt: Date.now(), dateLabel: today, hidden:false,
    source: isGift?'gift':'manual', isGift: !!isGift, giftFrom: giftFrom||'', giftNote: giftNote||'', revealed: !isGift
  };
  var orders = await rpGet('rp_market_orders', []);
  orders.push(order);
  await rpSet('rp_market_orders', orders.slice(-200));
  if (!isGift) await rpSet('rp_market_cart', null);
  var newBal = bal - total;
  await setBankBalance(newBal, payAcct);
  var counterparty = isGift ? ('Маркет (подарок для '+(await getNames()).userName+')') : 'Маркет';
  await pushBankTx({ type:'out', amount: -total, counterparty: counterparty, note: isGift?'Подарок-сюрприз':'Покупка в Маркете', dateLabel: today, source: isGift?'gift':'manual', acct:payAcct });
  if (!isGift) await pushBankNotification({ bank:'Банк', ntype:'СПИСАНИЕ', amount: total, place: counterparty, message:'', balanceAfter: newBal, time:'', dateLabel: today, source: isGift?'gift':'manual' });
  if (!isGift) toast('Заказ оформлен — '+fmtMoney(total)+' списано со счёта');
  return true;
}
async function renderMarketOrders(wrap, scope){
  wrap.innerHTML = '';
  var orders = await rpGet('rp_market_orders', []);
  var activeOrders = orders.filter(function(o){ return o.status==='shipping'; });
  if (activeOrders.length){
    var activeTitle = el('div','rp_bank_section_title'); activeTitle.innerHTML = '<span>В пути ('+activeOrders.length+')</span>';
    wrap.appendChild(activeTitle);
    for (var i=0;i<activeOrders.length;i++){
      var trackWrap = el('div');
      wrap.appendChild(trackWrap);
      await renderMarketTracking(trackWrap, scope, activeOrders[i].id);
    }
  }
  var title = el('div','rp_bank_section_title'); title.innerHTML = '<span>История заказов</span>';
  wrap.appendChild(title);
  var listWrap = el('div');
  wrap.appendChild(listWrap);
  await renderMarketOrdersList(listWrap, scope);
}
async function renderMarketTracking(wrap, scope, orderId){
  var orders = await rpGet('rp_market_orders', []);
  var order = orders.find(function(o){ return o.id === orderId; });
  if (!order || order.status !== 'shipping'){ wrap.innerHTML=''; return; }
  var etaId = 'rp_mkt_eta_'+orderId;
  var barId = 'rp_mkt_bar_'+orderId;
  var label = order.isGift ? 'Сюрприз в пути…' : (order.items.length>1 ? (escapeHtml(order.items[0].name)+' и ещё '+(order.items.length-1)+' поз.') : escapeHtml(order.items[0]?order.items[0].name:'Заказ'));
  wrap.innerHTML =
    '<div class="rp_mkt_tracking">'+
      '<div style="font-size:11px;color:rgba(255,255,255,.7);overflow:hidden;text-overflow:ellipsis;white-space:nowrap;">'+label+'</div>'+
      '<div class="rp_mkt_tracking_row"><div class="rp_mkt_eta" id="'+etaId+'">--:--</div><div class="rp_mkt_eta_label">до доставки</div></div>'+
      '<div class="rp_mkt_progress_wrap"><div class="rp_mkt_progress_bar" id="'+barId+'" style="width:0%;"></div></div>'+
    '</div>';
  function tick(){
    var totalMs = order.etaMinutes*60000;
    var elapsed = Date.now()-order.startedAt;
    var left = totalMs - elapsed;
    if (left <= 0){
      clearInterval(marketOrderCountdownTimers[orderId]);
      delete marketOrderCountdownTimers[orderId];
      completeMarketOrder(order.id).then(function(){ if (panelOpen && currentScreen==='market') renderMarketBody(scope); });
      return;
    }
    var mm = Math.floor(left/60000), ss = Math.floor((left%60000)/1000);
    var t = document.getElementById(etaId);
    if (t) t.textContent = pad2(mm)+':'+pad2(ss);
    var bar = document.getElementById(barId);
    if (bar) bar.style.width = Math.min(100, Math.round(elapsed/totalMs*100))+'%';
  }
  tick();
  marketOrderCountdownTimers[orderId] = setInterval(tick, 1000);
}
async function completeMarketOrder(id){
  var orders = await rpGet('rp_market_orders', []);
  var order = orders.find(function(o){ return o.id === id; });
  if (!order || order.status !== 'shipping') return;
  order.status = 'delivered';
  order.deliveredAt = Date.now();
  await rpSet('rp_market_orders', orders);
  if (panelOpen && currentScreen === 'market'){
    toast(order.isGift ? 'Посылка-сюрприз прибыла!' : 'Заказ доставлен!');
  } else {
    unreadCount++; updateBadge();
    pushHomeNotification('Маркет', order.isGift ? 'Посылка-сюрприз прибыла!' : 'Заказ доставлен!');
  }
}
async function renderMarketOrdersList(wrap, scope){
  try{
    var orders = (await rpGet('rp_market_orders', [])).filter(function(o){ return o.status==='delivered'; });
    if (!orders.length){ wrap.innerHTML = '<div class="rp_empty">Заказов пока нет.</div>'; return; }
    var shown = orders.slice(-40).slice().reverse();
    wrap.innerHTML = shown.map(function(o){
      if (o.isGift && !o.revealed){
        return '<div class="rp_mkt_gift_card'+(o.hidden?' rp_note_hidden':'')+'" data-id="'+o.id+'" data-gift="1">'+
          '<div class="rp_del_btn rp_del_tr">'+RP_DEL_ICON+'</div>'+
          '<div class="rp_mkt_gift_icon">🎁</div>'+
          '<div class="rp_mkt_gift_title">Подарок-сюрприз от '+escapeHtml(o.giftFrom)+'</div>'+
          '<div class="rp_mkt_gift_sub">Нажми, чтобы открыть · '+escapeHtml(o.dateLabel||'')+'</div>'+
        '</div>';
      }
      return '<div class="rp_mkt_order_card'+(o.hidden?' rp_note_hidden':'')+'" data-id="'+o.id+'">'+
        '<div class="rp_del_btn rp_del_tr">'+RP_DEL_ICON+'</div>'+
        (o.isGift ? '<div class="rp_bank_salary_badge" style="background:#6c3ce0;margin-bottom:6px;">подарок от '+escapeHtml(o.giftFrom)+'</div>' : '')+
        '<div class="rp_mkt_order_head"><span class="rp_mkt_order_badge">✓ Доставлено</span><span>'+escapeHtml(o.dateLabel||'')+'</span></div>'+
        o.items.map(function(it){ return '<div class="rp_mkt_order_line"><span>'+escapeHtml(it.name)+' ×'+escapeHtml(String(it.qty))+'</span><span>'+escapeHtml(String(it.price||''))+'</span></div>'; }).join('')+
        '<div class="rp_mkt_order_total"><span>Итого</span><span>'+fmtMoney(o.total)+'</span></div>'+
        (o.isGift && o.giftNote ? '<div class="rp_muted" style="margin-top:6px;font-style:italic;">«'+escapeHtml(o.giftNote)+'»</div>' : '')+
      '</div>';
    }).join('');
    wrap.querySelectorAll('[data-gift="1"]').forEach(function(card){
      card.addEventListener('click', async function(){
        var list = await rpGet('rp_market_orders', []);
        var o = list.find(function(x){ return x.id === card.getAttribute('data-id'); });
        if (o){ o.revealed = true; await rpSet('rp_market_orders', list); }
        await renderMarketOrdersList(wrap, scope);
      });
    });
    rpWireLongPressDelete(wrap, '.rp_mkt_order_card, .rp_mkt_gift_card', async function(id){
      var list = await rpGet('rp_market_orders', []);
      var next = list.filter(function(x){ return x.id !== id; });
      await rpSet('rp_market_orders', next);
      await renderMarketOrdersList(wrap, scope);
    });
  }catch(e){ console.error(e); wrap.innerHTML = '<div class="rp_empty">Не удалось загрузить заказы.</div>'; }
}
async function gatherOocMarket(){
  var orders = (await rpGet('rp_market_orders', [])).filter(function(o){ return !o.hidden; });
  if (!orders.length) return [];
  return ['Маркет (последние заказы):\n'+orders.slice(-8).map(function(o){
    return '- '+(o.isGift?'[подарок от '+o.giftFrom+'] ':'')+(o.status==='shipping'?'в пути: ':'')+o.items.map(function(it){ return it.name+' x'+it.qty; }).join(', ')+' — '+fmtMoney(o.total);
  }).join('\n')];
}
async function hideMarketLists(){
  var orders = await rpGet('rp_market_orders', []);
  var changed = false;
  for (var i=0;i<orders.length-hk();i++){ if (!orders[i].hidden){ orders[i].hidden=true; changed=true; } }
  if (changed) await rpSet('rp_market_orders', orders);
  return changed;
}
async function unhideMarketLists(){
  var orders = await rpGet('rp_market_orders', []);
  var changed = false;
  orders.forEach(function(o){ if (o.hidden){ o.hidden=false; changed=true; } });
  if (changed) await rpSet('rp_market_orders', orders);
  return changed;
}
async function generateSurpriseGiftItem(){
  try{
    var card = await getCharCard();
    var names = await getNames();
    var cat = MARKET_CATEGORIES[Math.floor(Math.random()*MARKET_CATEGORIES.length)];
    var prompt = 'Ты подбираешь один небольшой подарок-сюрприз, который персонаж '+names.charName+' решил заказать для '+names.userName+' в категории "'+cat.name+'" на маркетплейсе, в мире этой истории.'+
      (card.facts ? '\nФон мира/истории персонажа: '+card.facts : '')+
      '\n\nФормат СТРОГО, без пояснений, две строки:\nНазвание | цена (например '+rpLocPriceEx(990,24)+')\nЗаметка: короткая фраза от '+names.charName+' (1 предложение, в его манере, почему выбрал именно это)';
    var raw = await callModel(prompt);
    var lines = splitKeyValueLines(String(raw||''));
    if (!lines.length) return null;
    var parts = lines[0].split('|').map(function(p){ return p.trim(); });
    if (!parts[0]) return null;
    var noteLine = lines.slice(1).join(' ').replace(/^заметка\s*:\s*/i,'').trim();
    return { name: parts[0].slice(0,70), price: (parts[1]||rpLocPriceEx(500,15)).slice(0,30), note: noteLine.slice(0,200), catId: cat.id };
  }catch(e){ console.error('RP generateSurpriseGiftItem failed', e); return null; }
}
async function maybeAutonomousMarketGift(){
  try{
    var conf = await rpGet('rp_autonomy_market', null);
    if (!conf || !conf.enabled) return;
    var intervalMs = Math.max(30, Number(conf.intervalMin)||90) * 60000;
    var count = 0;
    try{ count = await PM.chat.count(); }catch(e){ return; }
    var watch = await rpGet('rp_autonomy_watch_market', null);
    if (!watch || watch.count !== count){
      await rpSet('rp_autonomy_watch_market', { count: count, at: Date.now() });
      return;
    }
    if (Date.now() - watch.at < intervalMs) return;
    var lastAuto = await rpGet('rp_autonomy_last_market', 0);
    if (Date.now() - lastAuto < intervalMs) return;
    if (Math.random() > 0.35) return;
    await rpSet('rp_autonomy_last_market', Date.now());

    var gift = await generateSurpriseGiftItem();
    if (!gift) return;
    var names = await getNames();
    var priceNum = Math.abs(parseFloat(String(gift.price).replace(/[^\d.,]/g,'').replace(',','.'))||0);
    if (!priceNum) return;
    var cart = { items: {} };
    cart.items[uid()] = { name: gift.name, price: gift.price, qty: 1 };
    var ok = await placeMarketOrder(cart, priceNum, true, names.charName, gift.note);
    if (!ok) return;
    if (panelOpen && currentScreen === 'market'){
      var scope = $('.rp_mkt_scope');
      if (scope) await renderMarketBody(scope);
    } else {
      unreadCount++; updateBadge();
      pushHomeNotification('Маркет', names.charName+' оформил(а) подарок-сюрприз 🎁');
    }
  }catch(e){ console.error('RP autonomy (market gift) failed', e); }
}

