async function buildCalendarMenu(scope){
  $('#rp_appbar_menu_btn').style.display = 'flex';
  var menu = buildAppbarMenu();
  menu.innerHTML =
    '<div class="rp_btn rp_sm" id="rp_cal_menu_lore"><svg><use href="#rpi-note"/></svg><span>Саммари в лорбук</span></div>'+
    '<div class="rp_btn rp_ghost rp_xs" id="rp_cal_menu_hide"><svg><use href="#rpi-eyeoff"/></svg><span>Хайд</span></div>'+
    '<div class="rp_btn rp_ghost rp_xs" id="rp_cal_menu_unhide"><svg><use href="#rpi-eye"/></svg><span>Анхайд</span></div>';
  menu.appendChild(buildOocButton('ooc-calendar', gatherOocCalendar));

  wireBusyButton($('#rp_cal_menu_lore', menu), 'cal-lore', async function(){
    var events = (await rpGet('rp_calendar_events', [])).filter(function(e){ return !e.hidden; });
    if (!events.length){ toast('Пока нет событий'); closeAppbarMenu(); return; }
    var sorted = events.slice().sort(function(a,b){ return a.iso<b.iso?-1:(a.iso>b.iso?1:0); });
    var lines = sorted.slice(-20).map(function(e){ return '- '+e.iso+' '+(e.icon||'')+' '+e.text; });
    await upsertLorebookEntry('rp-calendar', 'События календаря', lines.join('\n'));
    toast('Сохранено в лорбук');
    closeAppbarMenu();
  });
  wireBusyButton($('#rp_cal_menu_hide', menu), 'cal-hide', async function(){
    var changed = await hideCalendarLists();
    toast(changed ? 'Скрыто (кроме последней записи)' : 'Нечего скрывать');
    closeAppbarMenu();
    await renderCalendarBody(scope);
  });
  wireBusyButton($('#rp_cal_menu_unhide', menu), 'cal-unhide', async function(){
    var changed = await unhideCalendarLists();
    toast(changed ? 'Показано всё скрытое' : 'Нечего показывать');
    closeAppbarMenu();
    await renderCalendarBody(scope);
  });
}
async function renderCalendarBody(scope){
  scope.innerHTML = '';
  var meta = await rpGet('rp_calendar_meta', null);
  if (meta && (meta.title || meta.note)){
    var banner = el('div','rp_cal_banner');
    banner.innerHTML = (meta.title ? '<div class="rp_cal_banner_title">'+escapeHtml(meta.title)+'</div>' : '')+
      (meta.note ? '<div class="rp_cal_banner_note">'+escapeHtml(meta.note)+'</div>' : '');
    scope.appendChild(banner);
  }
  var headerRow = el('div','rp_cal_header');
  headerRow.innerHTML =
    '<div class="rp_iconbtn" id="rp_cal_prev"><svg><use href="#rpi-back"/></svg></div>'+
    '<div class="rp_cal_month_label">'+CAL_MONTH_NAMES[calendarViewMonth]+' '+calendarViewYear+'</div>'+
    '<div class="rp_iconbtn" id="rp_cal_next" style="transform:scaleX(-1);"><svg><use href="#rpi-back"/></svg></div>';
  scope.appendChild(headerRow);
  var toggleRow = el('div'); toggleRow.style.display='flex'; toggleRow.style.justifyContent='center'; toggleRow.style.marginBottom='14px';
  toggleRow.innerHTML = '<div class="rp_cal_toggle"><div class="rp_cal_toggle_opt on">Месяц</div><div class="rp_cal_toggle_opt">Неделя</div></div>';
  scope.appendChild(toggleRow);
  $('#rp_cal_prev', headerRow).addEventListener('click', async function(){
    calendarViewMonth--; if (calendarViewMonth<0){ calendarViewMonth=11; calendarViewYear--; }
    await renderCalendarBody(scope);
  });
  $('#rp_cal_next', headerRow).addEventListener('click', async function(){
    calendarViewMonth++; if (calendarViewMonth>11){ calendarViewMonth=0; calendarViewYear++; }
    await renderCalendarBody(scope);
  });

  var weekRow = el('div','rp_cal_weekrow');
  weekRow.innerHTML = ['Пн','Вт','Ср','Чт','Пт','Сб','Вс'].map(function(d){ return '<div>'+d+'</div>'; }).join('');
  scope.appendChild(weekRow);

  var events = await rpGet('rp_calendar_events', []);
  var todayIso = await getStoryDate();
  var byDate = {};
  events.forEach(function(e){ (byDate[e.iso] = byDate[e.iso] || []).push(e); });

  var firstDow = (new Date(calendarViewYear, calendarViewMonth, 1).getDay()+6)%7;
  var numDays = new Date(calendarViewYear, calendarViewMonth+1, 0).getDate();
  var prevMonth = calendarViewMonth===0?11:calendarViewMonth-1;
  var prevYear = calendarViewMonth===0?calendarViewYear-1:calendarViewYear;
  var prevNumDays = new Date(prevYear, prevMonth+1, 0).getDate();
  var nextMonth = calendarViewMonth===11?0:calendarViewMonth+1;
  var nextYear = calendarViewMonth===11?calendarViewYear+1:calendarViewYear;
  var grid = el('div','rp_cal_grid');
  var cellsHtml = '';
  for (var i=0;i<firstDow;i++){
    var pd = prevNumDays-firstDow+i+1;
    cellsHtml += '<div class="rp_cal_cell rp_cal_cell_outside"><div class="rp_cal_cell_num">'+pd+'</div></div>';
  }
  for (var d=1; d<=numDays; d++){
    var iso = calendarViewYear+'-'+pad2(calendarViewMonth+1)+'-'+pad2(d);
    var dayEvents = byDate[iso] || [];
    var isToday = iso === todayIso;
    var isSelected = iso === calendarSelectedDay;
    cellsHtml += '<div class="rp_cal_cell'+(isToday?' rp_cal_today':'')+(isSelected?' rp_cal_selected':'')+'" data-iso="'+iso+'">'+
      '<div class="rp_cal_cell_num">'+d+'</div>'+
      '<div class="rp_cal_cell_dots">'+(dayEvents.length ? dayEvents.slice(0,3).map(function(){ return '<span></span>'; }).join('') : '')+'</div>'+
    '</div>';
  }
  var totalSoFar = firstDow+numDays;
  var trailing = (7-(totalSoFar%7))%7;
  for (var t=1;t<=trailing;t++){
    cellsHtml += '<div class="rp_cal_cell rp_cal_cell_outside"><div class="rp_cal_cell_num">'+t+'</div></div>';
  }
  grid.innerHTML = cellsHtml;
  scope.appendChild(grid);
  grid.querySelectorAll('[data-iso]').forEach(function(cell){
    cell.addEventListener('click', async function(){
      var iso2 = cell.getAttribute('data-iso');
      calendarSelectedDay = (calendarSelectedDay === iso2) ? null : iso2;
      await renderCalendarBody(scope);
    });
  });

  if (calendarSelectedDay){
    var daypanel = el('div');
    scope.appendChild(daypanel);
    await renderCalendarDayPanel(daypanel, scope, calendarSelectedDay);
  } else {
    var illu = el('div','rp_cal_illustration');
    illu.innerHTML = CAL_ILLUSTRATION_SVG;
    scope.appendChild(illu);
  }

  var upcomingTitle = el('div','rp_cal_section_title'); upcomingTitle.innerHTML = 'Ближайшие события';
  scope.appendChild(upcomingTitle);
  var upcomingWrap = el('div','rp_cal_upcoming_card');
  scope.appendChild(upcomingWrap);
  await renderCalendarUpcoming(upcomingWrap, scope, events, todayIso);
}
async function renderCalendarDayPanel(wrap, scope, iso){
  var events = await rpGet('rp_calendar_events', []);
  var dayEvents = events.filter(function(e){ return e.iso === iso; });
  var dateObj = new Date(iso+'T00:00:00');
  var label = dateObj.getDate()+' '+CAL_MONTH_GEN[dateObj.getMonth()]+' '+dateObj.getFullYear();
  wrap.innerHTML = '<div class="rp_cal_daypanel_card">'+
    '<div class="rp_cal_daypanel_head"><span>'+escapeHtml(label)+'</span><div class="rp_iconbtn rp_xs" id="rp_cal_day_close"><svg><use href="#rpi-x"/></svg></div></div>'+
    (dayEvents.length ? dayEvents.map(function(e){
      return '<div class="rp_cal_event_row'+(e.hidden?' rp_note_hidden':'')+'" data-id="'+e.id+'">'+
        '<div class="rp_del_btn rp_del_tr">'+RP_DEL_ICON+'</div>'+
        '<span class="rp_cal_event_icon">'+escapeHtml(e.icon||'📌')+'</span><span class="rp_cal_event_text">'+escapeHtml(e.text)+'</span>'+
      '</div>';
    }).join('') : '<div class="rp_muted" style="margin:6px 0;">Событий нет</div>')+
    '<div class="rp_cal_icon_picker">'+CAL_ICON_SET.map(function(ic,idx){ return '<div class="rp_cal_icon_opt'+(idx===0?' on':'')+'" data-icon="'+ic+'">'+ic+'</div>'; }).join('')+'</div>'+
    '<input class="rp_input" type="text" id="rp_cal_new_text" placeholder="Новое событие...">'+
    '<div class="rp_cal_btn" id="rp_cal_add_event" style="margin-top:8px;width:100%;"><span>Добавить</span></div>'+
  '</div>';
  $('#rp_cal_day_close', wrap).addEventListener('click', async function(){ calendarSelectedDay = null; await renderCalendarBody(scope); });
  var chosenIcon = CAL_ICON_SET[0];
  var opts = wrap.querySelectorAll('.rp_cal_icon_opt');
  opts.forEach(function(o){
    o.addEventListener('click', function(){
      chosenIcon = o.getAttribute('data-icon');
      opts.forEach(function(x){ x.classList.toggle('on', x===o); });
    });
  });
  $('#rp_cal_add_event', wrap).addEventListener('click', async function(){
    var input = $('#rp_cal_new_text', wrap);
    var text = input.value.trim();
    if (!text){ toast('Введи текст события'); return; }
    var list = await rpGet('rp_calendar_events', []);
    list.push({ id: uid(), iso: iso, icon: chosenIcon, text: text.slice(0,200), source:'manual', hidden:false, createdAt: Date.now() });
    await rpSet('rp_calendar_events', list.slice(-500));
    toast('Событие добавлено');
    await renderCalendarBody(scope);
  });
  rpWireLongPressDelete(wrap, '.rp_cal_event_row', async function(id){
    var list = await rpGet('rp_calendar_events', []);
    var next = list.filter(function(x){ return x.id !== id; });
    await rpSet('rp_calendar_events', next);
    await renderCalendarBody(scope);
  });
}
async function renderCalendarUpcoming(wrap, scope, events, todayIso){
  var upcoming = events.filter(function(e){ return !e.hidden && e.iso >= todayIso; })
    .sort(function(a,b){ return a.iso<b.iso?-1:(a.iso>b.iso?1:0); }).slice(0,8);
  if (!upcoming.length){ wrap.innerHTML = '<div class="rp_empty">Ближайших событий нет.</div>'; return; }
  wrap.innerHTML = upcoming.map(function(e){
    var d = new Date(e.iso+'T00:00:00');
    var label = d.getDate()+' '+CAL_MONTH_SHORT[d.getMonth()];
    return '<div class="rp_cal_upcoming_row" data-iso="'+e.iso+'"><span class="rp_cal_upcoming_bullet"></span><span class="rp_cal_upcoming_date">'+label+'</span><span class="rp_cal_upcoming_icon">'+escapeHtml(e.icon||'📌')+'</span><span class="rp_cal_upcoming_text">'+escapeHtml(e.text)+'</span></div>';
  }).join('');
  wrap.querySelectorAll('[data-iso]').forEach(function(row){
    row.addEventListener('click', async function(){
      var iso = row.getAttribute('data-iso');
      var m = /^(\d{4})-(\d{2})-(\d{2})$/.exec(iso);
      if (m){ calendarViewYear = parseInt(m[1],10); calendarViewMonth = parseInt(m[2],10)-1; }
      calendarSelectedDay = iso;
      await renderCalendarBody(scope);
    });
  });
}
async function gatherOocCalendar(){
  var events = (await rpGet('rp_calendar_events', [])).filter(function(e){ return !e.hidden; });
  if (!events.length) return [];
  var today = await getStoryDate();
  var upcoming = events.filter(function(e){ return e.iso >= today; }).sort(function(a,b){ return a.iso<b.iso?-1:(a.iso>b.iso?1:0); }).slice(0,8);
  var list = upcoming.length ? upcoming : events.slice(-8);
  var lines = list.map(function(e){ return '- '+e.iso+' '+(e.icon||'')+' '+e.text; });
  return ['Календарь ('+(upcoming.length?'ближайшие события':'последние записи')+'):\n'+lines.join('\n')];
}
async function hideCalendarLists(){
  var events = await rpGet('rp_calendar_events', []);
  var changed = false;
  for (var i=0;i<events.length-hk();i++){ if (!events[i].hidden){ events[i].hidden=true; changed=true; } }
  if (changed) await rpSet('rp_calendar_events', events);
  return changed;
}
async function unhideCalendarLists(){
  var events = await rpGet('rp_calendar_events', []);
  var changed = false;
  events.forEach(function(e){ if (e.hidden){ e.hidden=false; changed=true; } });
  if (changed) await rpSet('rp_calendar_events', events);
  return changed;
}
function parseRuMonthName(raw){
  var s = String(raw||'').toLowerCase().trim();
  var map = [
    ['январ',0],['феврал',1],['март',2],['апрел',3],
    ['июнь',5],['июня',5],['июн',5],['июль',6],['июля',6],['июл',6],
    ['август',7],['сентябр',8],['октябр',9],['ноябр',10],['декабр',11]
  ];
  for (var i=0;i<map.length;i++){ if (s.indexOf(map[i][0])===0) return map[i][1]; }
  if (s.indexOf('ма')===0) return 4;
  var num = parseInt(s,10);
  if (!isNaN(num) && num>=1 && num<=12) return num-1;
  return null;
}
function parseCalendarBlocks(text){
  var blocks = [];
  var re = /\[CALENDAR\]([\s\S]*?)\[\/CALENDAR\]/g, bm;
  while ((bm = re.exec(text))){
    var lines = splitKeyValueLines(bm[1]);
    var rec = { title:'', month:'', year:'', note:'', eventsMap:{} };
    lines.forEach(function(line){
      var m;
      if ((m = /^title\s*:\s*(.*)$/i.exec(line))) rec.title = m[1].trim();
      else if ((m = /^month\s*:\s*(.*)$/i.exec(line))) rec.month = m[1].trim();
      else if ((m = /^year\s*:\s*(.*)$/i.exec(line))) rec.year = m[1].trim();
      else if ((m = /^note\s*:\s*(.*)$/i.exec(line))) rec.note = m[1].trim();
      else if ((m = /^event_(\d+)_date\s*:\s*(.*)$/i.exec(line))){ rec.eventsMap[m[1]] = rec.eventsMap[m[1]] || {}; rec.eventsMap[m[1]].date = m[2].trim(); }
      else if ((m = /^event_(\d+)_icon\s*:\s*(.*)$/i.exec(line))){ rec.eventsMap[m[1]] = rec.eventsMap[m[1]] || {}; rec.eventsMap[m[1]].icon = m[2].trim(); }
      else if ((m = /^event_(\d+)_text\s*:\s*(.*)$/i.exec(line))){ rec.eventsMap[m[1]] = rec.eventsMap[m[1]] || {}; rec.eventsMap[m[1]].text = m[2].trim(); }
    });
    var events = Object.keys(rec.eventsMap).map(function(k){ return rec.eventsMap[k]; }).filter(function(e){ return e.date && e.text; });
    blocks.push({ title: rec.title, month: rec.month, year: rec.year, note: rec.note, events: events });
  }
  return blocks;
}
async function maybeImportCalendarTags(){
  try{
    var count = 0;
    try{ count = await PM.chat.count(); }catch(e){ return; }
    var watermark = await rpGet('rp_calendar_tag_watermark', null);
    if (watermark === null){ await rpSet('rp_calendar_tag_watermark', count); return; }
    if (count <= watermark){ if (count < watermark) await rpSet('rp_calendar_tag_watermark', count); return; }
    var msgs = [];
    try{ msgs = await PM.chat.slice([watermark, count-1]); }catch(e){ msgs = []; }
    await rpSet('rp_calendar_tag_watermark', count);
    if (!Array.isArray(msgs) || !msgs.length) return;

    var touched = false;
    var today = await getStoryDate();
    var todayMatch = /^(\d{4})-(\d{2})-(\d{2})$/.exec(today);
    var fallbackYear = todayMatch ? parseInt(todayMatch[1],10) : new Date().getFullYear();
    var fallbackMonth = todayMatch ? parseInt(todayMatch[2],10)-1 : new Date().getMonth();
    var events = await rpGet('rp_calendar_events', []);
    var meta = (await rpGet('rp_calendar_meta', null)) || { title:'', note:'' };

    for (var mi=0; mi<msgs.length; mi++){
      var m = msgs[mi];
      if (!m || m.role !== 'assistant' || !m.content) continue;
      var text = rpTagText(String(m.content));
      var blocks = parseCalendarBlocks(text);
      if (!blocks.length) continue;
      for (var bi=0; bi<blocks.length; bi++){
        var b = blocks[bi];
        var monthIdx = parseRuMonthName(b.month);
        if (monthIdx === null) monthIdx = fallbackMonth;
        var yearNum = parseInt(b.year, 10);
        if (isNaN(yearNum)) yearNum = fallbackYear;
        for (var ei=0; ei<b.events.length; ei++){
          var ev = b.events[ei];
          var dayNum = parseInt(String(ev.date).replace(/[^\d]/g,''), 10);
          if (!dayNum || dayNum<1 || dayNum>31) continue;
          var iso = yearNum+'-'+pad2(monthIdx+1)+'-'+pad2(dayNum);
          var dupe = events.some(function(x){ return x.iso===iso && x.text.trim().toLowerCase()===ev.text.trim().toLowerCase(); });
          if (dupe) continue;
          events.push({ id: uid(), iso: iso, icon: ev.icon||'📌', text: ev.text.slice(0,200), source:'bridge', hidden:false, createdAt: Date.now() });
          touched = true;
        }
        if (b.title) meta.title = b.title.slice(0,80);
        if (b.note) meta.note = b.note.slice(0,200);
      }
    }
    if (touched){
      await rpSet('rp_calendar_events', events.slice(-500));
      meta.updatedAt = Date.now();
      await rpSet('rp_calendar_meta', meta);
      if (panelOpen && currentScreen === 'calendar'){
        var scope = $('.rp_cal_scope');
        if (scope) await renderCalendarBody(scope);
      } else {
        unreadCount++; updateBadge();
        pushHomeNotification('Календарь', 'Новое событие в календаре');
      }
    }
  }catch(e){ console.error('RP calendar tag import failed', e); }
}

var CH_REACTIONS = ['👍','❤️','🔥','😂','😢','🤔'];
var chActiveTab = 'feed';
var chOpenChannelId = null;
