    '<div style="display:flex;gap:8px;"><div class="rp_ch_btn" id="rp_ch_cover_pick" style="flex:1;"><span>' + (channel.coverPath ? 'Сменить фото' : 'Выбрать фото') + '</span></div>' + (channel.coverPath ? '<div class="rp_ch_btn ghost" id="rp_ch_cover_rm" style="flex:1;"><span>Убрать</span></div>' : '') + '</div>';
  scope.appendChild(coverRow);
