        '<div class="rp_ch_segment'+(!channel.isPrivate?' on':'')+'" data-priv="0">Открытый</div>'+
        '<div class="rp_ch_segment'+(channel.isPrivate?' on':'')+'" data-priv="1">Закрытый</div>'+
      '</div>';
