async function renderChannelPostsList(wrap, scope, channelId){
  try{
    var posts = (await rpGet('rp_tg_posts', [])).filter(function(p){ return p.channelId === channelId; });
    if (!posts.length){ wrap.innerHTML = '<div class="rp_empty">Постов пока нет.</div>'; return; }
    var channels = await rpGet('rp_tg_channels', []);
    var channel = channels.find(function(c){ return c.id === channelId; });
    wrap.innerHTML = posts.map(function(p){ return chPostRowHtml(p, channel); }).join('');
    wireChPostRows(wrap, scope, function(){ return renderChannelPostsList(wrap, scope, channelId); });
  }catch(e){ console.error(e); wrap.innerHTML = '<div class="rp_empty">Не удалось загрузить посты.</div>'; }
}
async function renderChAdmins(wrap, scope, channelId){
  var channels = await rpGet('rp_tg_channels', []);
  var channel = channels.find(function(c){ return c.id === channelId; });
  if (!channel) return;
  var admins = channel.admins || [];
  var names = await getNames();
  var contacts = (await rpGet('rp_contacts', [])).concat(await rpGet('rp_npcs2', []));
  var pickOptions = '<option value="__char__">'+escapeHtml(names.charName)+' (персонаж)</option>'+
    contacts.map(function(c){ return '<option value="'+escapeHtml(c.id)+'">'+escapeHtml(c.name)+'</option>'; }).join('');
  wrap.innerHTML = '<div class="rp_ch_admins_card">'+
    '<div class="rp_muted" style="margin-bottom:6px;">Администрация канала</div>'+
    (admins.length ? admins.map(function(a,idx){
      return '<div class="rp_ch_admin_row"><span style="overflow:hidden;text-overflow:ellipsis;white-space:nowrap;">'+escapeHtml(a.name)+'</span><span class="rp_ch_admin_role">'+(a.role==='admin'?'Админ':'Модератор')+'</span><div class="rp_ch_admin_del" data-idx="'+idx+'">✕</div></div>';
    }).join('') : '<div class="rp_muted" style="font-size:11px;">Пока никого нет</div>')+
    '<div class="rp_ch_admin_add">'+
      '<select class="rp_input" id="rp_ch_admin_person">'+pickOptions+'</select>'+
      '<div class="rp_ch_admin_add_row">'+
        '<select class="rp_input" id="rp_ch_admin_role"><option value="moderator">Модератор</option><option value="admin">Админ</option></select>'+
        '<div class="rp_ch_btn sm" id="rp_ch_admin_add_btn"><span>Назначить</span></div>'+
      '</div>'+
    '</div>'+
  '</div>';
  $('#rp_ch_admin_add_btn', wrap).addEventListener('click', async function(){
    var personSel = $('#rp_ch_admin_person', wrap);
    var val = personSel.value;
    var name = val === '__char__' ? names.charName : (contacts.find(function(c){ return c.id===val; })||{}).name;
    if (!name){ toast('Выбери персону'); return; }
    var role = $('#rp_ch_admin_role', wrap).value;
    var list = await rpGet('rp_tg_channels', []);
    var c = list.find(function(x){ return x.id === channelId; });
    if (!c) return;
    c.admins = c.admins || [];
    if (c.admins.some(function(a){ return a.name === name; })){ toast('Уже назначен'); return; }
    c.admins.push({ name: name.slice(0,30), role: role });
    await rpSet('rp_tg_channels', list);
    toast('Назначено');
    await renderChAdmins(wrap, scope, channelId);
  });
  wrap.querySelectorAll('.rp_ch_admin_del').forEach(function(btn){
    btn.addEventListener('click', async function(){
      var idx = parseInt(btn.getAttribute('data-idx'),10);
      var list = await rpGet('rp_tg_channels', []);
      var c = list.find(function(x){ return x.id === channelId; });
      if (!c || !c.admins) return;
      c.admins.splice(idx,1);
      await rpSet('rp_tg_channels', list);
      await renderChAdmins(wrap, scope, channelId);
    });
  });
}
async function chAudienceContext(){
  var out = [];
  try{
    var hint = await rpGet('rp_ch_interest', ''); if (hint) out.push('ЗАДАННЫЕ ИНТЕРЕСЫ ЛЕНТЫ (главное, опирайся прежде всего на них): '+hint);
    var names = await getNames(), card = await getCharCard(), mp = await rpGet('rp_my_profile', null);
    if (card && card.facts) out.push('Кто читает (персонаж '+names.charName+'): '+String(card.facts).slice(0,350));
    if (mp){ var pr = [mp.bio, mp.job, mp.city, mp.look].filter(Boolean).join('; '); if (pr) out.push('Игрок '+names.userName+': '+pr.slice(0,250)); }
    var ctx = await getContext(6); if (ctx) out.push('Что происходит в истории: '+String(ctx).slice(0,500));
  }catch(e){}
  return out.join('\n');
}
async function generateDiscoverChannels(count, existingNames){
  var aud = await chAudienceContext();
  var prompt = 'Придумай '+count+' случайных ПУБЛИЧНЫХ каналов, никак не связанных с главными героями этой истории — но ПОДОБРАННЫХ ПО ВКУСАМ тех, кто их читает: учитывай возраст, образ жизни и увлечения читателей. Молодёжь читает сплетни, мемы, звёзд, тусовки, моду, музыку, игры, отношения и «грязное бельё», а не часы, автомеханику или бухгалтерию (такие темы допустимы, только если подходят читателям).\n'+(aud ? aud+'\n' : '')+'Каждый — на свою яркую, узкую тему. Каждый — на свою яркую, узкую, нестандартную тему '+
    '(не просто "новости/юмор/блог" — конкретные темы и интонации, как у настоящих телеграм-каналов: разные по стилю — от сплетен и мемов до подкастов и подборок). Каналы должны выглядеть как то, что реально лежит в ленте у такого читателя.'+
    (existingNames && existingNames.length ? ('\nУже существуют (не повторяй их названия и близкие темы): '+existingNames.slice(-25).join(', ')) : '')+
    '\nЭто обычные публичные каналы без всякого отношения к героям истории — не упоминай никого из персонажей и никакую личную/приватную информацию о них.'+
    '\n\nФормат СТРОГО построчно, без нумерации: Название канала | краткое описание темы (до 8 слов)';
  try{
    var raw = await callModel(prompt);
    var lines = splitKeyValueLines(String(raw||''));
    var out = [];
    lines.forEach(function(line){
      var parts = line.split('|').map(function(p){ return p.trim(); });
      if (parts[0]) out.push({ name: parts[0].slice(0,40), desc: (parts[1]||'').slice(0,100) });
    });
    return out.slice(0,count);
  }catch(e){ console.error('RP generateDiscoverChannels failed', e); return []; }
}
async function ensureDiscoverChannels(minCount){
  var channels = await rpGet('rp_tg_channels', []);
  var discoverPool = channels.filter(function(c){ return c.kind === 'generic' && c.source === 'autonomous' && !c.hidden; });
  var wantNew = 0;
  if (discoverPool.length < minCount) wantNew = minCount - discoverPool.length;
  else if (discoverPool.length < 24 && Math.random() < 0.5) wantNew = 1;
  if (!wantNew) return channels;
  var existingNames = channels.map(function(c){ return c.name; });
  var fresh = await generateDiscoverChannels(wantNew, existingNames);
  fresh.forEach(function(f){
    channels.push({
      id: uid(), name: f.name, description: f.desc||'', kind:'generic', linkedContactId:null, owner: f.name,
      subscribed:true, subscriberCount: 200+Math.floor(Math.random()*50000), isPrivate:false, avatarPath:null,
      admins:[], createdAt: Date.now(), source:'autonomous', hidden:false
    });
  });
  if (fresh.length) await rpSet('rp_tg_channels', channels);
  return channels;
}
async function generateChannelPostsBatch(channel, count){
  var names = await getNames();
  var voice = '';
  var isStoryChannel = channel.kind === 'char' || channel.kind === 'contact';
  var card = isStoryChannel ? await getCharCard() : null;
  var ctx = isStoryChannel ? await getContext(Math.min(cfg('contextRange',24), 8)) : '';
  if (channel.kind === 'char') voice = 'Пиши от лица персонажа "'+names.charName+'", как будто он сам ведёт канал.'+(card&&card.styleSample?('\nКак он говорит:\n'+card.styleSample):'');
  else if (channel.kind === 'contact' && channel.contactAbout) voice = 'Пиши от лица '+channel.owner+' ('+channel.contactAbout+').';
  var prompt = 'Напиши '+count+' постов для канала "'+channel.name+'"'+(channel.description?(' — '+channel.description):'')+' в мире этой истории.'+
    (voice ? '\n'+voice : '')+
    (isStoryChannel && card && card.facts ? '\nФон мира/истории: '+card.facts : '')+
    (ctx ? '\nНедавние события сцены (можно отражать не впрямую, не выдавай приватные интимные подробности открыто): '+ctx : '')+
    (!isStoryChannel ? '\nЭто обычный публичный канал без отношения к героям истории — не упоминай персонажей истории и никакую личную информацию о них, которая не была бы публично известна.' : '')+
    '\n\nКаждый пост короткий (1-3 предложения), разного содержания, в стиле этого канала.\n'+
    'Формат СТРОГО построчно, без нумерации, маркдауна и пояснений — каждый пост с новой строки.';
  try{
    var raw = await callModel(prompt);
    var lines = splitKeyValueLines(String(raw||''));
    return lines.slice(0,count);
  }catch(e){ console.error('RP generateChannelPostsBatch failed', e); return []; }
}
async function generateChannelPostComments(postText, count, channel){
  count = Math.max(5, Math.min(20, count||8));
  var channelName = channel ? channel.name : '';
  var names = await getNames();
  var includeChar = !!channel && channel.kind !== 'char';
  var card = includeChar ? await getCharCard() : null;
  var prompt = 'Напиши '+count+' коротких комментариев от случайных подписчиков под этим постом в канале'+(channelName?(' "'+channelName+'"'):'')+':\n"'+postText+'"\n\n'+
    'Это обычные случайные подписчики — не упоминай личную/приватную информацию о ком-либо, которая не была бы публично известна из самого текста поста.\n'+
    (includeChar ? ('Если персонаж "'+names.charName+'" мог бы увидеть этот пост (это уместно по контексту сцены), один из комментариев (необязательно первый) напиши от его лица, в характерном стиле'+(card&&card.styleSample?(': '+card.styleSample):'')+'. Подпиши его именем "'+names.charName+'" без искажений. Если неуместно — не включай его вовсе.\n') : '')+
    'Формат СТРОГО построчно, без нумерации и пояснений, каждый комментарий новой строкой:\nИмя: текст комментария';
  try{
    var raw = await callModel(prompt);
    var lines = splitKeyValueLines(String(raw||''));
    var comments = [];
    lines.forEach(function(line){
      var m = line.match(/^([^:]{1,30}):\s*(.+)$/);
      if (m){
        var author = m[1].trim();
        comments.push({ author: author, text: m[2].trim().slice(0,200), isChar: includeChar && author.toLowerCase()===String(names.charName).toLowerCase() });
      }
    });
    return comments.slice(0, count);
  }catch(e){ console.error('RP generateChannelPostComments failed', e); return []; }
}
async function gatherOocChannels(){
  var posts = (await rpGet('rp_tg_posts', [])).filter(function(p){ return !p.hidden; });
  if (!posts.length) return [];
  var channels = await rpGet('rp_tg_channels', []);
  var lines = posts.slice(0,8).map(function(p){
    var ch = channels.find(function(c){ return c.id===p.channelId; });
    return '- ['+(ch?ch.name:'?')+'] '+p.text;
  });
  return ['Каналы (последние посты):\n'+lines.join('\n')];
}
async function hideChannelsList(){
  var posts = await rpGet('rp_tg_posts', []);
  var changed = false;
  for (var i=hk();i<posts.length;i++){ if (!posts[i].hidden){ posts[i].hidden=true; changed=true; } }
  if (changed) await rpSet('rp_tg_posts', posts);
  return changed;
}
async function unhideChannelsList(){
  var posts = await rpGet('rp_tg_posts', []);
  var changed = false;
  posts.forEach(function(p){ if (p.hidden){ p.hidden=false; changed=true; } });
  if (changed) await rpSet('rp_tg_posts', posts);
  return changed;
}
function parseTgChannelBlocks(text){
  var blocks = [];
  var re = /\[TG_CHANNEL_\d+\]([\s\S]*?)\[\/TG_CHANNEL_\d+\]/g, bm;
  while ((bm = re.exec(text))){
    var lines = splitKeyValueLines(bm[1]);
    var name = '', subs = '', posts = [], current = null;
    lines.forEach(function(line){
      var m;
      if ((m = /^name\s*:\s*(.*)$/i.exec(line))){ name = m[1].trim(); return; }
      if ((m = /^subs\s*:\s*(.*)$/i.exec(line))){ subs = m[1].trim(); return; }
      if ((m = /^post\d+\s*:\s*(.*)$/i.exec(line))){ current = { text: m[1].trim(), views:'', comments:[] }; posts.push(current); return; }
      if ((m = /^views\d+\s*:\s*(.*)$/i.exec(line))){ if (current) current.views = m[1].trim(); return; }
      if ((m = /^time\d+\s*:\s*(.*)$/i.exec(line))){ return; }
      if ((m = /^com\d+\s*:\s*(.*)$/i.exec(line))){
        if (current){
          var cm = /^([^:]{1,40}):\s*(.*)$/.exec(m[1]);
          if (cm) current.comments.push({ author: cm[1].trim(), text: cm[2].trim() });
          else current.comments.push({ author:'Подписчик', text: m[1].trim() });
        }
        return;
      }
    });
    if (name) blocks.push({ name: name, subs: subs, posts: posts.filter(function(p){ return p.text; }) });
  }
  return blocks;
}
async function maybeImportChannelTags(){
  try{
    var count = 0;
    try{ count = await PM.chat.count(); }catch(e){ return; }
    var watermark = await rpGet('rp_channels_tag_watermark', null);
    if (watermark === null){ await rpSet('rp_channels_tag_watermark', count); return; }
    if (count <= watermark){ if (count < watermark) await rpSet('rp_channels_tag_watermark', count); return; }
    var msgs = [];
    try{ msgs = await PM.chat.slice([watermark, count-1]); }catch(e){ msgs = []; }
    await rpSet('rp_channels_tag_watermark', count);
    if (!Array.isArray(msgs) || !msgs.length) return;

    var touched = false;
    var today = await getStoryDate();
    var channels = await rpGet('rp_tg_channels', []);
    var posts = await rpGet('rp_tg_posts', []);

    for (var mi=0; mi<msgs.length; mi++){
      var m = msgs[mi];
      if (!m || m.role !== 'assistant' || !m.content) continue;
      var text = rpTagText(String(m.content));
      var blocks = parseTgChannelBlocks(text);
      if (!blocks.length) continue;
      for (var bi=0; bi<blocks.length; bi++){
        var b = blocks[bi];
        var channel = channels.find(function(c){ return c.name.trim().toLowerCase() === b.name.trim().toLowerCase(); });
        if (!channel){
          channel = { id: uid(), name: b.name.slice(0,40), description:'', kind:'generic', linkedContactId:null, owner:b.name,
            subscribed:true, subscriberCount:0, isPrivate:false, admins:[], createdAt: Date.now(), source:'bridge', hidden:false };
          channels.push(channel);
        }
        var subsNum = parseInt(String(b.subs).replace(/[^\d]/g,''), 10);
        if (!isNaN(subsNum)) channel.subscriberCount = subsNum;
        for (var pi=0; pi<b.posts.length; pi++){
          var bp = b.posts[pi];
          var dupe = posts.some(function(x){ return x.channelId===channel.id && x.text.trim().toLowerCase()===bp.text.trim().toLowerCase(); });
          if (dupe) continue;
          var viewsNum = parseInt(String(bp.views).replace(/[^\d]/g,''), 10);
          posts.unshift({
            id: uid(), channelId: channel.id, text: bp.text.slice(0,500), ts: Date.now(), dateLabel: today,
            views: isNaN(viewsNum) ? (50+Math.floor(Math.random()*5000)) : viewsNum,
            reactions:{}, userReaction:null,
            comments: bp.comments && bp.comments.length ? bp.comments : null,
            commentCount: bp.comments && bp.comments.length ? bp.comments.length : (2+Math.floor(Math.random()*18)),
            hidden:false, source:'bridge'
          });
          touched = true;
        }
      }
    }
    if (touched){
      var freshChannels = await rpGet('rp_tg_channels', []);
      channels.forEach(function(ch){
        var existing = freshChannels.find(function(x){ return x.id===ch.id; });
        if (existing){ existing.subscriberCount = ch.subscriberCount; }
        else { freshChannels.push(ch); }
      });
      var freshPosts = await rpGet('rp_tg_posts', []);
      var freshIds = {}; freshPosts.forEach(function(p){ freshIds[p.id]=true; });
      var newPosts = posts.filter(function(p){ return !freshIds[p.id]; });
      freshPosts = newPosts.concat(freshPosts);
      await rpSet('rp_tg_channels', freshChannels);
      await rpSet('rp_tg_posts', freshPosts.slice(0,400));
      if (panelOpen && currentScreen === 'channels'){
        var scope = $('.rp_ch_scope');
        if (scope) await renderChannelsBody(scope);
      } else {
        unreadCount++; updateBadge();
        pushHomeNotification('Канал', 'Новый пост в канале');
      }
    }
  }catch(e){ console.error('RP channel tag import failed', e); }
}

