function mapElbowPath(a, b){
  var dx = Math.abs(a.x-b.x), dy = Math.abs(a.y-b.y);
  if (dx > dy) return 'M '+a.x+' '+a.y+' L '+b.x+' '+a.y+' L '+b.x+' '+b.y;
  return 'M '+a.x+' '+a.y+' L '+a.x+' '+b.y+' L '+b.x+' '+b.y;
}
