  var energy = await rpGet('rp_smarthome_energy', null) || { forecast:'' };
  var dow = ['Пн','Вт','Ср','Чт','Пт','Сб','Вс'];
  var seed = rooms.length + 3;
  var weekly = dow.map(function(_,i){ return 2.5 + Math.abs(Math.sin(seed+i*1.3))*4; });
  var maxW = Math.max.apply(null, weekly);
