    '<div class="rp_bb_nav_btn rp_bb_glass" id="rp_bb_nav_ach"><svg><use href="#rpi-star"/></svg><span>Успехи</span></div>'+
    '<div class="rp_bb_nav_btn rp_bb_glass" id="rp_bb_nav_settings"><svg><use href="#rpi-gear"/></svg><span>Опции</span></div>';
  scope.appendChild(nav);
  $('#rp_bb_nav_shop', nav).addEventListener('click', function(){ bbRenderShop(scope); });
  $('#rp_bb_nav_stats', nav).addEventListener('click', function(){ bbRenderStats(scope); });
  $('#rp_bb_nav_ach', nav).addEventListener('click', function(){ bbRenderAchievements(scope); });
