function petIcon(id, size){
  var inner = PET_ICONS[id];
  if (!inner) inner = PET_ICONS.paw;
  return '<svg class="pt_ico" viewBox="0 0 48 48" width="'+(size||36)+'" height="'+(size||36)+'" xmlns="http://www.w3.org/2000/svg">'+inner+'</svg>';
}

function pPat(u, w, h, inner){ return '<pattern id="'+u+'" width="'+w+'" height="'+h+'" patternUnits="userSpaceOnUse">'+inner+'</pattern>'; }
