function petFindDecor(id){
  var lists = [PET_WALLS, PET_FLOORS, PET_FURN, PET_RUGS, PET_WINDOWS, PET_ARTS, PET_CEILS], i, f;
  for (i=0;i<lists.length;i++){ f = petFindIn(lists[i], id); if (f) return f; }
  return null;
}
function petApplyPromo(state, code, p){
  var rewards = [];
  if (p.c){ state.coins += p.c; rewards.push({ ico:'coin', t:'+'+p.c.toLocaleString('ru-RU')+' монет', s:'на счёт' }); }
  if (p.g){ state.gems += p.g; rewards.push({ ico:'gem', t:'+'+p.g.toLocaleString('ru-RU')+' кристаллов', s:'на счёт' }); }
  (p.acc || []).forEach(function(id){ var a = petFindIn(PET_ACCS, id); if (!a) return; var had = state.owned[id]; state.owned[id] = 1; rewards.push({ ico:'hanger', t:a.name, s: had ? 'уже было — в гардеробе' : 'новый аксессуар' }); });
  (p.dec || []).forEach(function(id){ var d = petFindDecor(id); if (!d) return; var had = state.owned[id]; state.owned[id] = 1; rewards.push({ ico:'house', t:d.name, s: had ? 'уже было' : 'для комнаты' }); });
  Object.keys(p.cons || {}).forEach(function(id){ var it = PET_CONS_ALL[id]; if (!it) return; state.inventory[id] = (state.inventory[id]||0) + p.cons[id]; rewards.push({ ico:it.icon, t:it.name+' ×'+p.cons[id], s:'в запас' }); });
  if (p.ach){ var a2 = PET_ACH_BY[p.ach]; if (a2){ state.ach = state.ach || {}; var had2 = !!state.ach[p.ach]; if (!had2) state.ach[p.ach] = Date.now(); rewards.push({ medal:a2, t:'Достижение: '+a2.name, s: had2 ? 'уже открыто' : a2.desc }); } }
  return rewards;
}
function petOpenPromo(state, scope){
  var sh = thSheet('<div style="font-weight:900;font-size:15px;margin-bottom:4px;">Промокод</div>'+
    '<div class="th_hint" style="margin-bottom:8px;">Введи код — получишь подарок: монеты, кристаллы, аксессуары, вещи для комнаты или достижение.</div>'+
    '<input class="rp_input" id="pt_code_in" maxlength="24" placeholder="КОД" autocapitalize="characters" autocomplete="off" style="text-transform:uppercase;letter-spacing:.08em;text-align:center;font-weight:900;">'+
    '<div class="th_row2" style="margin-top:12px;"><div class="th_btn ghost" id="pt_code_x">Закрыть</div><div class="th_btn" id="pt_code_ok">Активировать</div></div>');
  var inp = $('#pt_code_in', sh); setTimeout(function(){ try{ inp.focus(); }catch(e){} }, 60);
  $('#pt_code_x', sh).addEventListener('click', function(){ sh.remove(); });
  var go = async function(){
    var code = inp.value.toUpperCase().replace(/[^A-Z0-9А-ЯЁ]/g,'');
    if (!code){ toast('Впиши код'); return; }
    var hk = rpH(code), p = PET_PROMOS[hk];
    if (!p){ inp.classList.add('pt_shake'); setTimeout(function(){ inp.classList.remove('pt_shake'); }, 500); toast('Такого кода нет'); return; }
    state.promoUsed = state.promoUsed || {};
    if ((state.promoUsed[hk] || state.promoUsed[code]) && !p.admin){ toast('Этот код уже активирован'); return; }
    var rewards = petApplyPromo(state, code, p);
    state.promoUsed[hk] = Date.now();
    await rpSet('rp_pet_state', state);
    await petAddFeedLog('user', p.admin ? 'активировал(а) служебный код' : 'активировал(а) промокод и получил(а) подарок');
    sh.remove();
    petPlayGiftAnim(rewards, p.admin, function(){ renderPetBody(scope); });
  };
  $('#pt_code_ok', sh).addEventListener('click', go);
  inp.addEventListener('keydown', function(e){ if (e.key === 'Enter') go(); });
}
