async function renderPetBody(scope){
  petClearTimer();
  scope.innerHTML = '';
  var state = await rpGet('rp_pet_state', null);
  if (!state){ state = petDefaultState(); }
  petMigrate(state);
  petApplyDecay(state);
  await rpSet('rp_pet_state', state);

  var top = el('div','rp_pet_topbar');
  top.innerHTML = '<div class="rp_pet_coins"><span>'+petIcon('coin',20)+state.coins.toLocaleString()+'</span><span>'+petIcon('gem',20)+state.gems+'</span></div>'+
    '<div style="display:flex;gap:8px;"><div class="pt_gift" id="pt_promo" title="Промокод" style="opacity:1;">'+petIcon('ticket',22)+'</div><div class="pt_gift'+(petGiftReady(state)?' ready':'')+'" id="pt_gift" title="Подарок раз в 4 часа">'+petIcon('gift',22)+'</div></div>';
  scope.appendChild(top);
  $('#pt_gift', top).addEventListener('click', function(){ petClaimGift(state, scope); });
  $('#pt_promo', top).addEventListener('click', function(){ petOpenPromo(state, scope); });

  var body = el('div','rp_pet_body');
  scope.appendChild(body);
  petGuard(body);
  var navDefs = [{ id:'home', label:'Дом', ic:'house' },{ id:'selector', label:'Питомцы', ic:'paw' },{ id:'shop', label:'Магазин', ic:'bag' },{ id:'games', label:'Игры', ic:'gamepad' },{ id:'partner', label:'Пара', ic:'heart' }];
  var nav = el('div','pt_bottombar');
  nav.innerHTML = navDefs.map(function(n){ return '<div class="pt_nav'+(petActiveTab===n.id?' on':'')+'" data-tab="'+n.id+'">'+petIcon(n.ic,26)+'<span>'+n.label+'</span></div>'; }).join('');
  nav.querySelectorAll('.pt_nav').forEach(function(n){ n.addEventListener('click', function(){ if (petBusy) return; petActiveTab = n.getAttribute('data-tab'); var sc = scope.closest('#rp_screens'); renderPetBody(scope).then(function(){ if (sc) sc.scrollTop = 0; }); }); });
  var navAdded = false;
  if (petActiveTab==='home'){
    if (state.reveal) petRenderReveal(body, state, scope);
    else if (!state.activePetId) await petRenderEggStage(body, state, scope);
    else await renderPetHome(body, state, scope);
  }
  else if (petActiveTab==='selector') await renderPetSelector(body, state, scope);
  else if (petActiveTab==='shop') await renderPetShop(body, state, scope);
  else if (petActiveTab==='games') await renderPetGames(body, state, scope);
  else if (petActiveTab==='partner') await renderPetPartner(body, state, scope);
  scope.appendChild(nav);
}
async function petRenderEggStage(container, state, scope){
  container.innerHTML = '';
  if (!state.egg){
    var intro = el('div','pt_intro');
    intro.innerHTML = '<div class="pt_intro_egg">'+petEggSVG('egg_basic', 0)+'</div><div class="pt_intro_t">У тебя пока нет малыша</div><div class="pt_intro_s">Купи яйцо и согрей его. Кто вылупится — решит случай: бывают и обычные, и редкие, и даже легендарные.</div>';
    container.appendChild(intro);
    var list = el('div','pt_eggs');
    list.innerHTML = PET_EGGS.map(function(e){
      var cost = e.gems ? petIcon('gem',16)+e.gems : petIcon('coin',16)+e.price;
      return '<div class="pt_egg_card"><div class="pt_egg_pic">'+petEggSVG(e.id, 0)+'</div><div class="pt_egg_info"><div class="pt_egg_n">'+e.name+'</div><div class="pt_egg_d">'+e.desc+' · греть '+e.mins+' мин</div></div><div class="pt_buy" data-egg="'+e.id+'">'+cost+'</div></div>';
    }).join('');
    container.appendChild(list);
    list.querySelectorAll('[data-egg]').forEach(function(b){
      b.addEventListener('click', async function(){ if (await petBuyEgg(state, b.getAttribute('data-egg'))) await renderPetBody(scope); });
    });
    return;
  }
  var egg = petFindIn(PET_EGGS, state.egg.type) || PET_EGGS[0], total = (egg.mins||12)*60000;
  var wrap = el('div','pt_eggscene');
  wrap.innerHTML = '<div class="pt_egg_t">'+egg.name+'</div><div class="pt_eggbig" id="pt_eggbig"></div><div class="pt_egg_timer" id="pt_egg_timer"></div>'+
    '<div class="pt_egg_prog"><div id="pt_egg_fill"></div></div>'+
    '<div class="pt_egg_btns" id="pt_egg_btns"></div>';
  container.appendChild(wrap);
  var draw = function(){
    var left = petEggLeft(state), ready = left <= 0, prog = Math.max(0, Math.min(1, 1 - left/total));
    $('#pt_eggbig', wrap).innerHTML = '<div class="'+(ready?'pt_egg_ready':'pt_egg_wobble')+'">'+petEggSVG(state.egg.type, prog, ready)+'</div>';
    $('#pt_egg_timer', wrap).textContent = ready ? 'Готово! Малыш просится наружу' : 'Осталось '+petFmtTime(left);
    $('#pt_egg_fill', wrap).style.width = Math.round(prog*100)+'%';
    var warmLeft = (state.egg.warmAt||0) + 5*60000 - Date.now();
    $('#pt_egg_btns', wrap).innerHTML = ready
      ? '<div class="pt_big" id="pt_hatch">Вылупить</div>'
      : '<div class="pt_btn2'+(warmLeft>0?' off':'')+'" id="pt_warm">'+petIcon('sun',18)+'<span>'+(warmLeft>0 ? 'Согреть через '+petFmtTime(warmLeft) : 'Согреть −2 мин')+'</span></div>'+
        '<div class="pt_btn2 gem" id="pt_speed">'+petIcon('gem',18)+'<span>Ускорить −10 мин · 1</span></div>'+
        '<div class="pt_btn2 gem" id="pt_now">'+petIcon('gem',18)+'<span>Вылупить сразу · '+Math.max(1, Math.ceil(left/60000/6))+'</span></div>';
    var hb = $('#pt_hatch', wrap); if (hb) hb.addEventListener('click', async function(){ await petHatch(state); await renderPetBody(scope); });
    var wb = $('#pt_warm', wrap); if (wb) wb.addEventListener('click', async function(){
      if ((state.egg.warmAt||0) + 5*60000 > Date.now()) return;
      state.egg.warmAt = Date.now(); state.egg.hatchAt -= 2*60000; await rpSet('rp_pet_state', state); toast('Яйцо стало тёплым'); draw();
    });
    var sb = $('#pt_speed', wrap); if (sb) sb.addEventListener('click', async function(){
      if (state.gems < 1){ toast('Нужен 1 кристалл'); return; }
      state.gems -= 1; state.egg.hatchAt -= 10*60000; await rpSet('rp_pet_state', state); await renderPetBody(scope);
    });
    var nb = $('#pt_now', wrap); if (nb) nb.addEventListener('click', async function(){
      var cost = Math.max(1, Math.ceil(petEggLeft(state)/60000/6));
      if (state.gems < cost){ toast('Нужно кристаллов: '+cost); return; }
      state.gems -= cost; state.egg.hatchAt = Date.now(); await rpSet('rp_pet_state', state); await renderPetBody(scope);
    });
  };
  draw();
  petTimer = setInterval(function(){
    if (!document.body.contains(wrap)){ petClearTimer(); return; }
    if (!panelOpen) return;
    var left = petEggLeft(state);
    if (left <= 0){ petClearTimer(); draw(); return; }
    $('#pt_egg_timer', wrap).textContent = 'Осталось '+petFmtTime(left);
    $('#pt_egg_fill', wrap).style.width = Math.round(Math.max(0, Math.min(1, 1 - left/total))*100)+'%';
    if ((state.egg.warmAt||0) + 5*60000 - Date.now() <= 1000 && $('#pt_warm', wrap) && $('#pt_warm', wrap).classList.contains('off')) draw();
  }, 1000);
}
