async function satRadar(){ return Object.assign({ chaos:78, night:92, humor:85, filters:[] }, await rpGet('rp_tinder_radar', null) || {}); }
async function satKarma(){ var k = await rpGet('rp_tinder_karma', 666); return Number(k)||0; }
async function satAddKarma(n){ var k = (await satKarma()) + n; await rpSet('rp_tinder_karma', k); var b = $('#sat_karma_n'); if (b) b.textContent = k; return k; }
function satSynergy(p, r){
  var d = (Math.abs((p.chaos||50)-r.chaos) + Math.abs((p.night||50)-r.night) + Math.abs((p.humor||50)-r.humor)) / 3;
  var bonus = 0; (p.tags||[]).forEach(function(t){ if ((r.filters||[]).indexOf(t) !== -1) bonus += 4; });
  return satClamp(99 - d*0.9 + bonus, 52, 99);
}
