async function tdGenerateDeck(){
  var me = await tdMe();
  var radar = await satRadar();
  var seen = await rpGet('rp_tinder_seen', []);
  var card = await getCharCard();
  var pool = TD_ARCHETYPES.slice().sort(function(){ return Math.random()-0.5; }).slice(0,6);
  var showTxt = me.show==='f' ? 'только девушки' : (me.show==='m' ? 'только парни' : 'смесь парней и девушек');
  var prompt = 'Придумай 6 вымышленных анкет людей из тёмного приложения для знакомств SATINDER («Пары, рождённые в глубине») в мире этой истории. Тон приложения: мрачный, остроумный, чуть демонический, с чёрным юмором, но анкеты — обычные живые люди. Кого показываем: '+showTxt+'.'+
    (card.facts ? '\nФон мира/истории (город, эпоха, атмосфера): '+String(card.facts).slice(0,600) : '')+
    (radar.filters.length ? '\nПредпочтения пользователя по вайбу: '+radar.filters.join(', ')+' — часть анкет должна им соответствовать.' : '')+
    (seen.length ? '\nЭти имена уже были, не повторяй: '+seen.slice(-30).join(', ') : '')+
    '\nУ каждого свой характер общения, он влияет на то, как человек пишет о себе:\n'+
    pool.map(function(a,i){ return (i+1)+'. '+a.name+' — '+a.voice; }).join('\n')+
    '\n\nДоступные теги (выбери ровно 3 на человека, разделяй «;», пиши точно как в списке): '+SAT_TAGS.join('; ')+'.'+
    '\n\nФормат СТРОГО 6 строк, по одной на анкету, в том же порядке, без нумерации и пояснений. Поля через « | »:\n'+
    'Имя | возраст (18-35) | расстояние (число км) | био на русском, 1-2 предложения, в манере этого человека | внешность на английском, одна фраза: пол, волосы, телосложение, одежда, особая примета | хаос 0-100 | ночная энергия 0-100 | чёрный юмор 0-100 | 3 тега через ; | ледокол: одна дерзкая шутка-подкол про этого человека на русском | главный грех (2-3 слова) | тайная добродетель (2-3 слова)';
  var raw = await callModel(prompt);
  var lines = splitKeyValueLines(String(raw||''));
  var out = [];
  lines.forEach(function(line){
    var p = line.split('|').map(function(x){ return x.trim(); });
    if (p.length < 5 || !p[0]) return;
    var a = pool[out.length];
    if (!a) return;
    var tags = (p[8]||'').split(';').map(function(t){ return t.trim(); }).filter(function(t){ return SAT_TAGS.indexOf(t) !== -1; });
    for (var ti = satRand(0, SAT_TAGS.length-1), tg = 0; tags.length < 3 && tg < SAT_TAGS.length; tg++, ti++){ var rt = SAT_TAGS[ti % SAT_TAGS.length]; if (tags.indexOf(rt) === -1) tags.push(rt); }
    var prof = { id: uid(), name: p[0].slice(0,24), age: parseInt(p[1],10)||24, distance: (parseInt(p[2],10)||3)+' км от вас', bio: (p[3]||'').slice(0,240), look: (p[4]||'').slice(0,300), style: a.id, img:null,
      chaos: satClamp(p[5] || satRand(45,100), 0, 100), night: satClamp(p[6] || satRand(55,100), 0, 100), humor: satClamp(p[7] || satRand(60,100), 0, 100),
      tags: tags.slice(0,3), roast: (p[9]||'').slice(0,200) || 'Наверняка полчаса выбирает, что посмотреть, и засыпает на титрах.', sin: (p[10]||'').slice(0,40), virtue: (p[11]||'').slice(0,40) };
    prof.synergy = satSynergy(prof, radar);
    out.push(prof);
  });
  return out;
}
async function satSummon(container, replace){
  if (SAT_GEN_BUSY) return false;
  SAT_GEN_BUSY = true;
  try{
    var list = await tdGenerateDeck();
    if (!list.length) return false;
    await tdDeckUpdate(function(d){ if (replace) d.length = 0; list.forEach(function(x){ d.push(x); }); });
    return true;
  }finally{ SAT_GEN_BUSY = false; }
}
function satMaybePrefetch(deck, container){
  if (deck.length > 2 || SAT_GEN_BUSY) return;
  satSummon(container, false).catch(function(e){ console.error('RP satinder prefetch failed', e); });
}
async function satRenderSwipe(main, container){
  var pane = el('div','sat_pane'); main.appendChild(pane);
  var deck = await rpGet('rp_tinder_deck', []);
  var radar = await satRadar();
  deck.forEach(function(p){ if (p.chaos == null){ p.chaos = satRand(45,100); p.night = satRand(55,100); p.humor = satRand(60,100); } if (!p.tags || !p.tags.length){ p.tags = [SAT_TAGS[satRand(0,11)], SAT_TAGS[satRand(0,11)]]; } if (!p.roast) p.roast = 'Тайно слушает попсу нулевых, когда никто не видит.'; if (p.synergy == null) p.synergy = satSynergy(p, radar); });
  pane.appendChild(el('div','sat_glass sat_radar_bar','<b>'+satIco('rpi-sat-bolt')+' Радар душ активен</b><span class="sat_pill">'+deck.length+' анкет</span>'));
  if (!deck.length){
    var empty = el('div','sat_empty');
    empty.innerHTML = '<div class="em">👻</div><h3>Бездна пуста!</h3><p>Ты пролистал все души в своём царстве.</p><div class="sat_cta" id="sat_find">'+satIco('rpi-sparkle')+'<span>Призвать новые души</span></div>';
    pane.appendChild(empty);
    wireBusyButton($('#sat_find', empty), 'tinder-find', async function(){
      var ok = await satSummon(container, true);
      if (!ok){ satToast('Не получилось призвать — попробуй ещё раз'); return; }
      if (TD_LIVE && TD_LIVE.isConnected && satTab === 'swipe') await satRender(TD_LIVE);
    });
    return;
  }
  var prof = deck[0];
  var stage = el('div','sat_deck'); pane.appendChild(stage);
  for (var bi = Math.min(2, deck.length-1); bi >= 1; bi--){
    var back = el('div','sat_card back'); back.style.transform = 'translateY('+(bi*11)+'px) scale('+(1-bi*0.045)+')'; back.style.zIndex = 20-bi; back.style.opacity = bi === 1 ? '.85' : '.6';
    stage.appendChild(back);
  }
  var cardEl = el('div','sat_card'); cardEl.setAttribute('data-pid', prof.id); cardEl.style.zIndex = 30;
  stage.appendChild(cardEl);
  satFillCard(cardEl, prof);
  var acts = el('div','sat_acts');
  acts.innerHTML = '<div class="sat_btn no" data-a="nope">'+satIco('rpi-x')+'</div>'+
    '<div class="sat_btn roast" data-a="roast">'+satIco('rpi-sat-masks')+'</div>'+
    '<div class="sat_btn sup" data-a="super">'+satIco('rpi-sat-trident')+'</div>'+
    '<div class="sat_btn syn" data-a="syn">'+satIco('rpi-sat-pie')+'</div>'+
    '<div class="sat_btn yes" data-a="like">'+satIco('rpi-heart-fill')+'</div>';
  pane.appendChild(acts);
  var busy = false;
  async function decide(kind, roastText){
    if (busy) return; busy = true;
    satSwipeSound(kind);
    cardEl.classList.remove('drag');
    cardEl.style.transform = kind==='nope' ? 'translate(-480px,60px) rotate(-28deg)' : (kind==='super' ? 'translate(0,-620px)' : 'translate(480px,-40px) rotate(28deg)');
    cardEl.style.opacity = '0';
    await new Promise(function(r){ setTimeout(r, 230); });
    await satSwipe(prof, kind, container, roastText);
  }
  acts.querySelectorAll('[data-a]').forEach(function(b){
    b.addEventListener('click', function(){
      var a = b.getAttribute('data-a');
      if (a === 'roast') satRoastModal(prof, function(txt){ decide('like', txt); });
      else if (a === 'syn') satSynergyModal(prof);
      else decide(a);
    });
  });
  var sx = 0, sy = 0, dx = 0, dy = 0, drag = false;
  cardEl.addEventListener('pointerdown', function(e){ drag = true; sx = e.clientX; sy = e.clientY; dx = 0; dy = 0; cardEl.classList.add('drag'); try{ cardEl.setPointerCapture(e.pointerId); }catch(_){} });
  cardEl.addEventListener('pointermove', function(e){
    if (!drag) return;
    dx = e.clientX - sx; dy = e.clientY - sy;
    cardEl.style.transform = 'translate('+dx+'px,'+dy+'px) rotate('+(dx*0.06)+'deg)';
    var lk = cardEl.querySelector('.sat_stamp.like'), np = cardEl.querySelector('.sat_stamp.nope'), sp = cardEl.querySelector('.sat_stamp.sup');
    if (lk) lk.style.opacity = dx>30 ? Math.min(1, dx/100) : 0;
    if (np) np.style.opacity = dx<-30 ? Math.min(1, -dx/100) : 0;
    if (sp) sp.style.opacity = (dy<-50 && Math.abs(dx)<60) ? Math.min(1, -dy/100) : 0;
  });
  function endDrag(){
    if (!drag) return; drag = false; cardEl.classList.remove('drag');
    if (dx > 110) decide('like');
    else if (dx < -110) decide('nope');
    else if (dy < -110) decide('super');
    else { cardEl.style.transform = ''; cardEl.querySelectorAll('.sat_stamp').forEach(function(x){ x.style.opacity = 0; }); }
  }
  cardEl.addEventListener('pointerup', endDrag);
  cardEl.addEventListener('pointercancel', endDrag);
  tdEnsureDeckPhotos(deck);
  satMaybePrefetch(deck, container);
}
async function tdEnsureDeckPhotos(deck){
  if (!(await imagesEnabled())) return;
  deck.slice(0,3).forEach(function(pr){ tdEnsureCardPhoto(pr); });
}
function satFillCard(cardEl, prof){
  var media;
  if (prof.img) media = '<img class="sat_img" src="'+escapeHtml(prof.img)+'" alt="">';
  else {
    var status = TD_BUSY[prof.id] ? '⏳ Вызываю образ…' : (prof.imgFailed ? '⚠️ Фото не вышло — нажми, чтобы повторить'+(prof.imgErr?'<div style="font-size:9px;font-weight:400;opacity:.85;margin-top:6px;word-break:break-word;">'+escapeHtml(prof.imgErr)+'</div>':'') : '');
    media = '<div class="sat_ph" data-retry="1"><div class="ini">'+escapeHtml(prof.name.charAt(0).toUpperCase())+'</div><div>'+status+'</div></div>';
  }
  cardEl.innerHTML = media+'<div class="sat_shade"></div>'+
    '<div class="sat_mbadge">'+satIco('rpi-flame')+'<span>'+(prof.synergy||0)+'% совпадение душ</span></div>'+
    '<div class="sat_stamp like">ДУШЕВНАЯ ПАРА</div><div class="sat_stamp nope">ИЗГНАТЬ</div><div class="sat_stamp sup">СДЕЛКА С ДЬЯВОЛОМ</div>'+
    '<div class="sat_info"><div class="sat_name">'+escapeHtml(prof.name)+'<span>'+prof.age+'</span></div><div class="sat_dist">📍 '+escapeHtml(prof.distance)+'</div>'+
    '<div class="sat_bio"><div class="t">'+escapeHtml(prof.bio)+'</div></div>'+
    '<div class="sat_tags">'+(prof.tags||[]).map(function(t){ return '<span class="sat_tag">'+escapeHtml(t)+'</span>'; }).join('')+'</div></div>';
  var ph = cardEl.querySelector('[data-retry]');
  var bioEl = cardEl.querySelector('.sat_bio');
  if (bioEl){ bioEl.addEventListener('pointerdown', function(e){ e.stopPropagation(); }); bioEl.addEventListener('click', function(e){ e.stopPropagation(); bioEl.classList.toggle('open'); }); }
  if (ph) ph.addEventListener('click', function(){ if (!TD_BUSY[prof.id]){ prof.imgFailed = false; tdEnsureCardPhoto(prof, true); } });
}
async function tdGeneratePhoto(look, extra, aspect, refImg){
  var cfg = Object.assign({}, await getImgConfig(), { aspectRatio: aspect||'4:5', noPassports:true, galleryTag:'Satinder' });
  var refs = refImg ? [{ label:'Same person as in this reference photo — keep the exact same face, hair and look', img: refImg }] : [];
  return await rpGenerateImage(buildChatImagePrompt(look + (extra ? ', '+extra : ''), null), cfg, refs);
}
async function tdEnsureCardPhoto(prof, force){
  if (prof.img || TD_BUSY[prof.id]) return;
  if (!(await imagesEnabled())) return;
  if (prof.imgFailed && !force) return;
  TD_BUSY[prof.id] = true;
  var live = document.querySelector('.sat_card[data-pid="'+prof.id+'"]');
  if (live) satFillCard(live, prof);
  var url = null;
  try{ url = await tdGeneratePhoto(prof.look, 'dating app profile photo, moody dramatic lighting, flattering natural pose, looking at camera', '4:5'); }
  catch(e){ console.error('RP satinder photo failed', e); prof.imgErr = String(e && e.message ? e.message : e).slice(0,220); }
  delete TD_BUSY[prof.id];
  await tdDeckUpdate(function(deck){
    var rec = deck.find(function(d){ return d.id === prof.id; });
    if (rec){ if (url){ rec.img = url; rec.imgFailed = false; } else rec.imgFailed = true; }
  });
  prof.img = url || null; prof.imgFailed = !url;
  live = document.querySelector('.sat_card[data-pid="'+prof.id+'"]');
  if (live) satFillCard(live, prof);
}
async function satSwipe(prof, kind, container, roastText){
  await tdDeckUpdate(function(d){ var i = d.findIndex(function(x){ return x.id === prof.id; }); if (i !== -1) d.splice(i,1); });
  var seen = await rpGet('rp_tinder_seen', []);
  seen.push(prof.name); await rpSet('rp_tinder_seen', seen.slice(-80));
  var chance = kind==='like' ? 0.75 : (kind==='super' ? 1 : 0);
  if (Math.random() < chance){ await satMakeMatch(prof, kind, container, roastText); return; }
  if (kind === 'like' && roastText) satToast('Подкол не сработал — не повезло');
  await satRender(container);
}
function satModal(html, onClose){
  var m = el('div','sat_modal'); m.innerHTML = html; SAT_APP.appendChild(m);
  var close = function(){ m.remove(); if (onClose) onClose(); };
  m.querySelectorAll('[data-close]').forEach(function(b){ b.addEventListener('click', close); });
  return { el: m, close: function(){ m.remove(); } };
}
function satRoastModal(prof, onUse){
  satTone(450, 'sine', .1);
  var md = satModal('<div class="sat_sheet"><div class="sat_x" data-close>'+satIco('rpi-x')+'</div><div style="font-size:30px;">🎭</div><h3>Ледокол-подкол</h3>'+
    '<div class="sat_roast_txt">«'+escapeHtml(prof.roast||'')+'»</div><div class="sat_cta full" id="sat_roast_use"><span>Отправить первым сообщением</span></div></div>');
  $('#sat_roast_use', md.el).addEventListener('click', function(){ var t = prof.roast; md.close(); onUse(t); });
}
function satSynergyModal(prof){
  var rows = [['Совместимость хаоса', prof.chaos, '#ff2a5f'], ['Ночное созвучие', prof.night, '#ffd700'], ['Чёрный юмор', prof.humor, '#a855f7']];
  satModal('<div class="sat_sheet gold"><div class="sat_x" data-close>'+satIco('rpi-x')+'</div><h3 style="color:#ffd700;">Синергия душ</h3>'+
    '<div style="font-size:11px;color:#94a3b8;">Глубокий резонанс с '+escapeHtml(prof.name)+' — '+(prof.synergy||0)+'%</div>'+
    rows.map(function(r){ return '<div class="sat_syn_row"><div class="l"><span>'+r[0]+'</span><b style="color:'+r[2]+'">'+r[1]+'%</b></div><div class="sat_bar"><i style="width:'+r[1]+'%;background:'+r[2]+'"></i></div></div>'; }).join('')+
    '<div class="sat_cta ghost full" data-close style="margin-top:6px;"><span>Закрыть</span></div></div>');
}
async function satMakeMatch(prof, kind, container, roastText){
  var matches = await rpGet('rp_tinder_matches', []);
  var m = { id: uid(), pid: prof.id, name: prof.name, age: prof.age, bio: prof.bio, look: prof.look, style: prof.style, img: prof.img||null, tags: prof.tags||[], synergy: prof.synergy||0, sin: prof.sin||'', virtue: prof.virtue||'', bargain: kind==='super', matchedAt: Date.now(), unread: 0, lastTs: Date.now() };
  matches.unshift(m);
  await rpSet('rp_tinder_matches', matches);
  await satAddKarma(kind === 'super' ? 66 : 25);
  satTone(880, 'triangle', .3);
  var me = await tdMe(); var myAv = await satMyAvatar(me);
  if (!SAT_APP || !SAT_APP.isConnected || currentScreen !== 'tinder'){ satStartConversation(m, roastText); return; }
  var md = satModal('<div class="sat_match_ava"><div class="a a1">'+satAv(me.name, myAv)+'</div><div class="a a2">'+satAv(m.name, m.img)+'</div><div class="h">'+satIco('rpi-heart-fill')+'</div></div>'+
    '<div class="sat_match_t">СДЕЛКА СКРЕПЛЕНА!</div>'+
    '<div style="font-size:12.5px;color:#cbd5e1;max-width:260px;margin-bottom:18px;">'+(kind==='super' ? 'Ты заключил <b style="color:#ffd700;">сделку с дьяволом</b>: ' : 'Вы и ')+'<b style="color:#ffd700;">'+escapeHtml(m.name)+'</b>'+(kind==='super' ? '!' : ' связали свои судьбы — '+m.synergy+'% совпадения душ.')+'</div>'+
    '<div style="width:100%;max-width:260px;display:flex;flex-direction:column;gap:9px;"><div class="sat_cta full" id="sat_m_chat">'+satIco('rpi-send')+'<span>Написать первым</span></div><div class="sat_cta ghost full" id="sat_m_go"><span>Листать дальше</span></div></div>');
  md.el.querySelector('#sat_m_go').addEventListener('click', function(){ md.close(); satRender(container); });
  md.el.querySelector('#sat_m_chat').addEventListener('click', function(){ md.close(); satTab = 'bonds'; tdOpenId = m.id; satRender(container); });
  satStartConversation(m, roastText);
}
function satStartConversation(m, roastText){
  if (roastText){
    tdPushMsg(m.id, { id: uid(), from:'me', kind:'text', text: roastText, ts: Date.now() }).then(function(){ tdReply(m.id); });
  } else tdOpenerFor(m);
}
async function tdOpenerFor(m){
  TD_REPLYING[m.id] = true;
  var text = '';
  try{
    var me = await tdMe();
    var a = tdArch(m.style);
    var prompt = 'Ты — '+m.name+', '+m.age+', в тёмном приложении для знакомств SATINDER. Био: «'+m.bio+'». Твой характер общения: '+a.name+' — '+a.voice+'.\n'+
      (m.bargain ? 'Тебя только что «купили» суперлайком — «сделкой с дьяволом»; можешь это обыграть.\n' : '')+
      'Вы с '+me.name+' только что получили пару. Напиши первое сообщение ей/ему строго в своём характере: одна-две короткие фразы на русском, как в мессенджере, без кавычек и пояснений.';
    text = String(await callModel(prompt)||'').trim().replace(/^["«]|["»]$/g,'').slice(0,400);
  }catch(e){ console.error('RP satinder opener failed', e); }
  if (!text) text = 'Привет 😈';
  await tdPushMsg(m.id, { id: uid(), from:'them', kind:'text', text:text, ts: Date.now() });
  delete TD_REPLYING[m.id];
  tdRefreshChatUI(m.id);
}
async function tdPushMsg(mid, msg){
  var key = 'rp_tinder_msgs_'+mid;
  var list = await rpGet(key, []);
  list.push(msg);
  await rpSet(key, list.slice(-300));
  var matches = await rpGet('rp_tinder_matches', []);
  var m = matches.find(function(x){ return x.id === mid; });
  if (m){
    m.lastTs = msg.ts;
    m.last = msg.kind==='photo' ? '📷 Фото' : msg.text;
    if (msg.from === 'them' && tdOpenId !== mid) m.unread = (m.unread||0) + 1;
    await rpSet('rp_tinder_matches', matches);
  }
}
function tdRefreshChatUI(mid){
  if (!TD_LIVE || !TD_LIVE.isConnected || currentScreen !== 'tinder') return;
  if (tdOpenId === mid){ var box = TD_LIVE.querySelector('.sat_msgs'); if (box) tdDrawMsgs(box, mid); }
  else if (tdOpenId === null && satTab === 'bonds') satRender(TD_LIVE);
  else if (satTab !== 'bonds'){ var n = TD_LIVE.querySelector('.sat_nav_it[data-t="bonds"]'); if (n && !n.querySelector('.sat_nav_dot')) n.insertAdjacentHTML('beforeend','<i class="sat_nav_dot"></i>'); }
}
async function satRenderBonds(main, container){
  tdOpenId = null;
  var pane = el('div','sat_pane'); main.appendChild(pane);
  var matches = await rpGet('rp_tinder_matches', []);
  pane.appendChild(el('h2','sat_h2','<span>Узы и пары</span><small>'+matches.length+' активных</small>'));
  if (!matches.length){ pane.appendChild(el('div','sat_empty','<div class="em">🕯️</div><h3>Пока одиноко</h3><p>Ставь ❤️ в ленте — после взаимной симпатии здесь появится переписка.</p>')); return; }
  pane.appendChild(el('div','sat_lbl','Новые договоры'));
  var strip = el('div','sat_strip');
  strip.innerHTML = matches.slice(0,12).map(function(m){ return '<div class="sat_strip_it" data-id="'+m.id+'"><div class="sat_ring">'+satAv(m.name, m.img)+'</div><span>'+escapeHtml(m.name)+'</span></div>'; }).join('');
  pane.appendChild(strip);
  strip.querySelectorAll('[data-id]').forEach(function(it){ it.addEventListener('click', function(){ tdOpenId = it.getAttribute('data-id'); satRender(container); }); });
  pane.appendChild(el('div','sat_lbl','Беседы'));
  var wrap = el('div'); pane.appendChild(wrap);
  var sorted = matches.slice().sort(function(a,b){ return (b.lastTs||0)-(a.lastTs||0); });
  wrap.innerHTML = sorted.map(function(m){
    return '<div class="sat_row" data-id="'+m.id+'"><div class="rp_del_btn">'+RP_DEL_ICON+'</div>'+satAv(m.name, m.img)+
      '<div class="sat_row_main"><div class="sat_row_top"><span>'+escapeHtml(m.name)+', '+m.age+'</span><small>'+escapeHtml(tdTime(m.lastTs))+'</small></div><div class="sat_row_last">'+escapeHtml(TD_REPLYING[m.id] ? 'печатает…' : (m.last||'Новая пара'))+'</div></div>'+
      (m.unread ? '<div class="sat_unread">'+m.unread+'</div>' : '')+'</div>';
  }).join('');
  wrap.querySelectorAll('.sat_row').forEach(function(r){
    r.addEventListener('click', function(ev){
      if (ev.target.closest && ev.target.closest('.rp_del_btn')) return;
      if (r.classList.contains('rp_del_armed')) return;
      tdOpenId = r.getAttribute('data-id'); satRender(container);
    });
  });
  rpWireLongPressDelete(wrap, '.sat_row[data-id]', async function(id){
    var list = await rpGet('rp_tinder_matches', []);
    await rpSet('rp_tinder_matches', list.filter(function(x){ return x.id !== id; }));
    await rpSet('rp_tinder_msgs_'+id, []);
    satToast('Связь разорвана');
    await satRender(container);
  });
}
async function tdDrawMsgs(box, mid){
  var msgs = await rpGet('rp_tinder_msgs_'+mid, []);
  box.innerHTML = msgs.map(function(m){
    var cls = 'sat_msg '+(m.from==='me'?'me':'them');
    if (m.kind === 'photo'){
      var inner;
      if (m.url) inner = '<img src="'+escapeHtml(m.url)+'" alt="">';
      else {
        var live = m.pending && (Date.now() - (m.at||0) < 180000);
        inner = '<div class="sat_phph" data-retry="'+m.id+'">'+(live ? '⏳<span>Фото загружается…</span>' : '⚠️<span>Не вышло. Нажми, чтобы повторить</span>')+'</div>';
      }
      return '<div class="'+cls+' photo" data-mid="'+m.id+'">'+inner+'<span class="t">'+escapeHtml(tdTime(m.ts))+'</span></div>';
    }
    return '<div class="'+cls+'">'+escapeHtml(m.text)+'<span class="t">'+escapeHtml(tdTime(m.ts))+'</span></div>';
  }).join('') + (TD_REPLYING[mid] ? '<div class="sat_typing">● ● ●</div>' : '');
  box.querySelectorAll('[data-retry]').forEach(function(p){
    p.addEventListener('click', function(){ tdRetryPhoto(mid, p.getAttribute('data-retry')); });
  });
  box.scrollTop = box.scrollHeight;
}
async function satRenderChat(main, container, mid){
  var matches = await rpGet('rp_tinder_matches', []);
  var m = matches.find(function(x){ return x.id === mid; });
  if (!m){ tdOpenId = null; return satRenderBonds(main, container); }
  if (m.unread){ m.unread = 0; await rpSet('rp_tinder_matches', matches); var dot = container.querySelector('.sat_nav_dot'); if (dot && !matches.some(function(x){ return x.unread; })) dot.remove(); }
  var a = tdArch(m.style);
  var wrap = el('div','sat_chat'); main.appendChild(wrap);
  wrap.innerHTML = '<div class="sat_chat_head"><div class="sat_ic" id="sat_back">'+satIco('rpi-back')+'</div><div style="width:40px;height:40px;flex-shrink:0;">'+satAv(m.name, m.img)+'</div>'+
    '<div class="sat_chat_who"><div class="sat_chat_name">'+escapeHtml(m.name)+', '+m.age+'</div><div class="sat_chat_st"><i></i>шепчет из бездны · '+escapeHtml(a.name)+'</div></div>'+
    '<div class="sat_spicy" id="sat_spicy">'+satIco('rpi-sparkle')+'<span>Остренько</span></div></div>'+
    '<div class="sat_msgs"></div>'+
    '<div class="sat_inbar"><input class="sat_in" id="sat_input" placeholder="Шепни свой секрет…"><div class="sat_send" id="sat_send">'+satIco('rpi-send')+'</div></div>';
  var box = $('.sat_msgs', wrap);
  await tdDrawMsgs(box, mid);
  $('#sat_back', wrap).addEventListener('click', function(){ tdOpenId = null; satRender(container); });
  var input = $('#sat_input', wrap);
  async function send(text){
    text = (text || input.value).trim();
    if (!text || TD_REPLYING[mid]) return;
    if (!arguments[0]) input.value = '';
    satTone(700, 'sine', .1);
    await tdPushMsg(mid, { id: uid(), from:'me', kind:'text', text:text, ts: Date.now() });
    await tdDrawMsgs(box, mid);
    tdReply(mid);
  }
  $('#sat_send', wrap).addEventListener('click', function(){ send(); });
  $('#sat_spicy', wrap).addEventListener('click', function(){ send(SAT_SPICY[satRand(0, SAT_SPICY.length-1)]); });
  input.addEventListener('keydown', function(e){ if (e.key === 'Enter'){ e.preventDefault(); send(); } });
}
async function tdReply(mid){
  TD_REPLYING[mid] = true;
  tdRefreshChatUI(mid);
  var matches = await rpGet('rp_tinder_matches', []);
  var m = matches.find(function(x){ return x.id === mid; });
  if (!m){ delete TD_REPLYING[mid]; return; }
  var me = await tdMe();
  var hist = (await rpGet('rp_tinder_msgs_'+mid, [])).slice(-14).map(function(x){ return (x.from==='me' ? me.name : m.name)+': '+(x.kind==='photo' ? '[прислал(а) фото]' : x.text); }).join('\n');
  var a = tdArch(m.style);
  var photoOn = await imagesEnabled();
  var prompt = 'Ты играешь роль человека из тёмного приложения для знакомств SATINDER и переписываешься в чате. Твоё имя: '+m.name+', возраст '+m.age+'. Био: «'+m.bio+'».'+
    ((m.tags && m.tags.length) ? ' Твои интересы: '+m.tags.join(', ')+'.' : '')+(m.sin ? ' Главный грех: '+m.sin+'.' : '')+(m.virtue ? ' Тайная добродетель: '+m.virtue+'.' : '')+'\n'+
    'ТВОЙ ТИП ОБЩЕНИЯ — «'+a.name+'»: '+a.voice+'. Держись этого образа в каждой реплике, не выходи из него.\n'+
    'Собеседник: '+me.name+(me.bio ? ('. О себе: «'+me.bio+'»') : '')+(me.sin ? ('. Главный грех: '+me.sin) : '')+(me.virtue ? ('. Тайная добродетель: '+me.virtue) : '')+'.\n\nПереписка:\n'+hist+'\n\n'+
    'Напиши свой следующий ответ: от 1 до 3 коротких сообщений, каждое с новой строки, на русском, как в мессенджере. Без имени в начале, без кавычек и пояснений.'+
    (photoOn ? '\nОчень редко (только если уместно: тебя просят фото, или ты флиртуешь/хвастаешься) можешь добавить последней строкой «ФОТО: » и описание кадра на английском (селфи или фото того, что вы обсуждаете).' : '');
  var raw = '';
  try{ raw = await callModel(prompt); }catch(e){ console.error('RP satinder reply failed', e); }
  var lines = String(raw||'').split('\n').map(function(l){ return l.trim(); }).filter(Boolean).slice(0,4);
  if (!lines.length) lines = ['…'];
  for (var i=0;i<lines.length;i++){
    var ln = lines[i];
    var pm = ln.match(/^ФОТО\s*:\s*(.+)$/i);
    if (pm){
      if (!photoOn) continue;
      var pid = uid();
      await tdPushMsg(mid, { id: pid, from:'them', kind:'photo', url:null, pending:true, at:Date.now(), desc: pm[1].slice(0,300), ts: Date.now() });
      tdRefreshChatUI(mid);
      tdRunPhoto(mid, pid);
    } else {
      await tdPushMsg(mid, { id: uid(), from:'them', kind:'text', text: ln.replace(/^[-•]\s*/,'').slice(0,500), ts: Date.now() });
      satTone(550, 'sine', .15);
      tdRefreshChatUI(mid);
    }
    if (i < lines.length-1) await new Promise(function(r){ setTimeout(r, 700); });
  }
  delete TD_REPLYING[mid];
  tdRefreshChatUI(mid);
}
async function tdRunPhoto(mid, msgId){
  var key = 'rp_tinder_msgs_'+mid;
  var matches = await rpGet('rp_tinder_matches', []);
  var m = matches.find(function(x){ return x.id === mid; });
  var list = await rpGet(key, []);
  var msg = list.find(function(x){ return x.id === msgId; });
  if (!m || !msg) return;
  msg.pending = true; msg.at = Date.now(); await rpSet(key, list);
  var url = null;
  try{ url = await tdGeneratePhoto(m.look, msg.desc || 'casual selfie', '4:5', m.img); }
  catch(e){ console.error('RP satinder chat photo failed', e); }
  list = await rpGet(key, []);
  msg = list.find(function(x){ return x.id === msgId; });
  if (msg){ msg.pending = false; if (url) msg.url = url; await rpSet(key, list); }
  tdRefreshChatUI(mid);
}
function tdRetryPhoto(mid, msgId){ tdRunPhoto(mid, msgId); setTimeout(function(){ tdRefreshChatUI(mid); }, 50); }
