async function hideEverythingGlobalInner(){
  var changed = false;
  await mutateMessages('main', function(l){
    for (var i=0;i<l.length-hk();i++){ if (!l[i].hidden){ l[i].hidden = true; changed = true; } }
  });
  var contacts = await rpGet('rp_contacts', []);
  for (var i=0;i<contacts.length;i++){
    await mutateMessages(contacts[i].id, function(l){
      for (var j=0;j<l.length-hk();j++){ if (!l[j].hidden){ l[j].hidden = true; changed = true; } }
    });
  }
  var npcContacts = await rpGet('rp_npc_contacts', []);
  for (var i=0;i<npcContacts.length;i++){
    await mutateMessages(npcContacts[i].id, function(l){
      for (var j=0;j<l.length-hk();j++){ if (!l[j].hidden){ l[j].hidden = true; changed = true; } }
    });
  }
  var notes = await rpGet('rp_notes', []);
  var nChanged = false;
  for (var i=0;i<notes.length-hk();i++){ if (!notes[i].hidden){ notes[i].hidden = true; nChanged = true; } }
  if (nChanged){ await rpSet('rp_notes', notes); changed = true; }
  var reminders = await rpGet('rp_reminders', []);
  var rChanged = false;
  for (var i=0;i<reminders.length-hk();i++){ if (!reminders[i].hidden){ reminders[i].hidden = true; rChanged = true; } }
  if (rChanged){ await rpSet('rp_reminders', reminders); changed = true; }
  var mems = await rpGet('rp_memories', []);
  var mChanged = false;
  for (var i=0;i<mems.length-hk();i++){ if (!mems[i].hidden){ mems[i].hidden = true; mChanged = true; } }
  if (mChanged){ await rpSet('rp_memories', mems); changed = true; }
  if (await hideDiaryLists()) changed = true;
  if (await hideTwitterList()) changed = true;
  if (await hideNpcsList()) changed = true;
  if (await hideDeliveryOrders()) changed = true;
  if (await hideBankLists()) changed = true;
  if (await hideMarketLists()) changed = true;
  if (await hideCalendarLists()) changed = true;
  if (await hideChannelsList()) changed = true;
  if (await hideHealthLists()) changed = true;
  if (await hideMapsList()) changed = true;
  if (await hideSmartHomeList()) changed = true;
  if (await hideRaveLog()) changed = true;
  if (await hidePetFeed()) changed = true;
  if (await hideTwitchOoc()) changed = true;
  if (await hideTinderAll()) changed = true;
  return changed;
}
