  if (await unhideCalendarLists()) changed = true;
  if (await unhideChannelsList()) changed = true;
  if (await unhideHealthLists()) changed = true;
  if (await unhideMapsList()) changed = true;
  if (await unhideSmartHomeList()) changed = true;
  if (await unhideRaveLog()) changed = true;
  if (await unhidePetFeed()) changed = true;
