      '<div class="th_lbl"><span>Ширина (ячеек)</span><div class="th_stepper"><div class="b" data-st="cols" data-d="-1">−</div><span>'+cols+'</span><div class="b" data-st="cols" data-d="1">+</div></div></div>'+
      '<div class="th_lbl"><span>Высота (рядов)</span><div class="th_stepper"><div class="b" data-st="rows" data-d="-1">−</div><span>'+rows+'</span><div class="b" data-st="rows" data-d="1">+</div></div></div>'+
      '<div class="th_row2" style="margin-top:14px;"><div class="th_btn ghost" id="wg_del">Удалить виджет</div><div class="th_btn" id="wg_ok">Готово</div></div>';
    if (!bg){ bg = thSheet(''); }
    var sheet = bg.querySelector('.th_sheet');
    scrollKeep = sheet.scrollTop;
    sheet.innerHTML = html;
    sheet.scrollTop = scrollKeep;
    var pv = $('#wg_prev', sheet); var pc = await wgBuild(w, l);
