function wgPresetPreview(pr){
  var colors = { notes:'var(--glass1)', love:'linear-gradient(135deg,var(--accent2),var(--accent))', pet:'var(--glass1)' };
  var cols = 5, rest = []; for (var i = 0; i < 20; i++) rest.push(0);
  var ents = pr.items.map(function(it, n){ return { idx: Math.min(rest.length, (it.row || 0) * cols), it:it, n:n }; }).sort(function(x, y){ return x.idx - y.idx || x.n - y.n; });
  var out = [], ptr = 0;
  if (pr.photo) out.push('<div style="grid-column:span 5;background:rgba(255,255,255,.2);border-radius:3px;height:9px;"></div>');
  var dot = '<div style="background:rgba(255,255,255,.18);border-radius:3px;height:9px;"></div>';
  ents.forEach(function(e){
    for (var k = ptr; k < e.idx; k++) out.push(dot);
    ptr = e.idx;
    var bg = e.it.over && e.it.over.mode === 'clear' ? 'rgba(255,255,255,.15)' : colors[e.it.type];
    out.push('<div style="grid-column:span '+e.it.cols+';grid-row:span '+e.it.rows+';background:'+bg+';border:1px solid rgba(255,255,255,.28);border-radius:3px;box-sizing:border-box;"></div>');
  });
  for (var k2 = ptr; k2 < rest.length; k2++) out.push(dot);
  return '<div style="display:grid;grid-template-columns:repeat(5,1fr);grid-auto-rows:9px;gap:2px;width:92px;flex:none;">'+out.join('')+'</div>';
}
async function wgApplyPreset(pr){
  var l = await hlGet(), cols = l.cols || 5;
  var list = pr.items.map(function(it){ return Object.assign({ id:'wg_'+uid(), type:it.type }, wgDefaults(it.type), { cols:it.cols, rows:it.rows }, it.over || {}); });
  await wgSaveList(list);
  var rest = (await rpGet('rp_home_order', [])).filter(function(x){ return !/^wg_/.test(x) && x !== 'widget'; });
  if (!rest.length) rest = (await hlOrder()).filter(function(x){ return !/^wg_/.test(x) && x !== 'widget'; });
  var ents = pr.items.map(function(it, n){ return { idx: Math.min(rest.length, (it.row || 0) * cols), id:list[n].id, n:n }; }).sort(function(x, y){ return x.idx - y.idx || x.n - y.n; });
  var ord = pr.photo ? ['widget'] : [], ptr = 0;
  ents.forEach(function(e){ ord = ord.concat(rest.slice(ptr, e.idx)); ptr = e.idx; ord.push(e.id); });
  ord = ord.concat(rest.slice(ptr));
  await rpSet('rp_home_order', ord);
  await hwSave({ photo: !!pr.photo });
  WG_IDX = {};
}
async function wgMove(id, dir){
  var l = await hlGet(), cols = l.cols || 5, ord = await hlOrder(), i = ord.indexOf(id); if (i < 0) return;
  ord.splice(i, 1); var j = Math.max(0, Math.min(ord.length, i + dir * cols)); ord.splice(j, 0, id);
  await rpSet('rp_home_order', ord);
}
var thWgSub = 'list';
async function thTabWgLayout(body, container){
  body.appendChild(el('div','th_hint','Готовые расположения: виджеты встают не только сверху, но и между рядами приложений. Приложения обтекают виджеты. Выбери расстановку — и подправь каждый виджет стрелками ниже. Тяни значки и виджеты на главном экране в режиме перестановки, чтобы настроить ещё точнее.'));
  WG_PRESETS.forEach(function(pr){
    var row = el('div','wg_add');
    row.innerHTML = wgPresetPreview(pr)+'<div class="t"><b>'+pr.name+'</b><span>'+pr.desc+'</span></div><div class="th_btn">Применить</div>';
    $('.th_btn', row).addEventListener('click', async function(){ await wgApplyPreset(pr); await buildGrid(); toast('Расстановка «'+pr.name+'» применена'); thRender(container); });
    body.appendChild(row);
  });
  var list = await wgList();
  body.appendChild(el('div','th_sec','Положение виджетов'));
  if (!list.length) body.appendChild(el('div','th_hint','Добавь виджеты на вкладке «Мои виджеты» или примени расстановку выше.'));
  var ord = await hlOrder(), lay = await hlGet();
  list.forEach(function(w){
    var T = WG_TYPES[w.type]; if (!T) return;
    var rowN = Math.floor(ord.filter(function(x, i){ return i < ord.indexOf(w.id) && !/^wg_|^widget$/.test(x); }).length / Math.max(1, lay.cols || 5));
    var row = el('div','wg_add');
    row.innerHTML = '<div class="e">'+T.emoji+'</div><div class="t"><b>'+T.name+'</b><span>после '+rowN+'-го ряда приложений</span></div><div class="th_btn ghost" data-m="-1" style="flex:0 0 38px;">▲</div><div class="th_btn ghost" data-m="1" style="flex:0 0 38px;">▼</div>';
    row.querySelectorAll('[data-m]').forEach(function(b){ b.addEventListener('click', async function(){ await wgMove(w.id, +b.getAttribute('data-m')); await buildGrid(); thRender(container); }); });
    body.appendChild(row);
  });
}
async function thTabWidgets(body, container){
  var segW = el('div','th_tabs'); segW.style.marginBottom = '10px';
  segW.innerHTML = '<div data-s="list" class="'+(thWgSub==='list'?'on':'')+'">Мои виджеты</div><div data-s="layout" class="'+(thWgSub==='layout'?'on':'')+'">Расположение</div>';
  segW.querySelectorAll('div').forEach(function(d){ d.addEventListener('click', function(){ thWgSub = d.getAttribute('data-s'); container.scrollTop = 0; thRender(container); }); });
  body.appendChild(segW);
  if (thWgSub === 'layout'){ await thTabWgLayout(body, container); return; }
  body.appendChild(el('div','th_hint','Добавь виджет на главный экран и настрой под себя: фон, картинку, цвета, шрифт и размер. Двигать и растягивать можно прямо на главном — зажми виджет, а ⚙ откроет эти же настройки.'));
  Object.keys(WG_TYPES).forEach(function(k){
    var T = WG_TYPES[k];
    var row = el('div','wg_add');
    row.innerHTML = '<div class="e">'+T.emoji+'</div><div class="t"><b>'+T.name+'</b><span>'+T.desc+'</span></div><div class="th_btn">Добавить</div>';
    $('.th_btn', row).addEventListener('click', async function(){ var w = await wgAdd(k); await buildGrid(); toast('Виджет добавлен на главный'); thRender(container); wgSheet(w.id); });
    body.appendChild(row);
  });
  var syncRow = el('div','wg_add'); syncRow.innerHTML = '<div class="e">🎨</div><div class="t"><b>Цвета — по теме</b><span>Сбросить цвета всех виджетов на палитру текущей темы</span></div><div class="th_btn">Сбросить</div>';
  $('.th_btn', syncRow).addEventListener('click', async function(){
    var l = await wgList();
    l.forEach(function(w){ var d = wgDefaults(w.type); w.mode = d.mode; w.c1 = d.c1; w.c2 = d.c2; w.tc = d.tc; w.ac = d.ac; });
    await wgSaveList(l); await buildGrid(); toast('Виджеты перекрашены по теме'); thRender(container);
  });
  body.appendChild(syncRow);
  var goLay = el('div','wg_add'); goLay.innerHTML = '<div class="e">🧩</div><div class="t"><b>Расположение виджетов</b><span>Сверху, между приложениями, внизу — готовые варианты</span></div><div class="th_btn">Открыть</div>';
  $('.th_btn', goLay).addEventListener('click', function(){ thWgSub = 'layout'; container.scrollTop = 0; thRender(container); });
  body.appendChild(goLay);
  var list = await wgList();
  body.appendChild(el('div','th_sec','На главном экране'));
  if (!list.length) body.appendChild(el('div','th_hint','Пока ничего не добавлено.'));
  list.forEach(function(w){
    var T = WG_TYPES[w.type]; if (!T) return;
    var row = el('div','wg_add');
    row.innerHTML = '<div class="e">'+T.emoji+'</div><div class="t"><b>'+T.name+'</b><span>'+(w.cols||2)+'×'+(w.rows||2)+' ячеек</span></div><div class="th_btn">Настроить</div><div class="th_btn ghost" data-del="1" style="padding:7px 11px;">×</div>';
    $('.th_btn', row).addEventListener('click', function(){ wgSheet(w.id); });
    $('[data-del]', row).addEventListener('click', async function(){ await wgRemove(w.id); await buildGrid(); thRender(container); });
    body.appendChild(row);
  });
}

var CAS = { view:'lobby', bet:0, busy:false, sess:{ txId:null, net:0, rounds:0 }, bj:null, mines:null, root:null };
var CAS_GAMES = [
  { id:'slots', name:'Золотой дракон', tag:'Три барабана, три шанса', em:'🎰', c1:'#8a1030', c2:'#3a0716', rtp:'92%' },
  { id:'wheel', name:'Колесо фортуны', tag:'Крутани — и до x5', em:'🎡', c1:'#12507a', c2:'#08202f', rtp:'96%' },
  { id:'bj',    name:'Блэкджек', tag:'Набери 21, обыграй дилера', em:'🃏', c1:'#14674a', c2:'#08301f', rtp:'99%', wide:true },
  { id:'mines', name:'Сокровища бездны', tag:'Открывай ячейки, не наступи на мину', em:'💎', c1:'#5a2a8a', c2:'#210c3a', rtp:'96%' },
  { id:'dice',  name:'Кости', tag:'Сам выбираешь шанс', em:'🎲', c1:'#8a5a12', c2:'#35210a', rtp:'96%' }
];
function casRoundMoney(v){ return rpLocIsRu() ? Math.round(v) : Math.round(v*100)/100; }
function casNice(x){ if (x < 1) return 1; var p = Math.pow(10, Math.floor(Math.log(x)/Math.LN10)); var m = x/p; return (m < 1.5 ? 1 : (m < 3.5 ? 2 : (m < 7.5 ? 5 : 10))) * p; }
function casChips(bal){ var out = []; [0.002, 0.01, 0.04, 0.15].forEach(function(b){ var v = casNice(Math.max(1, bal*b)); if (out.indexOf(v) === -1) out.push(v); }); return out; }
function casAlive(){ return CAS.root && CAS.root.isConnected && currentScreen === 'casino'; }
async function casRefreshBal(){
  if (!casAlive()) return;
  var b = $('#cas_bal_v', CAS.root), s = $('#cas_sess', CAS.root);
  if (b) b.textContent = fmtMoney(await getBankBalance());
  if (s){ var n = CAS.sess.net; s.innerHTML = '<span>Сессия: '+CAS.sess.rounds+' '+wgPl(CAS.sess.rounds, ['раунд','раунда','раундов'])+'</span><b class="'+(n>0?'up':(n<0?'dn':''))+'">'+(n>0?'+':'')+fmtMoney(n)+'</b>'; }
}
async function casAdd(delta){
  delta = casRoundMoney(delta);
  var bal = await getBankBalance(); await setBankBalance(bal + delta);
  CAS.sess.net = casRoundMoney(CAS.sess.net + delta);
  var list = await rpGet('rp_bank_tx', []);
  var tx = CAS.sess.txId ? list.filter(function(t){ return t.id === CAS.sess.txId; })[0] : null;
  if (!tx){
    tx = { id:uid(), hidden:false, ts:Date.now(), type:'out', amount:0, counterparty:'Казино', note:'', dateLabel: await getStoryDate(), source:'casino' };
    CAS.sess.txId = tx.id; list.push(tx);
  }
  tx.amount = CAS.sess.net; tx.type = tx.amount >= 0 ? 'in' : 'out';
  tx.note = (CAS.sess.rounds || 1)+' '+wgPl(CAS.sess.rounds || 1, ['раунд','раунда','раундов']);
  await rpSet('rp_bank_tx', list.slice(-300));
  casRefreshBal();
}
async function casStake(v){
  var bal = await getBankBalance();
  if (!(v > 0)){ toast('Поставь сумму'); return false; }
  if (v > bal){ toast('На счёте не хватает денег — пополни в Банке'); return false; }
  await casAdd(-v); return true;
}
async function casRecord(stake, payout){
  CAS.sess.rounds++;
  try{
    var st = await rpGet('rp_casino_stats', { rounds:0, wagered:0, returned:0, best:0 });
    st.rounds++; st.wagered = casRoundMoney(st.wagered + stake); st.returned = casRoundMoney(st.returned + payout); st.best = Math.max(st.best, payout - stake);
    await rpSet('rp_casino_stats', st);
  }catch(e){}
}
async function casPay(stake, payout){
  if (payout > 0) await casAdd(payout);
  await casRecord(stake, payout);
  casRefreshBal();
}
function casSetMsg(t, cls){ var m = $('#cas_msg', CAS.root); if (m){ m.textContent = t; m.className = 'cas_msg'+(cls ? ' '+cls : ''); } }
function casBetValue(){ var i = $('#cas_bet_in', CAS.root); var v = i ? Number(i.value) : CAS.bet; v = casRoundMoney(Math.max(0, v||0)); CAS.bet = v; return v; }
async function casBetBox(host, locked){
  var bal = await getBankBalance();
  var chips = casChips(bal);
  if (!CAS.bet || CAS.bet > bal) CAS.bet = Math.min(chips[1] || chips[0], Math.max(0, casRoundMoney(bal)));
  var box = el('div','cas_bet'+(locked ? ' off' : '')); box.id = 'cas_betbox';
  box.innerHTML = '<div class="cas_bet_row"><button data-a="half">½</button><input id="cas_bet_in" type="number" min="0" value="'+CAS.bet+'"><button data-a="dbl">×2</button><button data-a="max">MAX</button></div>'+
    '<div class="cas_chips">'+chips.map(function(c){ return '<div class="cas_chip" data-v="'+c+'">'+fmtMoney(c)+'</div>'; }).join('')+'</div>';
  host.appendChild(box);
  var inp = $('#cas_bet_in', box);
  var setV = async function(v){ var b = await getBankBalance(); v = casRoundMoney(Math.max(0, Math.min(v, b))); CAS.bet = v; inp.value = v; if (CAS.onBet) CAS.onBet(); };
  box.querySelectorAll('[data-a]').forEach(function(b){ b.addEventListener('click', function(){ var a = b.getAttribute('data-a'); setV(a==='half' ? casBetValue()/2 : (a==='dbl' ? casBetValue()*2 : 1e15)); }); });
  box.querySelectorAll('.cas_chip').forEach(function(c){ c.addEventListener('click', function(){ setV(+c.getAttribute('data-v')); }); });
  inp.addEventListener('change', function(){ setV(Number(inp.value)||0); });
  return box;
}
function casModal(html){
  var bg = el('div','cas_modal_bg'); bg.innerHTML = '<div class="cas_modal">'+html+'<div class="cas_go" style="margin-top:12px;text-align:center;">Понятно</div></div>';
  CAS.root.appendChild(bg);
  bg.addEventListener('click', function(e){ if (e.target === bg || e.target.classList.contains('cas_go')) bg.remove(); });
}
