    $('#cbj_p', main).innerHTML = b.p.map(function(c){ return casCardHtml(c); }).join('');
    $('#cbj_d', main).innerHTML = b.d.map(function(c, i){ return casCardHtml(c, b.active && i === 1); }).join('');
    $('#cbj_ps', main).textContent = casScore(b.p);
