    var ps = casScore(b.p), ds = casScore(b.d), mult = 0, msg = '', cls = 'lose';
    if (kind === 'bust'){ msg = 'Перебор — ставка сгорела'; }
    else if (kind === 'bj'){ mult = 2.5; msg = 'Блэкджек! Выигрыш '; cls = 'win'; }
    else if (kind === 'pushbj'){ mult = 1; msg = 'У обоих блэкджек — ничья'; cls = ''; }
    else if (ds > 21 || ps > ds){ mult = 2; msg = 'Победа! Дилер: '+ds+'. Выигрыш '; cls = 'win'; }
    else if (ps === ds){ mult = 1; msg = 'Ничья — ставка вернулась'; cls = ''; }
