  page.innerHTML = '<div class="stk_h1">Огоньки 🔥</div><div class="stk_sub">Пиши каждый день по сюжетной дате — и огонёк растёт.</div>'+
    '<div class="stk_fl_head"><div class="stk_flame'+(flame?' cold':'')+'">🔥</div><div><div class="stk_fl_n">'+info.n+' '+wgPl(info.n, ['день','дня','дней'])+'</div><div style="font-size:11px;color:#c9a07a;">'+(info.state==='active' ? 'Сегодня уже горит' : (info.state==='dying' ? 'Погаснет, если не написать сегодня!' : (info.state==='cold' ? 'Огонёк потух — напиши, чтобы зажечь заново' : 'Напиши первое сообщение, чтобы зажечь')))+'</div><div style="font-size:10px;color:#8a7358;margin-top:3px;">Рекорд: '+(info.best||0)+'</div></div></div>'+
    '<div class="stk_sub" style="margin:0 0 8px;font-weight:800;">Личные диалоги</div><div id="stk_row"></div>';
  var row = el('div','stk_chatrow');
  row.innerHTML = (await stkAvHtml({ name:names.charName, user:names.charName, img:(ref && ref.avatar)||'' }, ''))+'<div class="tx"><b>'+escapeHtml(names.charName)+' <span class="stk_pill'+(info.state==='dying'?' warn':(flame?' cold':''))+'">🔥 '+info.n+'</span></b><p>'+escapeHtml(last ? (last.post ? '🎬 Видео' : last.t) : 'Начни диалог')+'</p></div>';
  $('#stk_row', page).appendChild(row);
  row.addEventListener('click', function(){ stkChatOpen = true; stkRender(container); });
