async function pbCollect(){
  var out = [], seen = {}, names = await getNames(), over = await rpGet('rp_pb_over', {});
  var push = function(c){
    var k = String(c.name||'').trim().toLowerCase(); if (!k) return;
    if (seen[k]){ var ex = seen[k]; var oo = over[c.key] || {}; if (!ex.img && (oo.photo || c.img)) ex.img = oo.photo || c.img; if (!ex.about && c.about) ex.about = c.about; return; }
    seen[k] = c;
    var o = over[c.key] || {};
    c.phone = o.phone || c.phone || pbPhone(c.name); c.note = o.note || ''; c.fav = !!o.fav; c.hidden = !!o.hidden; if (o.photo) c.img = o.photo;
    out.push(c);
  };
  (await rpGet('rp_pb_contacts', [])).forEach(function(m){ push({ key:'m:'+m.id, id:m.id, src:'me', name:m.name, phone:m.phone, about:m.about, relation:m.relation, img:m.photo||'', manual:true }); });
  var ref = null; try{ ref = await getAutoCharRef(); }catch(e){}
  if (names.charName) push({ key:'char', src:'char', name:names.charName, about:'Главный персонаж', img:(ref && ref.avatar) || names.charAvatar || '' });
  (await rpGet('rp_npcs2', [])).forEach(function(n){ push({ key:'npc:'+n.id, src:'npc', name:n.name, about:n.about, relation:n.relation, img:n.photo||'' }); });
  (await rpGet('rp_npc_contacts', [])).forEach(function(c){ push({ key:'nc:'+c.id, src:'nc', name:c.name, about:c.desc||'', relation:'', img:c.avatarPath||c.photo||'' }); });
  (await rpGet('rp_contacts', [])).forEach(function(c){ push({ key:'ct:'+c.id, src:'ct', name:c.name, about:c.about||c.desc||'', relation:c.relation||'', img:c.avatarPath||c.photo||'' }); });
  (await rpGet('rp_tinder_matches', [])).forEach(function(m){ push({ key:'tn:'+m.id, src:'tn', name:m.name, about:m.bio, relation:'Мэтч в Tinder'+(m.age ? ', '+m.age : ''), img:m.img||'' }); });
  return out;
}
SCREENS.phonebook = {
  title: 'Телефонная книга',
  async render(container){
    container.style.padding = '0'; container.style.display = 'flex'; container.style.flexDirection = 'column'; container.style.height = '100%'; container.style.minHeight = '0';
    PB_Q = ''; PB_SHOW_HIDDEN = false;
    $('#rp_appbar_menu_btn').style.display = 'flex';
    var menu = buildAppbarMenu(); menu.innerHTML = ''; menu.appendChild(buildOocButton('ooc-phonebook', gatherOocPhonebook));
    var pbScan = el('div','rp_btn rp_ghost rp_xs','<svg><use href="#rpi-search"/></svg><span>Разобрать сюжет</span>'); pbScan.addEventListener('click', function(){ closeAppbarMenu(); msgScanSheet(null, function(){ pbRender(container); }); }); menu.appendChild(pbScan);
    await pbRender(container);
  }
};
async function pbRender(container){
  if (!container || !container.isConnected || currentScreen !== 'phonebook') return;
  var names0 = await getNames(); var all = await pbCollect(), hiddenN = all.filter(function(c){ return c.hidden; }).length;
  var list = all.filter(function(c){ return PB_SHOW_HIDDEN ? c.hidden : !c.hidden; });
  var q = PB_Q.trim().toLowerCase();
  if (q) list = list.filter(function(c){ return (c.name+' '+c.phone+' '+(c.about||'')).toLowerCase().indexOf(q) >= 0; });
  list.sort(function(a, b){ return a.name.localeCompare(b.name, 'ru'); });
  container.innerHTML = '';
  var app = el('div','pb_app'); container.appendChild(app); PB_ROOT = app;
  var head = el('div','pb_head');
  head.innerHTML = '<div class="pb_title"><div><b>'+(PB_SHOW_HIDDEN ? 'Скрытые' : 'Контакты')+'</b> <span>'+list.length+'</span></div><div class="pb_add" id="pb_add">'+pbIco('rpi-plus')+'</div></div><input class="pb_search" id="pb_q" placeholder="Поиск по имени или номеру" value="'+escapeHtml(PB_Q)+'">';
  app.appendChild(head);
  var body = el('div','pb_list'); app.appendChild(body);
  var mp = await rpGet('rp_my_profile', null) || {}; var myName = mp.name || names0.userName || 'Я'; var myPhone = mp.phone || pbPhone(myName);
  var favs = PB_SHOW_HIDDEN ? [] : list.filter(function(c){ return c.fav; });
  var rest = PB_SHOW_HIDDEN ? list : list.filter(function(c){ return !c.fav; });
  var rowHtml = function(c){ var t = PB_SRC[c.src]; return '<div class="pb_row" data-k="'+escapeHtml(c.key)+'">'+pbAv(c)+'<div class="tx"><b>'+escapeHtml(c.name)+'</b><span>'+escapeHtml(c.phone)+'</span></div><div class="pb_tag '+t[1]+'">'+t[0]+'</div></div>'; };
  var html = '';
  if (!PB_SHOW_HIDDEN && !q) html += '<div class="pb_row" id="pb_me">'+pbAv({ name:myName, img:mp.avatar||'' })+'<div class="tx"><b>'+escapeHtml(myName)+' <span>(я)</span></b><span>'+escapeHtml(myPhone)+'</span></div><div class="pb_tag me">Мой профиль</div></div>';
  if (favs.length) html += '<div class="pb_letter">★ Избранные</div>'+favs.map(rowHtml).join('');
  var cur = '';
  rest.forEach(function(c){ var L = c.name.charAt(0).toUpperCase(); if (L !== cur){ cur = L; html += '<div class="pb_letter">'+escapeHtml(L)+'</div>'; } html += rowHtml(c); });
  if (!list.length) html = '<div class="pb_empty">'+(q ? 'Ничего не нашлось' : (PB_SHOW_HIDDEN ? 'Скрытых контактов нет' : 'Пока пусто. Нажми «+», чтобы добавить контакт — НПС и мэтчи из Tinder появятся здесь сами.'))+'</div>';
  if (hiddenN || PB_SHOW_HIDDEN) html += '<div class="pb_empty" style="padding:14px;"><span id="pb_hid" style="color:#7db6fb;cursor:pointer;">'+(PB_SHOW_HIDDEN ? '← Назад к контактам' : 'Скрытые контакты ('+hiddenN+')')+'</span></div>';
  body.innerHTML = html;
  var byKey = {}; all.forEach(function(c){ byKey[c.key] = c; });
  body.querySelectorAll('.pb_row').forEach(function(r){ r.addEventListener('click', function(){ pbCard(byKey[r.getAttribute('data-k')], container); }); });
  var meRow = $('#pb_me', body); if (meRow) meRow.addEventListener('click', function(){ openScreen('myprofile'); });
  var hb = $('#pb_hid', body); if (hb) hb.addEventListener('click', function(){ PB_SHOW_HIDDEN = !PB_SHOW_HIDDEN; pbRender(container); });
  $('#pb_add', head).addEventListener('click', function(){ pbForm(null, container); });
  var qi = $('#pb_q', head);
  qi.addEventListener('input', function(){ PB_Q = qi.value; clearTimeout(qi.__t); qi.__t = setTimeout(function(){ pbRender(container).then(function(){ var n = $('#pb_q'); if (n){ n.focus(); try{ n.setSelectionRange(n.value.length, n.value.length); }catch(e){} } }); }, 220); });
}

async function pbApplyPhoto(c, src){
  await pbSetOver(c.key, { photo: src });
  var lc = String(c.name||'').trim().toLowerCase();
  var upd = async function(key, field){
    var l = await rpGet(key, []), ch = false;
    l.forEach(function(x){ if (String(x.name||'').trim().toLowerCase() === lc){ x[field] = src; ch = true; } });
    if (ch) await rpSet(key, l);
  };
  await upd('rp_npcs2', 'photo'); await upd('rp_npc_contacts', 'avatarPath'); await upd('rp_contacts', 'avatarPath'); await upd('rp_pb_contacts', 'photo');
}
function pbIco(id){ return '<svg><use href="#'+id+'"/></svg>'; }
function pbSheet(html){
  var bg = el('div','pb_sheet_bg'); bg.innerHTML = '<div class="pb_sheet">'+html+'</div>'; PB_ROOT.appendChild(bg);
  bg.addEventListener('click', function(e){ if (e.target === bg) bg.remove(); });
  return bg;
}
async function pbSetOver(key, patch){ var o = await rpGet('rp_pb_over', {}); o[key] = Object.assign(o[key] || {}, patch); await rpSet('rp_pb_over', o); }
function pbCard(c, container){
  if (!c) return;
  var t = PB_SRC[c.src];
  var bg = pbSheet('<div class="pb_card">'+pbAv(c,'big')+'<b>'+escapeHtml(c.name)+'</b><div class="ph">'+escapeHtml(c.phone)+'</div><div class="pb_tag '+t[1]+'" style="margin-top:4px;">'+t[0]+'</div></div>'+
    (c.relation ? '<div class="pb_fld"><label>Кто это</label><div style="font-size:13px;">'+escapeHtml(c.relation)+'</div></div>' : '')+
    (c.about ? '<div class="pb_fld"><label>О нём/ней</label><div style="font-size:12.5px;line-height:1.4;color:#c8d0d8;">'+escapeHtml(String(c.about).slice(0,400))+'</div></div>' : '')+
    '<div class="pb_fld"><label>Заметка</label><textarea id="pb_note" rows="2" maxlength="200" placeholder="Например: не брать трубку после 23:00">'+escapeHtml(c.note||'')+'</textarea></div>'+
    '<div class="pb_fld"><label>Номер</label><input id="pb_ph" maxlength="24" value="'+escapeHtml(c.phone)+'"></div>'+
    '<div class="pb_btns"><div class="pb_btn ghost" id="pb_photo">📷 Фото</div><div class="pb_btn ghost" id="pb_fav">'+(c.fav ? '★ Убрать из избранного' : '☆ В избранное')+'</div><div class="pb_btn ghost" id="pb_copy">Скопировать номер</div></div>'+
    '<div class="pb_btns"><div class="pb_btn" id="pb_save">Сохранить</div>'+(c.manual ? '<div class="pb_btn ghost" id="pb_edit">Изменить</div><div class="pb_btn red" id="pb_del">Удалить</div>' : '<div class="pb_btn red" id="pb_hide">'+(c.hidden ? 'Вернуть в книгу' : 'Скрыть')+'</div>')+'</div>');
  var key = c.key, done = function(){ bg.remove(); pbRender(container); };
  $('#pb_save', bg).addEventListener('click', async function(){
    var ph = $('#pb_ph', bg).value.trim(), nt = $('#pb_note', bg).value.trim();
    if (c.manual){ var l = await rpGet('rp_pb_contacts', []); var it = l.filter(function(x){ return x.id === c.id; })[0]; if (it){ it.phone = ph || it.phone; await rpSet('rp_pb_contacts', l); } await pbSetOver(key, { note:nt }); }
    else await pbSetOver(key, { phone: ph && ph !== pbPhone(c.name) ? ph : '', note:nt });
    toast('Сохранено'); done();
  });
  $('#pb_fav', bg).addEventListener('click', async function(){ await pbSetOver(key, { fav: !c.fav }); done(); });
  var phBtn = $('#pb_photo', bg), setPh = async function(src){ await pbApplyPhoto(c, src); toast('Фото сохранено'); done(); };
  if (rpNativeOk()) phBtn.addEventListener('click', async function(){ try{ var r = await rpImport({ multiple:false }); if (r && r[0] && r[0].path) await setPh(String(r[0].path)); }catch(err){ toast('Не удалось выбрать фото: '+(err && err.message ? err.message : err)); } });
  else rpOverlayInput(phBtn, false, function(f){ var rd = new FileReader(); rd.onload = async function(){ var sh = await galKeep(String(rd.result), 320, 0.85); if (sh) await setPh(sh.data); }; rd.readAsDataURL(f[0]); });
  $('#pb_copy', bg).addEventListener('click', function(){ try{ navigator.clipboard.writeText(c.phone); }catch(e){} toast('Номер скопирован'); });
  var hd = $('#pb_hide', bg); if (hd) hd.addEventListener('click', async function(){ await pbSetOver(key, { hidden: !c.hidden }); done(); });
  var ed = $('#pb_edit', bg); if (ed) ed.addEventListener('click', function(){ bg.remove(); pbForm(c, container); });
  var dl = $('#pb_del', bg); if (dl) dl.addEventListener('click', async function(){ var l = (await rpGet('rp_pb_contacts', [])).filter(function(x){ return x.id !== c.id; }); await rpSet('rp_pb_contacts', l); toast('Контакт удалён'); done(); });
}
function pbForm(c, container){
  var cur = { photo: c ? (c.img||'') : '' };
  var bg = pbSheet('<div style="font-weight:900;font-size:16px;margin-bottom:10px;">'+(c ? 'Изменить контакт' : 'Новый контакт')+'</div>'+
    '<div class="pb_fld"><label>Имя</label><input id="pbf_name" maxlength="40" value="'+escapeHtml(c ? c.name : '')+'"></div>'+
    '<div class="pb_fld"><label>Номер (пусто — подберу сам)</label><input id="pbf_ph" maxlength="24" value="'+escapeHtml(c ? c.phone : '')+'"></div>'+
    '<div class="pb_fld"><label>Кто это</label><input id="pbf_rel" maxlength="60" placeholder="Друг, коллега, бывший…" value="'+escapeHtml(c ? (c.relation||'') : '')+'"></div>'+
    '<div class="pb_fld"><label>О нём/ней</label><textarea id="pbf_about" rows="3" maxlength="300">'+escapeHtml(c ? (c.about||'') : '')+'</textarea></div>'+
    '<div class="pb_btns"><div class="pb_btn ghost" id="pbf_photo">Фото</div></div><div class="pb_btns"><div class="pb_btn" id="pbf_ok">Сохранить</div></div>');
  var pickBtn = $('#pbf_photo', bg), native = false; try{ native = rpNativeOk(); }catch(e){}
  if (native) pickBtn.addEventListener('click', async function(){ try{ var r = await rpImport({ multiple:false }); if (r && r[0] && r[0].path){ cur.photo = String(r[0].path); toast('Фото выбрано'); } }catch(e){ toast('Не удалось выбрать фото'); } });
  else rpOverlayInput(pickBtn, false, function(f){ var rd = new FileReader(); rd.onload = async function(){ var sh = await galKeep(String(rd.result), 240, 0.85); if (sh){ cur.photo = sh.data; toast('Фото выбрано'); } }; rd.readAsDataURL(f[0]); });
  $('#pbf_ok', bg).addEventListener('click', async function(){
    var name = $('#pbf_name', bg).value.trim(); if (!name){ toast('Введи имя'); return; }
    var l = await rpGet('rp_pb_contacts', []);
    var data = { name:name, phone:$('#pbf_ph', bg).value.trim() || pbPhone(name), relation:$('#pbf_rel', bg).value.trim(), about:$('#pbf_about', bg).value.trim(), photo:cur.photo };
    if (c){ var it = l.filter(function(x){ return x.id === c.id; })[0]; if (it) Object.assign(it, data); } else l.push(Object.assign({ id:uid(), ts:Date.now() }, data));
    await rpSet('rp_pb_contacts', l); bg.remove(); toast(c ? 'Контакт обновлён' : 'Контакт добавлен'); pbRender(container);
  });
}
async function gatherOocPhonebook(){
  var parts = [], man = await rpGet('rp_pb_contacts', []), names = await getNames();
  if (man.length) parts.push('В телефонной книге '+names.userName+' добавлены контакты: '+man.slice(-8).map(function(m){ return m.name+' ('+m.phone+')'+(m.relation ? ' — '+m.relation : '')+(m.about ? ': '+String(m.about).slice(0,80) : ''); }).join('; ')+'.');
  var all = await pbCollect(), fav = all.filter(function(c){ return c.fav; });
  if (fav.length) parts.push('Избранные контакты: '+fav.slice(0,6).map(function(c){ return c.name; }).join(', ')+'.');
  return parts;
}


async function mpGet(){ return Object.assign({ name:'', user:'', bio:'', phone:'', birthday:'', city:'', job:'', status:'', look:'', avatar:'', extra:[] }, await rpGet('rp_my_profile', {})); }
async function mpApplyAvatar(){
  var a = $('#rp_home_avatar'); if (!a) return;
  var pr = null; try{ pr = await rpGet('rp_my_profile', null); }catch(e){}
  if (pr && pr.avatar){ a.style.backgroundImage = 'url("'+String(pr.avatar).replace(/"/g,'%22')+'")'; a.classList.add('has_photo'); }
  else { a.style.backgroundImage = ''; a.classList.remove('has_photo'); }
}
SCREENS.myprofile = {
  title: 'Мой профиль',
  async render(container){
    container.style.flexDirection = ''; container.style.height = ''; container.style.minHeight = ''; container.style.padding = '12px 14px 20px';
    var names = await getNames(), ref = null; try{ ref = await getAutoUserRef(); }catch(e){}
    var pr = await mpGet();
    var oldShared = null;
    if (!pr.name && !pr.avatar){ try{ oldShared = await PM.store.get('rp_my_profile', 'global'); }catch(e){ oldShared = null; } if (!oldShared || !(oldShared.name || oldShared.avatar)) oldShared = null; }
    if (!pr.name) pr.name = names.userName || '';
    if (!pr.user && pr.name) pr.user = '@'+String(pr.name).toLowerCase().replace(/[^a-zа-яё0-9_]/gi,'_').slice(0,18);
    var cur = JSON.parse(JSON.stringify(pr));
    container.innerHTML = '';
    var w = el('div','mp_wrap'); container.appendChild(w);
    if (oldShared){
      var imp = el('div','rp_card'); imp.style.marginBottom = '10px';
      imp.innerHTML = '<div class="rp_muted" style="font-size:11px;line-height:1.45;margin-bottom:8px;">Теперь у каждого чата свой профиль. Раньше был один общий: «'+escapeHtml(oldShared.name || 'без имени')+'». Взять его в этот чат?</div><div class="rp_btn rp_sm" id="mp_take_old"><span>Взять старый профиль</span></div>';
      container.insertBefore(imp, w);
      $('#mp_take_old', imp).addEventListener('click', async function(){ await rpSet('rp_my_profile', oldShared); await mpApplyAvatar(); toast('Профиль перенесён в этот чат'); openScreen('myprofile'); });
    }
    var fld = function(id, label, ph, val, area){ return '<div class="mp_fld"><label>'+label+'</label>'+(area ? '<textarea id="'+id+'" rows="3" maxlength="300" placeholder="'+ph+'">'+escapeHtml(val||'')+'</textarea>' : '<input id="'+id+'" maxlength="60" placeholder="'+ph+'" value="'+escapeHtml(val||'')+'">')+'</div>'; };
    var paint = function(){
      var av = cur.avatar ? 'background-image:url("'+String(cur.avatar).replace(/"/g,'%22')+'");' : '';
      $('#mp_av', w).setAttribute('style', av); $('#mp_av', w).textContent = cur.avatar ? '' : String(cur.name||'?').charAt(0).toUpperCase();
    };
    w.innerHTML = '<div class="mp_top"><div class="mp_av" id="mp_av"></div><span>Нажми на фото, чтобы выбрать</span><div style="display:flex;gap:6px;margin-top:4px;"><div class="rp_btn rp_ghost rp_xs" id="mp_pass"><span>Из паспорта героя</span></div><div class="rp_btn rp_ghost rp_xs" id="mp_noav"><span>Убрать фото</span></div></div></div>'+
      fld('mp_name','Имя','Как тебя зовут',cur.name)+fld('mp_user','Юзернейм','@nick',cur.user)+
      '<div class="mp_fld"><label>Номер телефона</label><input id="mp_phone" maxlength="24" placeholder="Пусто — подберу сам" value="'+escapeHtml(cur.phone||'')+'"></div>'+
      fld('mp_bio','О себе','Пара слов о тебе',cur.bio,true)+
      '<div class="mp_grid2">'+fld('mp_bd','День рождения','12 мая',cur.birthday)+fld('mp_city','Город','Где живёшь',cur.city)+fld('mp_job','Занятие','Работа или учёба',cur.job)+fld('mp_status','Статус','В отношениях, свободна…',cur.status)+'</div>'+
      fld('mp_look','Внешность (для фото)','Волосы, глаза, стиль — подставится в генерацию картинок',cur.look,true)+
      '<div class="mp_fld"><label>Свои поля</label><div id="mp_extra"></div><div class="rp_btn rp_ghost rp_xs" id="mp_add"><span>+ Добавить поле</span></div></div>'+
      '<div class="rp_btn" id="mp_save" style="margin-top:6px;"><span>Сохранить профиль</span></div>';
    var extraWrap = $('#mp_extra', w);
    var paintExtra = function(){
      extraWrap.innerHTML = '';
      (cur.extra||[]).forEach(function(f, i){
        var r = el('div','mp_extra'); r.innerHTML = '<input class="rp_input" placeholder="Название" maxlength="24" value="'+escapeHtml(f.k||'')+'" style="flex:.8;"><input class="rp_input" placeholder="Значение" maxlength="80" value="'+escapeHtml(f.v||'')+'" style="flex:1.2;"><div class="mp_x">×</div>';
        var ins = r.querySelectorAll('input'); ins[0].addEventListener('input', function(){ f.k = ins[0].value; }); ins[1].addEventListener('input', function(){ f.v = ins[1].value; });
        $('.mp_x', r).addEventListener('click', function(){ cur.extra.splice(i, 1); paintExtra(); });
        extraWrap.appendChild(r);
      });
    };
    paint(); paintExtra();
    $('#mp_add', w).addEventListener('click', function(){ cur.extra = cur.extra || []; cur.extra.push({ k:'', v:'' }); paintExtra(); });
    $('#mp_noav', w).addEventListener('click', function(){ cur.avatar = ''; paint(); });
    $('#mp_pass', w).addEventListener('click', function(){ if (ref && ref.avatar){ cur.avatar = ref.avatar; paint(); toast('Фото взято из паспорта'); } else toast('В паспорте нет фото'); });
    var native = false; try{ native = rpNativeOk(); }catch(e){}
    var av = $('#mp_av', w);
    if (native) av.addEventListener('click', async function(){ try{ var r = await rpImport({ multiple:false }); if (r && r[0] && r[0].path){ cur.avatar = String(r[0].path); paint(); } }catch(e){ toast('Не удалось выбрать фото: '+(e && e.message ? e.message : e)); } });
    else rpOverlayInput(av, false, function(f){ var rd = new FileReader(); rd.onload = async function(){ var sh = await galKeep(String(rd.result), 360, 0.85); if (sh){ cur.avatar = sh.data; paint(); } }; rd.readAsDataURL(f[0]); });
    $('#mp_save', w).addEventListener('click', async function(){
      var v = function(id){ return $('#'+id, w).value.trim(); };
      cur.name = v('mp_name'); var u = v('mp_user').replace(/\s+/g,'_'); cur.user = u ? (u.charAt(0)==='@' ? u : '@'+u) : '';
      cur.phone = v('mp_phone'); cur.bio = v('mp_bio'); cur.birthday = v('mp_bd'); cur.city = v('mp_city'); cur.job = v('mp_job'); cur.status = v('mp_status'); cur.look = v('mp_look');
      cur.extra = (cur.extra||[]).filter(function(f){ return (f.k||'').trim() && (f.v||'').trim(); });
      await rpSet('rp_my_profile', cur); await mpApplyAvatar(); toast('Профиль сохранён');
    });
  }
};
async function gatherOocProfile(){
  var pr = await rpGet('rp_my_profile', null); if (!pr) return [];
  var names = await getNames(), bits = [];
  if (pr.user) bits.push('юзернейм '+pr.user); if (pr.phone) bits.push('телефон '+pr.phone); if (pr.birthday) bits.push('день рождения '+pr.birthday); if (pr.city) bits.push('город '+pr.city); if (pr.job) bits.push('занятие: '+pr.job); if (pr.status) bits.push('статус: '+pr.status); if (pr.bio) bits.push('о себе: '+pr.bio);
  (pr.extra||[]).forEach(function(f){ bits.push(f.k+': '+f.v); });
  return bits.length ? ['Профиль '+(pr.name || names.userName)+' на телефоне: '+bits.join('; ')+'.'] : [];
}
async function msgScanStory(depth, onDone){
  var names = await getNames();
  var count = 0; try{ count = await PM.chat.count(); }catch(e){}
  if (!count){ toast('В чате пока нет сообщений'); return; }
  var end = count - 1, start = Math.max(0, end - depth + 1), msgs = [];
  try{ msgs = await PM.chat.slice([start, end]); }catch(e){}
  var text = (Array.isArray(msgs) ? msgs : []).map(function(m){
    var c = stripBrailleNoise(String(m.content||'')).replace(/<[^>]+>/g,' ').replace(/[ \t]+/g,' ').trim();
    return (m.role==='user' ? '['+names.userName+' — реплика игрока]' : '[рассказчик/'+names.charName+']')+' '+c;
  }).filter(function(l){ return l.length > 12; }).join('\n\n').slice(-14000);
  if (!text){ toast('Нечего разбирать'); return; }
  toast('Ищу сообщения в сюжете…');
  var raw = '';
  try{
    raw = await callModel('Ниже фрагмент ролевой истории. Найди ВСЕ места, где персонажи переписываются по телефону: смс, мессенджер, чат, голосовые, личные сообщения — в кавычках, курсивом, после слов «написал(а)», «пришло сообщение», «ответил(а) в чате» и т.п. Учитывай даже те, что не оформлены тегами.\n'+
      'Выведи по одной строке на сообщение, СТРОГО в формате:\nЧАТ | ОТПРАВИТЕЛЬ | текст сообщения\n'+
      'ЧАТ — имя собеседника, с которым идёт переписка (не '+names.userName+' и не '+names.charName+', если переписка между ними двумя — напиши слово MAIN). ОТПРАВИТЕЛЬ — точное имя того, кто написал. Текст — дословно как в сюжете, без кавычек. Порядок — как в истории. Ничего не выдумывай; если сообщений нет — выведи одно слово NONE.\n\nИСТОРИЯ:\n'+text);
  }catch(e){ console.error(e); toast('Не получилось: ответ модели не пришёл'); return; }
  var rows = [];
  String(raw||'').split('\n').forEach(function(l){ var a = l.split('|').map(function(x){ return x.trim(); }); if (a.length >= 3 && a[2]) rows.push({ chat:a[0], from:a[1], text:a.slice(2).join('|').trim().slice(0,600) }); });
  if (!rows.length){ toast('Сообщений без плашек не нашлось'); return; }
  var added = 0, threads = {}, uLc = String(names.userName||'').toLowerCase(), cLc = String(names.charName||'').toLowerCase();
  for (var i = 0; i < rows.length; i++){
    var r = rows[i], clc = r.chat.toLowerCase(), tid;
    if (/^(main|мейн|основной|главный)$/i.test(r.chat) || clc === uLc || clc === cLc || !r.chat) tid = 'main';
    else tid = await findOrCreateContactByName(r.chat);
    if (!tid) continue;
    var flc = r.from.toLowerCase(), isChar = flc === cLc || flc === 'я';
    var norm = function(t){ return String(t||'').toLowerCase().replace(/\s+/g,' ').replace(/^[^:]{1,24}:\s*/,'').slice(0,80); };
    var did = await mutateMessages(tid, function(list){
      var ex = {}; list.forEach(function(m){ ex[norm(m.text)] = 1; });
      if (ex[norm(r.text)]) return false;
      list.push({ id: uid(), role: isChar ? 'char' : 'user', ts: Date.now() + i, hidden:false, text: r.text });
      return true;
    });
    if (did){ added++; threads[tid] = 1; }
  }
  if (added){ await rpSet('rp_msg_last_activity', Date.now()); toast('Нашла и добавила сообщений: '+added); } else toast('Всё найденное уже есть в чатах');
  if (onDone) onDone(added);
}
function msgScanSheet(container, afterFn){
  var dflt = cfg('scanDepth', 20);
  var bg = thSheet('<div style="font-weight:900;font-size:15px;margin-bottom:6px;">Умный разбор сюжета</div><div class="th_hint">Модель прочитает последние сообщения истории и подтянет в телефон: переписку без плашек, упущенные плашки мессенджера, новых НПС, номера телефонов и дату. Дубликаты не создаются. Глубину по умолчанию и автозапуск можно настроить в настройках плагина.</div>'+
    '<div class="th_btn" data-d="'+dflt+'" style="margin-top:10px;text-align:center;">Разобрать последние '+dflt+'</div>'+
    '<div class="th_row2" style="margin-top:8px;"><div class="th_btn ghost" data-d="10">10</div><div class="th_btn ghost" data-d="30">30</div><div class="th_btn ghost" data-d="60">60</div><div class="th_btn ghost" data-d="100">100</div></div>');
  bg.querySelectorAll('[data-d]').forEach(function(b){ b.addEventListener('click', async function(){ bg.remove(); await smartScan({ depth:+b.getAttribute('data-d') }); if (afterFn) afterFn(); }); });
}


var SCAN_BUSY = false;
function scanNorm(t){ return String(t||'').toLowerCase().replace(/^[^:]{1,24}:\s+/,'').replace(/[«»"'“”‘’`*_~\[\]()…\.,!?:;—–\-|]/g,' ').replace(/\s+/g,' ').trim(); }
function scanSame(a, b){ if (!a || !b) return false; if (a === b) return true; var sh = a.length < b.length ? a : b, lg = a.length < b.length ? b : a; return sh.length >= 14 && lg.indexOf(sh) >= 0; }
function scanSameName(a, b){
  a = String(a||'').trim().toLowerCase(); b = String(b||'').trim().toLowerCase(); if (!a || !b) return false; if (a === b) return true;
  var ta = a.split(/\s+/), tb = b.split(/\s+/), stem = function(t){ return t.length >= 5 ? t.slice(0, -1) : t; };
  if (ta.length === 1 || tb.length === 1) return stem(ta[0]) === stem(tb[0]) && ta[0].length >= 3;
  return stem(ta[0]) === stem(tb[0]) && stem(ta[ta.length-1]) === stem(tb[tb.length-1]);
}
async function scanThreadResolve(name, names){
  var uLc = String(names.userName||'').toLowerCase(), cLc = String(names.charName||'').toLowerCase(), n = String(name||'').trim(), lc = n.toLowerCase();
  if (!n || /^(main|мейн|основной|главный)$/i.test(n) || lc === uLc || lc === cLc || scanSameName(n, names.charName)) return 'main';
  return await findOrCreateContactByName(n);
}
async function smartScan(opts){
  opts = opts || {};
  if (SCAN_BUSY){ if (!opts.silent) toast('Разбор уже идёт…'); return null; }
  SCAN_BUSY = true;
  var res = { msgs:0, npcs:0, phones:0, date:false };
  try{
    var depth = Math.max(3, Math.min(100, opts.depth || cfg('scanDepth', 20)));
    var count = 0; try{ count = await PM.chat.count(); }catch(e){}
    if (!count){ if (!opts.silent) toast('В чате пока нет сообщений'); return null; }
    var end = count - 1, start = Math.max(0, end - depth + 1), msgs = [];
    try{ msgs = await PM.chat.slice([start, end]); }catch(e){}
    msgs = Array.isArray(msgs) ? msgs : [];
    if (!opts.silent) toast('Разбираю последние '+msgs.length+' сообщений…');
    var names = await getNames();
    var existing = [], tids = ['main'];
    (await rpGet('rp_npc_contacts', [])).concat(await rpGet('rp_contacts', [])).forEach(function(c){ if (c && c.id && tids.indexOf(c.id) < 0) tids.push(c.id); });
    for (var ti = 0; ti < tids.length; ti++){ (await rpGet(msgKey(tids[ti]), [])).forEach(function(m){ rpMsgNorms(m).forEach(function(t){ existing.push(t); }); }); }
    var tombS = await rpTombLoad();
    var isDup = function(text){ var n = scanNorm(rpMediaStrip(text)); if (!n) return true; if (n.length >= 4 && tombS.some(function(x){ return scanSame(x, n); })) return true; for (var i = 0; i < existing.length; i++){ if (scanSame(existing[i], n)) return true; } return false; };
    var addMsg = async function(tid, role, text){
      text = rpRawFix(String(text||'')).trim(); if (!tid || !text || isDup(text)) return false;
      existing.push(scanNorm(rpMediaStrip(text)));
      var base = Date.now();
      await mutateMessages(tid, function(list){ list.push({ id: uid(), role: role, ts: base + res.msgs, hidden:false, text: text.slice(0, 700), scan:true }); });
      res.msgs++; return true;
    };
    var userLc = String(names.userName||'').trim().toLowerCase();
    for (var mi = 0; mi < msgs.length; mi++){
      var m = msgs[mi]; if (!m || m.role !== 'assistant' || !m.content) continue;
      var blocks = []; try{ blocks = parseChatNBlocks(rpTagText(String(m.content))); }catch(e){}
      for (var bi = 0; bi < blocks.length; bi++){
        var block = blocks[bi], others = [];
        block.lines.forEach(function(l){ if (l.sender !== 'Я' && others.indexOf(l.sender) < 0) others.push(l.sender); });
        var isGroup = others.length > 1, tid;
        if (!others.length){ var cn = (block.chatName||'').trim(); tid = (cn && cn.toLowerCase() !== userLc) ? await findOrCreateContactByName(cn) : 'main'; }
        else if (!isGroup && others[0].trim().toLowerCase() === userLc) tid = 'main';
        else if (!isGroup) tid = await findOrCreateContactByName(others[0]);
        else tid = await findOrCreateContactByName(block.chatName || others.join(', '));
        if (!tid) continue;
        for (var li = 0; li < block.lines.length; li++){
          var l = block.lines[li], isChar = l.sender === 'Я';
          if (parseImagePayload(l.payload)) continue;
          var txt = formatChatPayload(l.payload); if (!isChar && isGroup) txt = l.sender+': '+txt;
          await addMsg(tid, isChar ? 'char' : 'user', txt);
        }
      }
    }
    var hdr = null; try{ hdr = await scanHdrClock(depth); }catch(e){}
    var clk = await rpGet('rp_rpclock', null);
    if (hdr && (hdr.date || hdr.day) && (!hdr.date || parseFreeTextDateToISO(hdr.date)) && (!clk || clk.date !== hdr.date)){ await rpSet('rp_rpclock', { date:hdr.date||'', day:hdr.day||'', source:'hdr', updatedAt:Date.now() }); res.date = true; }
    var text = msgs.map(function(m){
      var c = stripBrailleNoise(String(m.content||'')).replace(/<[^>]+>/g,' ').replace(/[ \t]+/g,' ').trim();
      return (m.role==='user' ? '['+names.userName+' — реплика игрока]' : '[рассказчик/'+names.charName+']')+' '+c;
    }).filter(function(l){ return l.length > 12; }).join('\n\n').slice(-16000);
    if (text){
      var chatsKnown = (await rpGet('rp_npc_contacts', [])).map(function(c){ return c.name; }).filter(Boolean);
      var npcsKnown = (await rpGet('rp_npcs2', [])).map(function(n){ return n.name; }).concat((await rpGet('rp_npc_contacts', [])).map(function(n){ return n.name; })).concat((await rpGet('rp_contacts', [])).map(function(n){ return n.name; })).concat((await rpGet('rp_pb_contacts', [])).map(function(n){ return n.name; }));
      var raw = '';
      try{
        raw = await callModel('Ты — внимательный разборщик ролевой истории. Ниже фрагмент между '+names.userName+' (игрок) и '+names.charName+' (персонаж). Найди ВАЖНОЕ для телефона героя и выведи по одной строке на находку, СТРОГО в форматах:\n'+
          'MSG | ЧАТ | ОТПРАВИТЕЛЬ | текст — любое сообщение в телефоне/смс/мессенджере/чате/голосовом, даже без плашек и тегов, а также реплики, которые выглядят как переписка (в кавычках, курсивом, после «написал(а)», «пришло сообщение»). ЧАТ — с кем идёт переписка (имя собеседника, не '+names.userName+' и не '+names.charName+'; если переписка между этими двумя — слово MAIN). Текст дословно, без кавычек.\n'+
          'Уведомления приложений, соцсетей, сервисов, ботов, доставок, банков, стримов и игр — НЕ MSG, пропускай их. Один и тот же человек или группа под разными обращениями и подписями (Мама, Мамуля, мамскин; Игорь Борисович, Борисыч Адвокат, Борисыч (Юрист); «Ночной Роблокс | общий-чат» и «Ночной Роблокс — общий-чат») — это ОДИН чат: пиши имя уже существующего чата символ в символ.\n'+
          (chatsKnown.length ? 'Уже существующие чаты (используй их имена точно): '+chatsKnown.slice(0,40).join(', ')+'.\n' : '')+
          'NPC | ФИО | кто это | отношения с '+names.userName+' или '+names.charName+' — второстепенный персонаж, который упомянут или появился (НЕ '+names.userName+' и НЕ '+names.charName+').\n'+
          'PHONE | имя | номер — если в тексте явно назван номер телефона.\n'+
          'DATE | дата и/или время в мире истории | день недели — одна строка, если из текста понятно какой сейчас день.\n'+
          (npcsKnown.length ? 'Уже известны (НЕ выводи их как NPC повторно): '+npcsKnown.slice(0,60).join(', ')+'.\n' : '')+
          'Ничего не выдумывай, не дублируй одно и то же. Если ничего нет — выведи слово NONE.\n\nИСТОРИЯ:\n'+text);
      }catch(e){ console.error('RP smartScan model failed', e); raw = ''; }
      var rows = String(raw||'').split('\n').map(function(l){ return l.split('|').map(function(x){ return x.trim().replace(/^[-*•\s]+/, function(m0, off){ return off === 0 ? '' : m0; }); }); });
      var newNpcs = [], dateRow = null, phones = [];
      for (var ri = 0; ri < rows.length; ri++){
        var a = rows[ri], kind = String(a[0]||'').replace(/[^A-Za-z]/g,'').toUpperCase();
        if (kind === 'MSG' && a.length >= 4 && a[3]){
          var tid2 = await scanThreadResolve(a[1], names), f = String(a[2]||'').trim().toLowerCase();
          var role = (f === String(names.charName||'').toLowerCase() || f === 'я' || scanSameName(a[2], names.charName)) ? 'char' : 'user';
          await addMsg(tid2, role, a.slice(3).join('|'));
        } else if (kind === 'NPC' && a[1]) newNpcs.push({ name:a[1].slice(0,60), about:(a[2]||'').slice(0,160), relation:(a[3]||'').slice(0,60) });
        else if (kind === 'PHONE' && a[1] && String(a[2]||'').replace(/\D/g,'').length >= 6) phones.push({ name:a[1], phone:a[2].slice(0,24) });
        else if (kind === 'DATE' && a[1] && !/неизвестно/i.test(a[1])) dateRow = { date:a[1], day:(a[2]||'').replace(/неизвестно/i,'') };
      }
      if (newNpcs.length){
        var npcs = await rpGet('rp_npcs2', []), changed = false;
        var pool = npcs.map(function(n){ return n.name; }).concat(npcsKnown);
        newNpcs.forEach(function(n){
          if (scanSameName(n.name, names.userName) || scanSameName(n.name, names.charName)) return;
          if (pool.some(function(k){ return scanSameName(k, n.name); })) return;
          pool.push(n.name); npcs.push({ id: uid(), name:n.name, about:n.about, relation:n.relation, source:'context', hidden:false, photo:null }); res.npcs++; changed = true;
        });
        if (changed) await rpSet('rp_npcs2', npcs);
      }
      if (phones.length){
        var all = await pbCollect();
        for (var pi = 0; pi < phones.length; pi++){
          var ct = all.filter(function(c){ return scanSameName(c.name, phones[pi].name); })[0];
          if (ct && ct.phone !== phones[pi].phone){ await pbSetOver(ct.key, { phone: phones[pi].phone }); res.phones++; }
        }
      }
      if (!res.date && !(hdr && (hdr.date || hdr.day)) && dateRow && parseFreeTextDateToISO(dateRow.date)){
        var clk2 = await rpGet('rp_rpclock', null);
        if (!clk2 || clk2.date !== dateRow.date){ await rpSet('rp_rpclock', { date:dateRow.date, day:dateRow.day, source:'context', updatedAt:Date.now() }); res.date = true; }
      }
    }
    if (res.date){ try{ await renderHomeClockText(); }catch(e){} }
    await rpSet('rp_scan_last', count);
    if (res.msgs){ await rpSet('rp_msg_last_activity', Date.now()); }
    var bits = [];
    if (res.msgs) bits.push('сообщений: '+res.msgs); if (res.npcs) bits.push('НПС: '+res.npcs); if (res.phones) bits.push('номеров: '+res.phones); if (res.date) bits.push('дата обновлена');
    if (bits.length) toast('Нашла — '+bits.join(', ')); else if (!opts.silent) toast('Нового не нашлось — всё уже на месте');
    return res;
  }catch(e){ console.error('RP smartScan failed', e); if (!opts.silent) toast('Разбор не удался: '+(e && e.message ? e.message : e)); return null; }
  finally{ SCAN_BUSY = false; }
}
async function maybeAutoScan(){
  try{
    if (!cfg('enabled', true) || !cfg('autoScan', false) || SCAN_BUSY) return;
    var count = await PM.chat.count(), last = await rpGet('rp_scan_last', null);
    if (last === null){ await rpSet('rp_scan_last', count); return; }
    if (count < last){ await rpSet('rp_scan_last', count); return; }
    if (count - last < Math.max(2, cfg('scanEvery', 8))) return;
    var r = await smartScan({ depth: cfg('scanDepth', 20), silent:true });
    if (r && r.msgs && panelOpen && currentScreen === 'messenger') openScreen('messenger');
    await relAutoUpdate();
  }catch(e){}
}
setInterval(maybeAutoScan, 20000);

