async function thWallApply(){
  var home = $('#rp_home'), root = $('#rp_root'); if (!home) return;
  var w = null; try{ w = await rpGet('rp_wall', null); }catch(e){}
  var src = '';
  if (w && w.id){
    if (w.id.indexOf('url:') === 0) src = w.id.slice(4);
    else { var lib = await thLib(); var it = lib.filter(function(x){ return x.id === w.id; })[0]; if (it) src = it.data; }
  }
  var oldVid = $('#rp_wall_video'), oldDim = $('#rp_wall_dim');
  if (oldVid) oldVid.remove();
  if (oldDim) oldDim.remove();
  if (!src){ home.style.background = ''; root.classList.remove('rp_has_wall'); return; }
  var dim = Math.max(0, Math.min(85, w.dim == null ? 30 : w.dim)) / 100;
  var safe = String(src).replace(/["'()\\\s]/g, function(c){ return encodeURIComponent(c); });
  if (/\.(mp4|webm|mov|m4v|ogv)(\?|$)/i.test(src)){
    home.style.background = '';
    var v = document.createElement('video');
    v.id = 'rp_wall_video'; v.src = src; v.muted = true; v.loop = true; v.autoplay = true; v.playsInline = true;
    var shade = document.createElement('div'); shade.id = 'rp_wall_dim'; shade.style.background = 'rgba(0,0,0,' + dim + ')';
    home.insertBefore(shade, home.firstChild); home.insertBefore(v, home.firstChild);
    try{ v.play(); }catch(e){}
  } else {
    home.style.background = 'linear-gradient(rgba(0,0,0,'+dim+'),rgba(0,0,0,'+dim+')), url("'+safe+'") center/cover no-repeat';
  }
  root.classList.add('rp_has_wall');
}
async function thSetWall(w){ await rpSet('rp_wall', w); await thWallApply(); }
async function thInit(){
  try{
    var t = await rpGet('rp_theme', null);
    if (t && t.vars){
      var root = $('#rp_root');
      TH_VARS.forEach(function(k){ if (t.vars[k]) root.style.setProperty('--'+k, t.vars[k]); });
      root.classList.toggle('rp_icons_accent', t.iconMode === 'accent'); root.classList.toggle('rp_flat', !!t.flat);
    }
  }catch(e){ console.error('RP theme init failed', e); }
  await thWallApply();
}
async function thApply(t){
  var root = $('#rp_root');
  TH_VARS.forEach(function(k){ if (t.vars && t.vars[k]) root.style.setProperty('--'+k, t.vars[k]); });
  root.classList.toggle('rp_icons_accent', t.iconMode === 'accent'); root.classList.toggle('rp_flat', !!t.flat);
  var patch = {};
  if (t.shape != null) patch.shape = t.shape;
  if (t.size) patch.size = t.size;
  if (Object.keys(patch).length) await hlSave(patch);
  if (t.custom && t.home){
    try{
      if (t.home.layout) await rpSet('rp_home_layout', t.home.layout);
      await rpSet('rp_home_order', t.home.order || []);
      await wgSaveList(t.home.wgts || []);
      await rpSet('rp_app_removed', t.home.removed || []);
    }catch(e){ console.error('RP theme home restore failed', e); }
  }
  if (t.custom){
    if (t.colors) await rpSet('rp_app_icon_colors', t.colors);
    if (t.names) await rpSet('rp_app_names', t.names);
    await rpSet('rp_theme_edit', t.id);
    await thSetWall(t.wall || null);
  }
  await rpSet('rp_theme', { id:t.id, name:t.name, vars:t.vars, iconMode:t.iconMode, flat:!!t.flat });
  await buildGrid();
}

async function thEditId(){ return await rpGet('rp_theme_edit', null); }
async function thSnapshotExtras(){
  var l = await hlGet();
  return { colors: await rpGet('rp_app_icon_colors', {}), names: await rpGet('rp_app_names', {}), iconMode: $('#rp_root').classList.contains('rp_icons_accent') ? 'accent' : 'app', shape:l.shape, size:l.size,
    home: { layout:l, order: await rpGet('rp_home_order', []), wgts: await wgList(), removed: await rpGet('rp_app_removed', []) } };
}
async function thSyncEdit(full){
  var id = await thEditId(); if (!id) return false;
  var list = await thCustomList(), t = list.filter(function(x){ return x.id === id; })[0];
  if (!t) return false;
  Object.assign(t, await thSnapshotExtras());
  if (full){ t.vars = thSnapshotVars(); var w = await rpGet('rp_wall', null); t.wall = w && w.id ? w : null; }
  await thCustomSave(list);
  return t;
}
async function thMarkCustom(){
  var cur = await rpGet('rp_theme', null);
  await rpSet('rp_theme', { id:'custom', name:'Своя', flat: $('#rp_root').classList.contains('rp_flat'), vars:thSnapshotVars(), iconMode: $('#rp_root').classList.contains('rp_icons_accent') ? 'accent' : 'app' });
}
function thPrevHtml(t, wallSrc){
  var v = t.vars;
  var ic = t.iconMode === 'accent' ? ['linear-gradient(160deg,'+v.accent2+','+v.accent+')','linear-gradient(160deg,'+v.accent2+','+v.accent+')','linear-gradient(160deg,'+v.accent2+','+v.accent+')','linear-gradient(160deg,'+v.accent2+','+v.accent+')'] : ['#5b8def','#ff4d6d','#9146ff','#0f7a4a'];
  var rad = t.shape === 'circle' ? '50%' : Math.round((t.shape||14)/2)+'px';
  var bg = wallSrc ? 'background:linear-gradient(rgba(0,0,0,.3),rgba(0,0,0,.3)),url(\''+String(wallSrc).replace(/["'()\\\s]/g, function(c){ return encodeURIComponent(c); })+'\') center/cover;' : 'background:linear-gradient(160deg,'+v.bg1+','+v.bg2+');';
  return '<div class="th_prev" style="'+bg+'color:'+v.text+';">'+
    '<div class="bar"><span>9:41</span><span>●●●</span></div>'+
    '<div class="ics">'+ic.map(function(c){ return '<i style="background:'+c+';border-radius:'+rad+';"></i>'; }).join('')+'</div>'+
    '<div class="wid" style="background:'+v.glass1+';border:1px solid '+v.border+';"></div></div>';
}
SCREENS.themes = {
  title: 'Темы',
  async render(container){
    container.style.flexDirection=''; container.style.height=''; container.style.minHeight='';
    container.style.padding = '12px 14px 18px';
    await thRender(container);
  }
};
async function thRender(container){
  var keep = container.scrollTop;
  backTarget = openHome;
  container.innerHTML = '';
  var tabs = el('div','th_tabs');
  tabs.innerHTML = [['themes','Каталог тем'],['studio','Создать тему']].map(function(t){ return '<div data-t="'+t[0]+'" class="'+(thTab===t[0]?'on':'')+'">'+t[1]+'</div>'; }).join('');
  container.appendChild(tabs);
  tabs.querySelectorAll('div').forEach(function(d){ d.addEventListener('click', function(){ thTab = d.getAttribute('data-t'); container.scrollTop = 0; thRender(container); }); });
  var body = el('div'); container.appendChild(body);
  if (thTab === 'themes') await thTabThemes(body, container);
  else await thTabStudio(body, container);
  if (currentScreen === 'themes') container.scrollTop = keep;
  if (thTab === 'studio') thStudioSync();
}
async function thStudioSync(){
  try{ var id = await thEditId(); if (id) await thSyncEdit(true); }catch(e){}
}
async function thCreateTheme(name){
  var l = await hlGet(), w = await rpGet('rp_wall', null);
  var t = { id:'c_'+uid(), name:name.slice(0,28), cat:'Мои', custom:true, desc:'Моя тема', flat: $('#rp_root').classList.contains('rp_flat'), vars: thSnapshotVars(),
    iconMode: $('#rp_root').classList.contains('rp_icons_accent') ? 'accent' : 'app', shape:l.shape, size:l.size,
    colors: await rpGet('rp_app_icon_colors', {}), names: await rpGet('rp_app_names', {}), wall: w && w.id ? w : null,
    home: { layout:l, order: await rpGet('rp_home_order', []), wgts: await wgList(), removed: await rpGet('rp_app_removed', []) } };
  var list = await thCustomList(); list.unshift(t);
  if (!(await thCustomSave(list))) return null;
  await rpSet('rp_theme', { id:t.id, name:t.name, vars:t.vars, iconMode:t.iconMode, flat:!!t.flat }); await rpSet('rp_theme_edit', t.id);
  return t;
}
var thStudioSub = 'look';
