      '<div style="display:flex;gap:6px;"><input class="rp_input" id="th_new_name" placeholder="Например: Ночной Токио" maxlength="28" style="flex:1;margin:0;"><div class="th_btn" id="th_new_go" style="padding:9px 12px;">Создать</div></div>';
