function applyTogglePosition(r, b){
  var root = $('#rp_root');
  var w = window.innerWidth || 360, h = window.innerHeight || 640;
  r = Math.max(4, Math.min(w - 36, r));
  b = Math.max(4, Math.min(h - 150, b));
  root.style.right = r+'px';
  root.style.bottom = b+'px';
}
function toggleSideR(side){ var w = window.innerWidth || 360; return side === 'l' ? w - 40 : 10; }
function applyToggleSaved(p){
  var root = $('#rp_root');
  var w = window.innerWidth || 360;
  var side = p && (p.side === 'l' || p.side === 'r') ? p.side : (p && typeof p.r === 'number' && p.r + 15 > w / 2 ? 'l' : 'r');
  root.setAttribute('data-side', side);
  applyTogglePosition(toggleSideR(side), p && typeof p.b === 'number' ? p.b : 110);
}
(function(){
  var dragging = false, moved = false, sx = 0, sy = 0, sr = 10, sb = 110, root = $('#rp_root');
  var toggle = $('#rp_toggle');
  function cur(){ return { r: parseFloat(root.style.right) || 10, b: parseFloat(root.style.bottom) || 110, side: root.getAttribute('data-side') || 'r' }; }
  function snap(){
    var c = cur(), w = window.innerWidth || 360;
    var side = c.r + 15 > w / 2 ? 'l' : 'r';
    root.setAttribute('data-side', side);
    root.style.transition = 'right .22s cubic-bezier(.2,1,.3,1), bottom .22s cubic-bezier(.2,1,.3,1)';
    applyTogglePosition(toggleSideR(side), c.b);
    setTimeout(function(){ root.style.transition = ''; }, 260);
  }
  toggle.addEventListener('pointerdown', function(e){
    dragging = true; moved = false; sx = e.clientX; sy = e.clientY;
    var c = cur(); sr = c.r; sb = c.b;
    try{ toggle.setPointerCapture(e.pointerId); }catch(_){}
  });
  toggle.addEventListener('pointermove', function(e){
    if (!dragging) return;
    var dx = e.clientX - sx, dy = e.clientY - sy;
    if (!moved && Math.abs(dx) + Math.abs(dy) < 8) return;
    moved = true;
    applyTogglePosition(sr - dx, sb - dy);
  });
  async function end(e){
    if (!dragging) return;
    dragging = false;
    try{ toggle.releasePointerCapture(e.pointerId); }catch(_){}
    if (moved){ snap(); var c = cur(); await rpSet('rp_toggle_pos', { side: c.side, b: c.b }); setTimeout(function(){ moved = false; }, 0); }
  }
  toggle.addEventListener('pointerup', end);
  toggle.addEventListener('pointercancel', end);
  window.addEventListener('resize', function(){ var c = cur(); applyTogglePosition(toggleSideR(c.side), c.b); });
  toggle.addEventListener('click', function(){
    if (moved){ moved = false; return; }
    if (panelOpen) closePanel(); else openPanel();
  });
  toggle.addEventListener('dblclick', async function(){
    root.setAttribute('data-side', 'r');
    applyTogglePosition(10, 110);
    await rpSet('rp_toggle_pos', { side: 'r', b: 110 });
  });
})();

